// ---- the stand-in for sagebrush-agent (0.3.0, lib/server.mjs at cc11a8a): one paired page at a time (a second upgrade
// gets 409 before the upgrade while a page is paired, :136); the session secret from a code hello, a session hello
// checked against it; a refused hello answered, then the socket closed (:192-193); chats by conversation. Unlike it,
// the code here stays valid (it's single use there, :188): the cases that pair again use the same one.
export function fakeAgent({ name = "Claude", client = "claude-agent-sdk" } = {}) {
  const A = { secret: randomBytes(32).toString("base64url"), live: new Set(), rejected: 0, upgrades: 0, hellos: 0, notes: [], resume: new Map(), silent: false, port: 0, server: null, pending: new Map(), n: 0, page: null, delay: 0 };
  const start = (port) => {
    A.server = Bun.serve({
      port,
      hostname: "127.0.0.1",
      fetch(req, srv) {
        if (new URL(req.url).pathname !== "/sagebrush") return new Response("not here", { status: 404 });
        // (as sagebrush-agent 0.3.0's verifyClient, lib/server.mjs:136 at cc11a8a: 409 while a page is PAIRED)
        if (A.page) { A.rejected++; return new Response("already paired", { status: 409 }); }
        return srv.upgrade(req) ? undefined : new Response("no", { status: 400 });
      },
      websocket: {
        open(ws) { A.upgrades++; A.live.add(ws); },
        message(ws, data) {
          const m = JSON.parse(String(data));
          if (m.method === "hello") {
            A.hellos++;
            if (A.silent) return; // (the 10 s bound: an agent that never answers)
            const p = m.params ?? {};
            const good = typeof p.code === "string" ? p.code === "123456" : p.session === A.secret;
            if (!good) {
              // (and the socket closed, as sagebrush-agent does after a refused hello: a new code can then connect)
              ws.send(JSON.stringify({ jsonrpc: "2.0", id: m.id, error: { code: -32001, message: "refused", data: { code: "refused", message: "unknown session: a new code is needed" } } }));

// "Chat here", the Agents page's own: your computers in the Connect dialog, each with Chat here, and the
// attempt it starts: a leg to that computer's agent (agent-relay.ts), then a pairing over it (agent-ui.ts's adopt) and
// the grant dialog. Kept out of agent-ui.ts, which every page's pairing chunk carries; only this page has it.

import type { AgentLink, AgentPairing } from "../workspace/agent-pair";
import { NOT_ENABLED } from "../workspace/remote-runners";

/** The Connect dialog's words for your computers, word for word as reviewed. */
export const RUNNER_COPY = {
  heading: "Or chat with an agent on one of your computers:",
  button: "Chat here",
  finding: "Finding your computers…",
  none: "None of your computers is set up for this. On one, run: sagebrush remote login",
  // (an account the site doesn't let connect a computer: this sentence alone, before any command (the server's words))
  notEnabled: NOT_ENABLED,
  failed: (reason: string) => `Your computers: ${reason}`,
  signIn: "Sign in",
};
/** How long a computer's agent has to say it's ready (agent.ready) after the leg's hello: its process starting. */
export const READY_MS = 30_000;
/** A computer whose runner isn't connected yet (its leg unreachable): Chat here waits for it this long, trying again
 * every RETRY_MS, as a runner just started takes a few seconds to reach the relay. */
export const WAIT_MS = 60_000;
export const RETRY_MS = 2_000;

type Runner = { remote_id: string; name: string };
type End = { kind: string; why: string };
/** What the attempt needs: your computers, a leg to one (open, or ended with why), and the page's words for it. */
export type ChatHereHost = {
  list(): Promise<{ available: boolean; runners: Runner[] }>;
  open(r: Runner): Promise<{ link: AgentLink; ended: End | null }>;
  onConnecting(r: Runner): void;
  /** its runner isn't connected yet: waiting for it */
  onWaiting(r: Runner): void;
  onFailed(r: Runner, e: End): void;
};
/** What it needs of the page's pairing (agent-ui.ts's mountAgentPairing). */
type Ui = { adopt(link: AgentLink, computer: string): AgentPairing; grant(p: AgentPairing): Promise<void>; live(): boolean; readonly pairing: AgentPairing | null };

const CSS = `
.sbag-box .runners { display: grid; gap: 6px; border-top: 1px solid #e6e9e1; padding-top: 10px; }
.sbag-box .runner { display: flex; gap: 8px; align-items: center; justify-content: space-between; }
`;

export function chatHere(host: ChatHereHost, ui: () => Ui | null) {
  if (!document.getElementById("sbag-runners-css")) document.head.append(Object.assign(document.createElement("style"), { id: "sbag-runners-css", textContent: CSS }));
  const el = <K extends keyof HTMLElementTagNameMap>(tag: K, props: Partial<HTMLElementTagNameMap[K]> = {}, ...kids: (Node | string)[]) => { const e = Object.assign(document.createElement(tag), props); e.append(...kids); return e; };
  // (each Chat here is one attempt: a newer one, or a pairing adopted meanwhile, supersedes it)
  let attempt = 0;

  async function start(r: Runner) {
    const u = ui();
    if (!u) return;
    const mine = ++attempt;
    host.onConnecting(r);
    let opened: { link: AgentLink; ended: End | null };
    const deadline = Date.now() + WAIT_MS;
    for (;;) {
      try { opened = await host.open(r); } catch (e) { if (mine === attempt) host.onFailed(r, { kind: "lost", why: String((e as Error)?.message ?? e) }); return; }
      if (mine !== attempt || u.live()) { opened.link.close(); return; }

// The connect page's Copy buttons (web/agents/connect/index.html): each copies the command beside it. A file of its
// own, so the page needs no inline script (the site's policy for /agents/* is script-src 'self'). Without it the buttons
// stay hidden and a click on a command selects it whole (user-select: all).
for (const b of document.querySelectorAll("button.copy")) {
  const pre = b.parentElement?.querySelector("pre");
  if (!pre || !navigator.clipboard) continue;
  b.hidden = false;
  b.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(pre.textContent.trim());
      b.textContent = "Copied";
    } catch {
      b.textContent = "Select it, then copy";
    }
    setTimeout(() => (b.textContent = "Copy"), 2000);
  });
}

// A scripted stand-in for Claude, for the preview: it produces the same turn
// events a real agent's turn would (streamed text, thinking, tool calls with
// live output, an approval, diffs and artifacts), on a timer, with nothing
// sent anywhere. Each prompt picks a scenario by its words.

import type { Draft } from "../workspace/agent-chat/events";

export type { Draft };

export interface FakeTurn {
  // stops the turn at its next step; it finishes as interrupted
  interrupt(): void;
  // answers an open approval
  answer(id: string, approve: boolean): void;
  done: Promise<void>;
}

class Interrupted extends Error {}

export function startFakeTurn(prompt: string, emit: (d: Draft) => void, speed = 1): FakeTurn {
  let stopped = false;
  const waiting = new Map<string, (approve: boolean) => void>();
  const sleep = (ms: number) =>
    new Promise<void>((resolve, reject) => {
      const t = setTimeout(() => (stopped ? reject(new Interrupted()) : resolve()), ms / speed);
      if (stopped) {
        clearTimeout(t);
        reject(new Interrupted());
      }
    });
  const step = () => {
    if (stopped) throw new Interrupted();
  };
  let messages = 0;
  let calls = 0;
  const say = async (text: string) => {
    const id = `m${messages++}`;
    emit({ type: "message_revised", message: id, revision: 1 });
    for (const piece of chunks(text)) {
      await sleep(18 + Math.random() * 30);
      emit({ type: "text_delta", message: id, revision: 1, text: piece });
    }
  };
  const think = async (text: string) => {
    for (const piece of chunks(text)) {
      await sleep(10 + Math.random() * 15);
      emit({ type: "thinking_delta", text: piece });
    }
  };
  const tool = async (
    tool: string,
    name: string,
    summary: string,
    work: (call: string) => Promise<{ status: string; summary?: string; diff?: { path: string; before: string; after: string } }>,
  ) => {
    const call = `t${calls++}`;
    const started = Date.now();
    emit({ type: "tool_call_started", call, tool, name, summary });
    const r = await work(call);
    emit({ type: "tool_call_finished", call, status: r.status, summary: r.summary, duration_ms: Date.now() - started, diff: r.diff });

// The agents page's layout (web/agents): the body classes that place the chat, the artifact pane and full screen, and
// the two resizable columns (the chat list and the artifact pane; William A1 + A10, the layout plan r3 PR 2).
// Widths are two CSS variables on body, --sb-side-w and --sb-pane-w, which index.html reads only above 900 px and
// outside full screen, so the narrow overlay and full screen keep their own layout. Nothing here sets a width.
import type { Artifact } from "../workspace/agent-chat/events";

/** The pane-state classes on body: an artifact shown, and full screen. (A notebook no longer widens its pane: A10.) */
export function applyPaneClasses(a: Artifact | undefined, fullscreen: boolean) {
  document.body.classList.toggle("has-artifact", !!a);
  document.body.classList.toggle("fullscreen", !!a && fullscreen);
}

export const LAYOUT_KEY = "sb-agents-layout-v1";
const SIDE = { min: 180, max: 480, default: 250 };
const CHAT_MIN = 420;
const PANE_MIN = 320;
const WIDE = 901; // (the narrow overlay is 900 px and below: index.html's @media)
const STEP = 16;

type Stored = { side: number; pane: number };

/** A stored layout, or null: exactly {side, pane}, two finite numbers in 0..4096; any other shape is ignored whole. */
export function parseLayout(raw: string | null): Stored | null {
  if (raw == null) return null;
  let v: unknown;
  try {
    v = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!v || typeof v !== "object" || Array.isArray(v)) return null;
  const keys = Object.keys(v).sort();
  if (keys.length !== 2 || keys[0] !== "pane" || keys[1] !== "side") return null;
  const { side, pane } = v as Record<string, unknown>;
  const ok = (n: unknown): n is number => typeof n === "number" && Number.isFinite(n) && n >= 0 && n <= 4096;
  return ok(side) && ok(pane) ? { side, pane } : null;
}

function readStored(): Stored | null {
  try {
    return parseLayout(localStorage.getItem(LAYOUT_KEY));
  } catch {
    return null; // (storage unavailable: the defaults)
  }
}

// what the person asked for (null: the default), and what is shown after the clamps
let want: { side: number | null; pane: number | null } = { side: null, pane: null };
let shown = { side: SIDE.default, pane: 0, sideMax: SIDE.max, paneMax: 0, collapsed: false, open: false };

// (the test seam, only with ?layout-test in the URL: the animation-frame function and the counts of applies and writes)
let frame: (cb: () => void) => unknown = (cb) => requestAnimationFrame(cb);
const stats = { applies: 0, writes: 0 };

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

/** The widths for this window: the chat keeps 420 px first, the pane 320, and the sidebar gets what it can (180-480);
 * when 180 + 420 + 320 doesn't fit beside an open pane, the sidebar collapses to the narrow overlay's. */
function compute() {
  const vw = innerWidth;

// A notebook artifact: a workspace .ipynb file shown and run in the artifact pane with the notebook component
// (/sagebrush-notebook.js, loaded on first use; its kernel worker, /sagebrush-worker.js, only on the first Run).
// The artifacts plan (r2 + r2.1): only the person's Run runs code (the component is created non-reactive, the host
// never calls applyEdits); the store is the notebook page's own IdbStore, bound to the document's ref, so a save
// can never reach another document at the same path; under sync's journal, the page's own journal store, with its
// writer lock: the pane writes while it holds it, else follows the tab that does, as another tab of the page would
// (web/page/handover.ts), and an agent's edit asks for it; remote pictures wait for a click whatever the document says.
import { writerHandover } from "../page/handover";
import type { Workspace } from "../workspace/api";
import { canonical, cellForm, preflight, type NotebookEdit } from "../workspace/notebook-edit";

// (stores.js's FENCE, the workspace's record in the notebooks store; test-agents-artifacts checks they're equal)
export const FENCE = "__sagebrush-workspace__";
// (the site's root: this page is /agents/agents.js; built as a URL so the bundler leaves the import to the browser)
const SITE = new URL("../", import.meta.url);

export type NotebookUi = {
  /** The pane's saved indicator. */
  saved(text: string): void;
  /** A bar over the notebook (null: none): its text, its kind, and buttons. */
  bar(b: { kind: "conflict" | "refused" | "readonly" | "gone"; text: string; actions?: { label: string; run: () => void }[] } | null): void;
  /** The paired agent's name, for the written-by label. */
  agentName(): string;
  /** A cell started or stopped running (the tab's running mark). */
  running(on: boolean): void;
  /** Said after the notebook closed (its last changes kept as a copy). */
  notice(text: string): void;
};

export type NotebookHost = {
  el: HTMLElement;
  /** Settles when the notebook is shown, or its mount stopped (disposed, or refused: said in its bar). */
  ready: Promise<void>;
  /** Saves made and kept (or an error). */
  flush(): Promise<void>;
  /** Closing (ART-C2 r3): what was edited is saved (CLOSE_SAVE_MS at most), then nothing more is written from here; if
   * the latest content isn't in the store (not saved, refused, let go), it is kept as a copy first. True: closed;
   * false: neither saved nor kept, so the notebook stays, with its bar saying so (the only copy is never dropped). */
  release(): Promise<{ ok: true } | { ok: false; why: string }>;
  /** Closed without keeping anything: detached, stopped, its kernel ended; nothing it started writes afterwards. */
  dispose(): Promise<void>;
  /** After a failed close: the content it kept frozen, as a file to download (.ipynb), or null. */
  download(): { name: string; text: string; type: string } | null;
  isRunning(): boolean;
  /** An agent's edit by cell (A12 step 1): checked whole against what's shown, then applied, then saved once; or
   * refused with nothing changed.  Resolves once the change is saved (or says why not). */
  /** `hold` (a notebook in /Branches: the branches' rule, chat plan PR 3): asked after every wait, right before the
   * synchronous apply, holding the workspace's lock until it is released after the apply; it rejects to refuse. */
  edit(e: NotebookEdit, may: () => boolean, hold?: () => Promise<() => void>): Promise<EditResult>;
  hidden(on: boolean): void;
  interrupt(): void;
  copyText(): string;
};

type Nb = any; // (the component is plain JS: its API is web/notebook/README.md's)
export type EditResult = { ok: true; inserted: string[]; rev?: number } | { ok: false; code: "conflict" | "invalid" | "busy"; why: string; ids?: string[] };

/** The cells the agent wrote, by id: their source when it wrote them (a label shows while a cell still has it and hasn't run). */
export type AgentCells = Map<string, string>;

// The agents chat preview (web/agents): a full-page chat with artifacts beside
// it, the model claude.ai and chatgpt.com have converged on. The chat is
// primary; an artifact opens floating to the right, or full screen. This
// preview drives it with a scripted agent (fake-agent.ts), or with Claude on
// the person's own computer (sagebrush-agent, paired over the loopback
// address like any agent: design/workspace-agent-protocol.md), which speaks
// the same turn events (events.ts). Files the agent writes are workspace
// files (this browser's workspace), shown and edited beside the chat.
// Threads are kept in this browser's localStorage.

// (first: the pairing code leaves the address bar before anything else runs)
import "../workspace/pair-link";
import { BlockEditor } from "../board/blocks";
