// The reactive notebook's analyzer (src/dataflow.ts) in a Web Worker of its
// own: the names each cell defines and references, for the dependency graph
// (src/notebook-graph.ts).  Not in the page, whose script stays small, and
// not in the interpreter's worker, which is busy while a cell runs.
//
// In:  {id, code, mode}   mode: "python" | "sage" | "magma" | "matlab"
// Out: {id, defs, refs, deleted, mutations} (arrays of names), or {id, error: {kind, message}}
//      (kind "syntax" or "import-star")
//      {id, rename: {name, cells: [{id, code, defines, reads}], taken, mode, sep?}}
//        -> {id, sources: [[cell id, new code]] | null}: the fix of a name
//        defined by several cells (src/rename.ts)
import { analyzeCell, ImportStarError } from "../src/dataflow";
import { renameRedefinitions } from "../src/rename";

self.onmessage = (ev: MessageEvent) => {
  const { id, code, mode, rename } = ev.data;
  if (rename) {
    let sources: [string, string][] | null = null;
    try {
      const r = renameRedefinitions(rename.cells, rename.name, new Set(rename.taken), rename.mode, rename.sep ?? "_");
      sources = r ? [...r] : null;
    } catch {}
    postMessage({ id, sources });
    return;
  }
  try {
    const a = analyzeCell(code, "c", { mode });
    postMessage({ id, defs: [...a.defs], refs: [...a.refs], deleted: [...a.deleted], mutations: [...(a.mutations ?? [])], imports: [...(a.imports ?? [])] });
  } catch (e: any) {
    postMessage({ id, error: { kind: e instanceof ImportStarError ? "import-star" : "syntax", message: String(e?.message ?? e) } });
  }
};

// atlas.js: what the atlas's pages do in the browser.  Pages are complete
// without it; it adds the engine (a Web Worker running the notebook's
// WebAssembly build): computing spaces that are not stored, recomputing
// stored ones against their data, Sato-Tate with more primes, and WebMCP
// tools for agents.
import { BOUND, type Estimate, type Space, divisors, fmtBytes, fmtSeconds, parseLabel, sameMath, spaceFromEngine, spaceLabel } from "./model.ts";
import { apCost, satoTateSvg } from "./plot.ts";

const href = (label: string) => `/atlas/mf/${label}`;
// KaTeX and the page templates, only when a computed space is shown
const render = () => import("./render.ts");

const $ = (s: string) => document.querySelector(s) as HTMLElement | null;

// ---- the engine
let worker: Worker | null = null, seq = 0;
const waiting = new Map<number, [(v: any) => void, (e: Error) => void]>();
function engineWorker(): Worker {
  if (worker) return worker;
  worker = new Worker("/atlas/atlas-engine.js", { type: "module" });
  worker.onmessage = (ev) => {
    const w = waiting.get(ev.data.id);
    if (!w) return;
    waiting.delete(ev.data.id);
    if (ev.data.reply.error) w[1](new Error(ev.data.reply.error));
    else w[0](ev.data.reply.ok);
  };
  return worker;
}
function call(req: object): Promise<any> {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    waiting.set(id, [resolve, reject]);
    engineWorker().postMessage({ id, req });
  });
}
function stop() {
  worker?.terminate();
  worker = null;
  for (const [, [, reject]] of waiting) reject(new Error("stopped"));
  waiting.clear();
}

/** The newspace N.k.a, computed here exactly as the atlas computes it. */
async function computeSpace(n: number, k: number): Promise<Space> {
  const t = performance.now();
  const dims = await call({ fn: "dims", n, k });
  const newDim = new Map<number, number>();
  for (const m of divisors(n)) if (m < n) newDim.set(m, (await call({ fn: "dims", n: m, k })).new);
  const nf = await call({ fn: "newforms", n, k, bound: BOUND });
  const sp = spaceFromEngine(n, k, dims, nf, (m) => newDim.get(m) ?? 0, (performance.now() - t) / 1000);
  sp.computed = "browser";
  return sp;
}

/** The cost model's prediction (engine/modsym/src/estimate.rs). */
async function estimate(n: number, k: number): Promise<Estimate> {
  const e = await call({ fn: "estimate_newforms", n, k, bound: BOUND });
  return { seconds: e.seconds, low: e.seconds_low, high: e.seconds_high, bytes: e.bytes };
}

// A Web Worker running Sagebrush's engine (/sagebrush-engine.wasm, the
// notebook's): {id, req} -> {id, reply}, reply = {ok} | {error}.
let E: any = null;

async function engine() {
  if (E) return E;
  const res = await fetch("/sagebrush-engine.wasm");
  if (!res.ok) throw new Error(`could not load the engine (HTTP ${res.status})`);
  const { instance } = await WebAssembly.instantiate(await res.arrayBuffer(), { sagebrush: { interrupted: () => 0 } });
  return (E = instance.exports);
}

self.onmessage = async (ev: MessageEvent) => {
  const { id, req } = ev.data;
  try {
    const e = await engine();
    const b = new TextEncoder().encode(JSON.stringify(req));
    const p = e.sb_alloc(b.length);
    new Uint8Array(e.memory.buffer, p, b.length).set(b);
    const r = e.sb_call(p, b.length);
    const reply = JSON.parse(new TextDecoder().decode(new Uint8Array(e.memory.buffer, r, e.sb_reply_len())));
    e.sb_free(p, b.length);
    postMessage({ id, reply });
  } catch (err) {
    postMessage({ id, reply: { error: String((err as Error)?.message ?? err) } });
  }
};

