// ---- math: TeX rendered by KaTeX (in the Worker for stored pages, so the
// page needs no script for it; memoized, since labels repeat)
const memo = new Map<string, string>();
/** Inline math from TeX. */
export function m(tex: string): string {
  let h = memo.get(tex);
  if (h === undefined) {
    h = katex.renderToString(tex, { throwOnError: false, output: "htmlAndMathml" });
    if (memo.size > 20000) memo.clear();
    memo.set(tex, h);
  }
  return h;
}
const sgn = (n: number) => m(n > 0 ? "+1" : "-1");
const bigTex = (s: string) => s; // decimal strings are TeX as they are

/** TeX for c[0] + c[1] x + ..., highest degree first. */
export function polyTex(c: string[], v = "x"): string {
  let s = "";
  for (let i = c.length - 1; i >= 0; i--) {
    const a = c[i];
    if (a === "0") continue;
    const neg = a.startsWith("-"), abs = neg ? a.slice(1) : a;
    const mono = i === 0 ? "" : i === 1 ? v : `${v}^{${i}}`;
    const coef = abs === "1" && i > 0 ? "" : abs;
    s += s === "" ? (neg ? "-" : "") + coef + mono : ` ${neg ? "-" : "+"} ` + coef + mono;
  }
  return s || "0";
}

/** TeX for sum a_n q^n + O(q^prec) from a_1, a_2, ... */
export function qexpTex(a: string[], prec: number): string {
  let s = "";
  for (let n = 1; n < prec && n <= a.length; n++) {
    const x = a[n - 1];
    if (x === "0") continue;
    const neg = x.startsWith("-"), abs = neg ? x.slice(1) : x;
    const t = (abs === "1" ? "" : abs) + (n === 1 ? "q" : `q^{${n}}`);
    s += s === "" ? (neg ? "-" : "") + t : ` ${neg ? "-" : "+"} ` + t;
  }
  return (s ? s + " + " : "") + `O(q^{${prec}})`;
}
export const polyHtml = (c: string[]) => m(polyTex(c));
export const qexpHtml = (a: string[], prec: number) => m(qexpTex(a, prec));

const factorTex = (n: number) => (n === 1 ? "1" : factorInt(n).map(([p, e]) => (e > 1 ? `${p}^{${e}}` : String(p))).join(" \\cdot "));

// A local server for the atlas, like the site's Worker: static files from
// web/dist, atlas pages from web/atlas/server.ts.
//   node web/atlas/serve.mjs [PORT]      (after bun web/build.ts)
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { join, extname, normalize } from "node:path";
import { handleAtlas } from "./server.ts";

const dist = join(import.meta.dirname, "..", "dist");
const port = +(process.argv[2] ?? 8766);
const TYPES = { ".html": "text/html; charset=utf-8", ".js": "text/javascript", ".json": "application/json", ".wasm": "application/wasm", ".txt": "text/plain; charset=utf-8", ".css": "text/css", ".woff2": "font/woff2" };
async function asset(path) {
  let p = normalize(decodeURIComponent(path.split("?")[0]));
  if (p.endsWith("/")) p += "index.html";
  try {
    return new Response(await readFile(join(dist, p)), { headers: { "content-type": TYPES[extname(p)] ?? "application/octet-stream" } });
  } catch {
    return new Response("not found", { status: 404 });
  }
}
createServer(async (req, res) => {
  const url = new URL(req.url, `http://localhost:${port}`);
  const request = new Request(url, { headers: req.headers });
  let r = await asset(url.pathname);
  // (every static file is cross-origin isolated on the site, by web/_headers;
  // the atlas's own pages must say so themselves, as there)
  const isolated = r.status === 404 ? {} : { "cross-origin-opener-policy": "same-origin", "cross-origin-embedder-policy": "require-corp" };
  if (r.status === 404) r = (await handleAtlas(request, asset)) ?? r;
  res.writeHead(r.status, { ...isolated, ...Object.fromEntries(r.headers) });
  res.end(Buffer.from(await r.arrayBuffer()));
}).listen(port, () => console.log(`http://localhost:${port}/atlas/`));

