      if (ans.length > ASK_LIMITS.options) return `its answer lists more than ${ASK_LIMITS.options} values`;
      const seen = new Set<unknown>();
      for (const v of ans) {
        const why = among(v);
        if (why) return why;
        if (seen.has(v)) return `${show(v)} is in its answer twice`;
        seen.add(v);
      }
      return null;
    }

