const starts = (l: string) => FENCE.test(l) || MATH.test(l) || HEADING.test(l) || ITEM.test(l) || QUOTE.test(l);

/** What a block is, from its first line. */
export function kindOf(src: string): BlockKind {
  const l = src.split("\n", 1)[0];
