// The share database's migrations, in the order they are applied.  Core's web/share/migrations (MIT) and this
// directory's migrations (MS-RSL) share one numbering, so the two are merged by file name.  A file without a
// four-digit number, a number used twice, or a number missing from the sequence (0001 up) is an error: none is
// skipped or reordered.  The tests and the dev server read the list here; the deploy applies the same order.
import { readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const MIGRATION_DIRS = [join(here, "../../share/migrations"), join(here, "migrations")];

/** The .sql files of `dirs`, each { name, path }, merged in name order; throws on a bad, repeated or missing number. */
export function migrations(dirs = MIGRATION_DIRS) {
  const all = dirs.flatMap((d) => readdirSync(d).filter((f) => f.endsWith(".sql")).map((name) => ({ name, path: join(d, name) })));
  all.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  all.forEach((m, i) => {
    const n = /^(\d{4})_[^/]+\.sql$/.exec(m.name)?.[1];
    if (!n) throw new Error(`a migration without a four-digit number: ${m.path}`);
    if (i > 0 && all[i - 1].name.slice(0, 4) === n) throw new Error(`two migrations numbered ${n}: ${all[i - 1].path} and ${m.path}`);
    if (Number(n) !== i + 1) throw new Error(`migration ${String(i + 1).padStart(4, "0")} is missing (next: ${m.path})`);
  });
  return all;
}

// The UTC periods active-user counting files by (active-users plan r2 §1.1, §1.2): the day, the ISO week (Monday
// 00:00 UTC) and the calendar month an instant falls in, their starts, and the starts of the next ones.  One function
// for the account counter's flags (A1) and the browser answer's durations, so the two can't disagree.  Pure: the
// caller passes the time (seconds), from its injectable clock.

export interface Periods {
  /** "YYYY-MM-DD" */
  day: string;
  dayStart: number;
  weekStart: number;
  monthStart: number;
  nextDay: number;
  nextWeek: number;
  nextMonth: number;
}

const DAY = 86_400;

export function periods(t: number): Periods {
  const d = new Date(t * 1000);
  const y = d.getUTCFullYear(), m = d.getUTCMonth();
  const dayStart = Date.UTC(y, m, d.getUTCDate()) / 1000;
  // (ISO: Monday is the first day of the week; getUTCDay() is 0 on Sunday)
  const weekStart = dayStart - ((d.getUTCDay() + 6) % 7) * DAY;
  const monthStart = Date.UTC(y, m, 1) / 1000;
  return {
    day: d.toISOString().slice(0, 10),
    dayStart,
    weekStart,
    monthStart,
    nextDay: dayStart + DAY,
    nextWeek: weekStart + 7 * DAY,
    nextMonth: Date.UTC(y, m + 1, 1) / 1000,
  };
}

// Runs one of web/share's MIT test suites against this directory's share server (MS-RSL), never a copy of it:
// web/share/serve-dev.mjs starts SHARE_DEV_ENTRY (test-entry.ts here) with SHARE_DEV_MIGRATIONS (the merged list,
// migrations.mjs) and checks, on that instance, that it is the hosted variant.  The run passes only if the suite exits 0,
// printed its completion line, and the server printed that it was the hosted variant with exactly the merged migrations,
// in order: a suite that never started its server, or returned early, fails here.
import { spawnSync } from "node:child_process";
import { basename, dirname, isAbsolute, join } from "node:path";
import { fileURLToPath } from "node:url";
import { migrations } from "./migrations.mjs";

const here = dirname(fileURLToPath(import.meta.url));

/** The verdict on a finished run: null when it passed, or why not. */
export function verdict({ status, stdout }, done, names) {
  if (status !== 0) return `the suite exited ${status}`;
  const lines = stdout.split("\n");
  const variant = lines.filter((l) => l.startsWith("share dev server: "));
  if (variant.length === 0) return "the suite never started the share dev server";
  const want = `share dev server: the hosted variant; migrations applied: ${names.join(",")}`;
  if (variant.some((l) => l !== want)) return `the server wasn't the hosted variant with the merged migrations: ${variant.find((l) => l !== want)}`;
  const end = lines.findLast((l) => done.test(l));
  if (!end) return "the suite's completion line is missing";
  const n = /(\d+)/.exec(end)?.[1];
  if (n !== undefined && Number(n) === 0) return "the suite ran no checks";
  return null;
}

/** Runs `suite` (absolute, or relative to this directory) with the hosted variant and exits with the verdict. */
export function runOnHosted(suite, done, { entry = join(here, "test-entry.ts"), list = migrations().map((m) => m.path) } = {}) {
  const env = { ...process.env, SHARE_DEV_ENTRY: entry, SHARE_DEV_MIGRATIONS: JSON.stringify(list), SHARE_DEV_EXPECT: "hosted" };
  delete env.SHARE_URL; // (a remote URL would skip the dev server: this run is about this directory's server)
  const r = spawnSync(process.execPath, [isAbsolute(suite) ? suite : join(here, suite), ...process.argv.slice(2)], { env, encoding: "utf8", stdio: ["inherit", "pipe", "inherit"], maxBuffer: 1 << 28 });
  process.stdout.write(r.stdout ?? "");
  const why = verdict({ status: r.status, stdout: r.stdout ?? "" }, done, list.map((p) => basename(p)));
  console.log(why ? `FAIL ${basename(suite)} on the hosted variant: ${why}` : `${basename(suite)} passed on the hosted variant`);
  process.exit(why ? 1 : 0);
}

// Shared collections: the API on sagebrush.space (design/sharing.md).
//
//   GET  /auth/login?return=/path      sign in with CoCalc (code + PKCE); with AUTH_PROVIDER "workos", with
//                                      WorkOS AuthKit instead (and CoCalc is then no authority here at all)
//   GET  /auth/callback                the provider sends the user back here
//   POST /auth/logout
//   POST /auth/dev                     dev only: a session for a test account
//   GET  /api/share/me                 who you are, your usage and limits
//   GET  /api/share/mine               your collections
//   POST /api/share/first-upload       {title, license, files, attempt} -> {collection, version}: a
//                                      new share, created with its first version (its own path: a
//                                      server from before it answers 404 and creates nothing)
//   POST /api/share/collections        {title} -> {id}: an older page's empty collection, kept for
//                                      now (it is left empty when its upload fails); with files: 400
//   POST /api/share/check              {blobs: [{sha256, size}]} -> {missing}
//   PUT  /api/share/blob/<sha256>      the bytes (R2 checks the hash)
//   POST /api/share/collections/<id>/versions   {title, license, files} -> {version}
//   GET  /api/share/collections/<id>/versions   yours: its versions, oldest first -> {versions: [{hash, created, size, title}]}
//   GET  /api/share/c/<id>[?at=hash]   a collection's (latest) manifest
//   DELETE /api/share/collections/<id> delete a collection and its files
//   POST /api/share/delete-everything  {confirm: "delete"}: all of yours
//   POST /api/admin/purge              CoCalc: an account was deleted (signed)
//   GET  /api/admin/purge/<request_id> (signed)
//
// How storage stays consistent (D1 and R2 can't share a transaction):
//
// - Every upload is its own R2 object, a/<sha256(account_id)>/<random>, so
//   no object is ever shared between accounts or uploads: deleting one can
//   never remove bytes someone else (or a later upload) relies on.
//   Deduplication is per account (holdings), so nobody can learn whether
//   someone else has a file.
// - Bytes are reserved before they go to R2, by one conditional INSERT that
//   counts the account's files, manifests and other reservations: concurrent
//   uploads can't all pass one check.  Manifests count too.
// - A write that depends on a check made earlier ends in one D1 batch (a
//   transaction) with a guard row that fails, rolling the batch back, if the
//   check no longer holds (the account is being deleted, a file is no longer
//   held, the collection is gone).
// - An R2 object D1 stops referencing goes into the r2_deletes outbox in the
//   same batch, and leaves the outbox only once R2 has deleted it.  An object
//   written to R2 whose D1 write then failed is found from its expired
//   reservation.  So a failure anywhere leaves a state the scheduled job
//   finishes.
// - Deleting an account first marks it deleting (no sessions, no writes, in
//   the same batch that drops its sessions), then deletes its rows, then
//   everything under its R2 prefix; an account deleted in CoCalc keeps a
//   tombstone (by hash) so it never signs in again.
//
// Files are read from the user-content domain (web/share/files.ts) only
// through a collection: /c/<collection>/<sha256>, for files of its versions.

