  const m = ev.data;
  if (m?.file) {
    const w = waiting.get(m.file.path);
    waiting.delete(m.file.path);
    if (m.file.bytes instanceof ArrayBuffer) w?.ok(new TextDecoder().decode(m.file.bytes));
