    SAVED_UNJOURNALED: `This ${noun} is saved in this browser. TimeTravel and sync can't keep its versions right now (their storage is full): they'll keep the latest one when there's room.`,
    SAVED_TOO_LARGE: `This ${noun} is too large to sync. It's saved in this browser.`,
    NO_CLEAR_SYNCED: `TimeTravel's history can't be cleared while this ${noun} syncs (it will be, once conflicts are handled)`,
    BUSY: `the ${noun} kept changing while it was opened: reload this page`,
    ARRIVING: `this ${noun} is still arriving from sync: try again in a moment`,
    TOO_LARGE_TO_SYNC: `this ${noun} is too large to sync yet (its first synced version would be over 1 MiB): it is kept in this browser`,
    STARTED: `this ${noun}'s synced history has already started`,
    PAUSED: `TimeTravel is paused for this ${noun}`,
  };
}
export const NOT_WRITER = journalTexts("notebook").NOT_WRITER;
/** A versioned value (the codec's text) that can never be kept: past TimeTravel's bound for one version (an append's
 * JSON text alone, stores.js append), or an intent of it past the pending budget alone (2c-1d-iii §4). */
export const neverFits = (text) => text.length > Math.floor((HISTORY_BACKLOG.bytes - ENTRY_OVERHEAD) / 2) || intentCharge(text) > JOURNAL_BUDGETS.pendingAll;

/** Recovery's replay (design r4 §3.1), pure: from the record's revision `rev` (null: no record) and the intents above
 * its j in increasing j, the value chosen: the last one whose T2 would have won, in order, or null for the record's
 * own. */
export function replay(rev, intents) {
  let r = rev, chosen = null;
  for (const it of intents) {
    if (r === null || it.srev === null || it.srev === r) { chosen = it; r = r === null ? null : r + 1; }
  }

// The journal's rows (plan-sync-slice2-client r4 §2.1, F1, F2, F8; r9 §3.1a as #208's design r4 amends it), in the
// history database's own transactions: T1's writes (the document's next j; a version's patch row at it; a save's intent
// at it), intents pruned, a dropped document's rows deleted, and the journal read.  Kind-neutral: each takes a history
// store's transaction (or database) and the document's id, a notebook's or a board's.  Its own module, without the
// merge, so the workspace (web/workspace/api.ts, which drops a deleted notebook's rows) carries only this.  Moved here
// from web/notebook/journal-rows.js, which re-exports it under the same names; web/journal/core.js is the store-level
// part, web/notebook/journal.js the notebooks' store, its saves and its recovery.
//
// A document's rows: its registry row (its handle h), its j row (jseq), and its saves' intents ("p" + j, each
// {srev, value}); each charged (F8): the registry and j rows to the metadata budget (at most 4 KiB a document, 4 MiB in
// all), the intents to the 32 MiB pending budget, in the same transaction as the row.  What doesn't fit is refused, said, and nothing of it written.
import { SYNC_NB, SYNC_KEY_BOUNDS, handleOf, registryKey, rowCharge, rowKey, seqKey } from "../notebook/sync-rows.js";

/** The namespace of a device's local journal (the account's namespaces are the sender's, 2c-2). */
export const JOURNAL_NS = "local";
/** F8's budgets for the journal's rows, in bytes as charged. */
export const JOURNAL_BUDGETS = { metaDoc: 4096, metaAll: 4 * 2 ** 20, pendingAll: 32 * 2 ** 20 };
const NO_ROOM_META = "too many documents are kept for sync on this device: not saved";
const NO_ROOM_PENDING = "this version is too large to keep for sync now: not saved";
// (the rows that aren't a document's: the handles' counter, and the budgets' counters)
const COUNTER = [SYNC_NB, "n"], META = [SYNC_NB, "b:m:" + JOURNAL_NS], PENDING = [SYNC_NB, "b:p:" + JOURNAL_NS];

const rq = (r) => new Promise((ok, no) => { r.onsuccess = () => ok(r.result); r.onerror = () => no(r.error); });
// (a sync row as the history store keeps it: its key's parts, and its value under v)
const rowOf = ([nb, time], v) => ({ nb, time, v });
const refusedWith = (why) => Object.assign(new Error(why), { refusal: why });

// (a budget's counter raised by `delta` within `limit`, in the caller's transaction; over it, refused)
async function charge(st, key, delta, limit, why) {
  if (!delta) return;
  const cur = (await rq(st.get(key)))?.v ?? { bytes: 0 };
  const bytes = cur.bytes + delta;
  if (delta > 0 && bytes > limit) throw refusedWith(why);
  st.put(rowOf(key, { bytes: Math.max(0, bytes) }));
}

// (the document's registry row, made if `make` and it has none: its handle h and the metadata charged to it)
async function registry(st, id, make) {
  const key = registryKey(JOURNAL_NS, id), cur = (await rq(st.get(key)))?.v;
  if (cur || !make) return cur ? { key, ...cur } : null;
  const n = (await rq(st.get(COUNTER)))?.v?.next ?? 0, h = handleOf(n);
  // (the counter charged as it is, recharged as it grows)
  await charge(st, META, rowCharge(COUNTER, { next: n + 1 }) - (n ? rowCharge(COUNTER, { next: n }) : 0), JOURNAL_BUDGETS.metaAll, NO_ROOM_META);
  st.put(rowOf(COUNTER, { next: n + 1 }));
  return { key, h, meta: 0, fresh: true };
}

// (the document's metadata rows, j (jseq), m (its sync start), s (its slot, 2c-2) and k (its pull cursor, 2c-3), those in
// `changes` rewritten, and its metadata recharged: the registry's and these rows', together within the document's 4 KiB
// and everything's 4 MiB)
const META_ROWS = ["j", "m", "s", "k"];
async function setMeta(st, reg, changes) {
  let rows = 0;
  for (const L of META_ROWS) {
    const key = rowKey(reg.h, L), v = L in changes ? changes[L] : (await rq(st.get(key)))?.v;
    if (v !== undefined) rows += rowCharge(key, v);
  }
  // (the registry's own charge counted with a meta field as wide as the one it will hold)
  const total = rowCharge(reg.key, { h: reg.h, meta: rowCharge(reg.key, { h: reg.h, meta: 0 }) + rows }) + rows;
  if (total > JOURNAL_BUDGETS.metaDoc) throw refusedWith(NO_ROOM_META);

// The journal's store, kind-neutral (plan-sync-slice2-client r4 §2.1; r9 §3.1a as #208's design r4 amends it): a
// document's T1 then T2 on every save, its load's recovery, its writer's lock, and its synced history (2c-2, 2c-3), for
// any kind of document: notebooks (web/notebook/journal.js notebookKind) and boards.  Moved from web/notebook/journal.js,
// whose table (T1, T2, recovery, the mark) it implements; the notebooks' names are re-exported there.
//
// A kind ({kind, noun, lockPrefix, sync, versionedOf, history, toRecords, fromRecords, withValue, empty, apply,
// conflictCopy}), made from the history's module by `kindOf(mod)`:
//   kind, noun         its name ("notebooks", "boards") and the noun its texts say ("notebook", "board": journalTexts)
//   lockPrefix         its writer lock's name before the document's id ("sagebrush-nb-writer:", kept for open tabs)
//   sync               its switch: {on, saved(id)} (on: a writer's load starts its synced history; saved: told after a
//                      synced document's save is kept)
//   versionedOf(doc)   what its history keeps of a document: what the record's hash is of (hashOf)
//   history(store)     its history over a journal's patch store: a PatchHistory (web/notebook/patch-history.js) or a
//                      subclass, with record(doc, base) and mergedWith(doc, base).  The store uses its record,
//                      mergedWith, refused, init, close, session (value), codec (toString, fromString), paused,
//                      rebuilding, clientId, lastMs, sessionOptions, and its patch store's subscribe and onAcked
//   toRecords(doc), fromRecords(records)   a document as the history's records and back (its versioned part only)
//   withValue(rec, records)  the record with its versioned part replaced by `records`, its other parts kept.  The law,
//                      tested for each kind: withValue(rec, toRecords(rec)) is rec but for the store's own fields
//   empty(id, initial) a new document: `initial` (the store's) with what it lacks, and its id
//   apply(lastSynced, shown, remote, wins), conflictCopy   2c-3's merge (web/journal/core.js), of documents (the
//                      store gives it fromRecords's documents, and makes the record from toRecords of its value)
// The store's own fields of a record, the same for every kind, never a document's: rev, j, hash, unjournaled, and
// baseRev on the way in.
//
// `Base`, the kind's record store (T2): constructor(db, id, initial, {journal: true}) with `id` and `initial`;
// loadRecord(), the record or null; save(doc, {journal: {j, hash, unjournaled, keep?, markOnly?}}), a compare and swap
// on doc.baseRev, resolving {saved, rev}, {conflict}, or a refusal's text (web/notebook/stores.js IdbStore's).
import { bytesHash } from "../notebook/stores.js";
import { t1Write, dropRows, readJournal, roomRefused, syncedKey, acked, markSent, rotate } from "./rows.js";
import { writeIntent, prune, neverFits, replay, journalTexts } from "./core.js";
import { makeClientId, decodePatchId } from "patchflow";
import { NO_VERSIONS } from "../notebook/patch-history.js";
import { LIMITS } from "../sync-protocol/protocol";

const canonical = (v) => JSON.stringify(v, (k, x) => (x && typeof x === "object" && !Array.isArray(x) ? Object.fromEntries(Object.keys(x).sort().map((key) => [key, x[key]])) : x));
/** The hash of what a kind's history keeps of `doc` (SHA-256 of the canonical JSON of its versionedOf). */
export const hashOf = (kind, doc) => bytesHash(new TextEncoder().encode(canonical(kind.versionedOf(doc))));
export { canonical };
/** The rules a record's `at` proof was made under (the merge of several heads: patchflow's graph with the kind's
 * codec): a proof made under others is no proof, and its record is taken as an older version's (legacy). */
export const PROOF = "exact-1";
const MAX_AT = 64;

/** The journal's classes for a kind (`kindOf(mod)`), over the page's stores (stores.js: `{IdbStore, IdbPatchStore}`,
 * the page's own copy) or the kind's record store as `IdbStore`: {JournalStore, journalPatchStore}. */
export function journalStoreClasses({ IdbStore, IdbPatchStore }, kindOf) {
  /** A document's history store whose writes are the journal's: T1 on every version (an IdbPatchStore with the
   * journal's hooks), and, while paused, a save's intent alone (F4). */
  function journalPatchStore(hdb, id, kind = { noun: "notebook" }) {
    // (nothing written but by the document's writer here: `writerOK`, set by its JournalStore)
    // (`start`: a synced history's start, set by the store for its root's append (2c-2))
    const store = new IdbPatchStore(hdb, id, { journal: { t1: (st, row, intent) => (store.writerOK?.() === false ? Promise.resolve({ refused: journalTexts(kind.noun).NOT_WRITER }) : t1Write(st, id, { row, intent, start: row && store.start?.time === row.time ? store.start : undefined, noun: kind.noun })), drop: (st) => dropRows(st, id) } });
    // (the document's journal identity, for good: `store.id` is its history's key, which a synced document's start
    // changes to `<id>:s<n>`; every journal row is the document's (astra's CORR-2C2-1))
    store.docId = id; store.noun = kind.noun;
    // (F4: paused, a save's T1 is its intent alone; nothing to write for a version that isn't a save's)
    store.writePending = () => (store.intent ? writeIntent(store, store.intent) : Promise.resolve({ refused: journalTexts(kind.noun).PAUSED }));
    return store;
  }

// The LaTeX page's tools for an agent in the browser (WebMCP, navigator.modelContext), so that it can verify what it
// wrote and see it, as `sagebrush latex check|render` does on a computer (src/latex-cli.ts):
//   - latex_check: what the preview can't show or found wrong, each with its line (check.ts, the CLI's report);
//   - latex_render: each beamer frame (or each page of another document) as a PNG image, as the preview draws it,
//     and every frame whose content overflows its slide.
// Registered once per page; they act on the document the LaTeX page has open (setTarget), else say none is.
// This is only the document they act on: the tools themselves (their names, descriptions and arguments) and their
// work (the report, the pictures) are tools.ts, a chunk of its own, /sagebrush-latex-tools.js, fetched only where the
// browser offers WebMCP (an agent's browser): an ordinary one never fetches it (the eager group full: William's H5).
import type { EngineCheck } from "./check";

export interface ToolTarget {
  file: () => string;
  text: () => string;
  /** The check data of the preview shown, if it is of the source now in the editor; else null (one is coming). */
  lastCheck: () => EngineCheck | null;
  /** Whether the preview shown is of the source now in the editor. */
  current: () => boolean;
  preview: HTMLElement;
  images: Record<string, string | { why: string }>;
  /** The page's own styles (style.ts PAGE_CSS), for the pictures. */
  css: string;
  /** Read the code's saved results again (a `sagebrush latex run` may have written them since). */
  refresh?: () => Promise<void>;
}

// (a failed fetch is forgotten, so the next page's mount fetches again, by a URL of its own)
const toolsUrl = new URL("sagebrush-latex-tools.js", import.meta.url).href;
let work: Promise<typeof import("./tools")> | null = null, tries = 0;
const load = () => (work ??= (import(tries++ ? `${toolsUrl}?try=${tries}` : toolsUrl) as Promise<typeof import("./tools")>).catch((e) => { work = null; throw e; }));
let target: ToolTarget | null = null;
let registered = false;

/** The document the tools act on (null: none is open). */
export function setTarget(t: ToolTarget | null) { target = t; }
/** No document, if `t` is still the one (a page replaced by the next one's mount leaves that one's). */
export function clearTarget(t: ToolTarget) { if (target === t) target = null; }

/** The tools registered with the browser's WebMCP, if it has it: once, the chunk fetched first. */
export function registerLatexTools() {
  if (registered || !(navigator as any).modelContext) return;
  registered = true;
  load().then((m) => m.register(() => target), (e) => { registered = false; console.warn("WebMCP (LaTeX):", e); });
}

// An agent on this computer, paired with the LaTeX editor's page (design/workspace-agent-protocol.md): the shared
// pairing module (web/workspace/agent-ui.ts), in a chunk of its own, /sagebrush-latex-agent.js, fetched only when the
// person asks to connect an agent, opens a ?pair= link, or has an agent remembered.
export { mountAgentPairing } from "../workspace/agent-ui";

// The LaTeX editor saves as you type (William, Nov 2, U8: "a user should never see 'Leave this file without saving
// your changes?', have to explicitly find and click a 'Save' button"; plan U8 r6, on top of #599).
//
//   - Every edit is durable at once: a draft of the editor's text, bound to the file (fid) and to this editor
//     (writerId, a fresh random id per editor instance, so two tabs never share or replace a draft), written before
//     anything asynchronous (drafts.ts: localStorage, synchronously; a draft too large for it goes to IndexedDB, durable
//     when its transaction completes; William: "Never prompt; accept that tiny risk for >2 MB files").
//   - The file is written 800 ms after the last edit, and at once on flush (blur, hidden, pagehide, a switch, Ctrl+S):
//     one write at a time, by the page's own save (page.ts, #599: compare-and-swap on the revision its saved text came
//     from), of the text as it is when the write starts. Its acknowledgement removes this writer's drafts up to that
//     write's gen only: edits made since stay pending and get the next write.
//   - A change made elsewhere is the page's (#599): followed with nothing pending; with edits pending, its bar asks
//     (Keep mine, Use theirs) and nothing is written meanwhile ("blocked"). Settled, the page says so (settled()).
//   - A write that fails (storage full, the file gone or replaced) is the one state that keeps a prompt on leaving;
//     its edits stay in the editor and in the draft, and are written again on the next edit or flush.
//   - After dispose (the editor closed or switched), nothing of the UI changes.
// Pure logic over injected I/O, timers and draft stores: test-latex-autosave.mjs runs it with fakes.

export const DEBOUNCE_MS = 800;

export interface Draft { fid: string; writerId: string; gen: number; path: string; baseRev: number; text: string; t: number }

/** Where drafts are kept (drafts.ts; a fake in the tests). `put` is synchronous when it returns true (durable now),
 * else it returns the promise of the write that makes it durable (a large draft). `drop` removes this writer's
 * drafts whose gen is at most `upTo`, checked at the time of the removal. */
export interface DraftStore {
  put(d: Draft): true | Promise<void>;
  drop(fid: string, writerId: string, upTo: number): Promise<void>;
  all(fid: string): Promise<Draft[]>;
}

export interface SaverIO {
  /** The page's save of exactly this text: "saved"; "blocked" (a change made elsewhere is being asked about, or a
   * choice in its bar is under way: nothing written); "readonly" (this file can't be saved here, the banner says why:
   * nothing written, no prompt); throws for a refusal, its message the reason. */
  write(text: string): Promise<"saved" | "blocked" | "readonly">;
  /** Keep `text` as a version of this file, without writing the file (fid-checked). */
  keepVersion(text: string): Promise<void>;
}

export type SaveState = { k: "saved" } | { k: "edited" } | { k: "saving" } | { k: "blocked" } | { k: "readonly" } | { k: "failed"; why: string };

export interface SaverUI {
  text(): string;
  /** Edits not written: the editor's text isn't the one last saved or read (the page's own baseline) */
  dirty(): boolean;
  /** The revision the page's baseline is of */
  rev(): number;
  /** A change made elsewhere being asked about, or a choice in its bar under way */
  blocked(): boolean;
  /** A recovered draft put in the editor, as an edit of the person's (not saved) */
  adopt(text: string): void;
  /** A recovered draft made on an older revision than the file's: the page's bar asks, as for a change elsewhere */
  stale(): void;
  readOnly(on: boolean): void;
  state(s: SaveState): void;
}

