// preview can't do yet and what a full LaTeX run does instead. test-latex-units.mjs renders all of them.
// Their files are the corpus's, examples/latex/<id>/ (the gallery's: plan-examples-gallery), as literals in the
// bundle (web/examples/legacy.ts).
import { latexExamples } from "../examples/legacy.ts";

export type Example = { id: string; title: string; about: string; files: [name: string, text: string, base64?: true][] };

export const EXAMPLES: Example[] = latexExamples();

// Every render request carries the document and the source revision it was made for; a reply is patched only for
// that document, and its image names used only for that revision. A load is bound to its own token: nothing is sent
// while it is pending (the text shown is still the old one), and a later load wins (the earlier one's result, or its
// error, is ignored). Delayed callbacks re-check the token they captured.
export type Token = { doc: number; rev: number };
export class RenderGate {
  doc = 0;
  rev = 0;
  loading: Token | null = null;
  load(): Token { this.doc++; this.rev++; this.loading = this.token(); return this.loading; }
  loaded(t: Token): boolean { if (!this.current(t) || !this.loading || this.loading.doc !== t.doc) return false; this.loading = null; return true; }
  canSend(): boolean { return this.loading === null; }
  edit(): Token { this.rev++; return this.token(); }
  token(): Token { return { doc: this.doc, rev: this.rev }; }
  accept(r: { doc?: unknown; rev?: unknown } | null | undefined): { patch: boolean; current: boolean } {
    const doc = !!r && r.doc === this.doc;
    return { patch: doc, current: doc && r!.rev === this.rev };
  }
  current(t: Token | null | undefined): boolean { return !!t && t.doc === this.doc && t.rev === this.rev; }
  sameDoc(t: Token | null | undefined): boolean { return !!t && t.doc === this.doc; }
}

// The LaTeX editor's highlighter (plan sbspace r5 §4, P4): the source's lines drawn behind the textarea, colored by
// a line tokenizer whose start state per line is cached. An edit rescans from its first changed line until a line's
// computed start state equals the cached one past the edit (convergence). Bounded per input event: at most
// SLICE.lines lines, SLICE.bytes of source and SLICE.ms, the time checked every SLICE.check tokens (a line's
// tokenizer is a generator, so a long line resumes where it stopped); then it continues in later slices. A line over
// LONG_LINE is plain (its end state "unknown", reset to normal). If an edit hasn't converged within FALLBACK_MS, the
// lines not yet rescanned are drawn plain until done. A file over PLAIN_FILE isn't highlighted at all.
import { mark } from "./marks";

export const SLICE = { lines: 2000, bytes: 64 * 1024, ms: 8, check: 256 };
export const LONG_LINE = 16 * 1024, FALLBACK_MS = 150, PLAIN_FILE = 2 ** 20;
export type State = string;   // "N" normal, "M" inline math, "D" display math, "E:env" a math environment, "V:env" verbatim
type Tok = [cls: string, text: string];
const VERB = new Set(["verbatim", "verbatim*", "Verbatim", "lstlisting", "minted", "comment", "sageblock", "sagesilent", "sagecommandline", "pycode", "pyblock"]);
const MATHENV = new Set(["equation", "equation*", "align", "align*", "gather", "gather*", "multline", "multline*", "eqnarray", "eqnarray*", "displaymath", "math"]);
const ESC: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;" };
const esc = (s: string) => s.replace(/[&<>]/g, (c) => ESC[c]);

/** One line's tokens (yielded) and its end state (returned). */
export function* tokenizeLine(line: string, state: State): Generator<Tok, State, void> {
  let i = 0;
  // (a blank line ends $...$, $$...$$, \(...\) and \[...\] as it does for the renderer: an unclosed formula being typed
  // doesn't color the rest of the file as math)
  if ((state === "M" || state === "D") && /^[ \t]*$/.test(line)) return "N";
  if (state.startsWith("V:")) {
    const env = state.slice(2), end = line.indexOf("\\end{" + env + "}");
    if (end < 0) { yield ["c-verb", line]; return state; }
    if (end > 0) yield ["c-verb", line.slice(0, end)];
    i = end; state = "N";
  }
  const inMath = () => state !== "N";
  while (i < line.length) {
    const c = line[i];
    if (c === "%") { yield ["c-cmt", line.slice(i)]; break; }
    if (c === "\\") {
      const m = /^\\([A-Za-z@]+\*?|.)/.exec(line.slice(i));
      const cs = m ? m[0] : "\\";
      if (cs === "\\[") state = "D"; else if (cs === "\\]" && state === "D") state = "N";
      else if (cs === "\\(") state = "M"; else if (cs === "\\)" && state === "M") state = "N";
      if (cs === "\\begin" || cs === "\\end") {
        const env = /^\{([^}]*)\}/.exec(line.slice(i + cs.length));
        // (a math environment's \begin and \end both in math's color, as $ and \[ \] are: the \begin that opens it
        //  is colored as the math it starts, its \end as the math it closes)
        const opens = !!env && cs === "\\begin" && MATHENV.has(env[1]) && state === "N";
        yield [inMath() || opens ? "c-math c-cmd" : "c-cmd", cs + (env ? env[0] : "")];
        i += cs.length + (env ? env[0].length : 0);
        if (env && cs === "\\begin" && VERB.has(env[1])) { const rest = line.slice(i); const endAt = rest.indexOf("\\end{" + env[1] + "}"); if (endAt < 0) { if (rest) yield ["c-verb", rest]; return "V:" + env[1]; } if (endAt) yield ["c-verb", rest.slice(0, endAt)]; i += endAt; continue; }
        if (env && cs === "\\begin" && MATHENV.has(env[1]) && state === "N") state = "E:" + env[1];
        else if (env && cs === "\\end" && state === "E:" + env[1]) state = "N";
        continue;
      }
      yield [inMath() || cs === "\\]" || cs === "\\)" ? "c-math c-cmd" : "c-cmd", cs];
      i += cs.length; continue;
    }
    if (c === "$") {
      const dbl = line[i + 1] === "$";
      if (dbl) state = state === "D" ? "N" : state === "N" ? "D" : state; else state = state === "M" ? "N" : state === "N" ? "M" : state;
      yield ["c-math", dbl ? "$$" : "$"]; i += dbl ? 2 : 1; continue;
    }
    if (c === "{" || c === "}") { yield [inMath() ? "c-math" : "c-brace", c]; i++; continue; }

// The LaTeX editor's images (plan sbspace r5 §3): \includegraphics{name} resolved as TeX does (the opened file's folder,
// then \graphicspath's; up with ../, never above the workspace's top folder: William, Nov 2, L2),
// read by identity, bounded, checked by their bytes, and shown only as <img> from a blob: URL. The page decides with
// these pure functions; tests/test-latex-units.mjs checks them.
import { normPath, parentOf } from "../workspace/paths";

export const IMAGE_EXTS = [".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg"];
export const IMAGE_BOUNDS = { perDocument: 64, perImage: 8 * 2 ** 20, total: 64 * 2 ** 20, megapixels: 40 };

/** The bytes actually read (len), against the size the file was admitted with (its stat) and the bytes already kept:
 * null if they may be kept, else why not. Checked after the read, before any blob is made. */
export function admitImageBytes(len: number, statSize: number | undefined, kept: number, b = IMAGE_BOUNDS): string | null {
  if (len !== (statSize ?? -1)) return "changed while it was read";
  if (len > b.perImage || kept + len > b.total) return "too large";
  return null;
}

/** `rel` ("a/b", "../x", "./y") from the folder `from`, as a workspace path, or null if it isn't a relative path of
 * names or goes above the workspace's top folder. */
function resolveRel(from: string, rel: string): string | null {
  const out = from === "/" ? [] : from.slice(1).split("/");
  for (const x of rel.split("/")) {
    if (x === "" || x === ".") continue;
    if (x === "..") { if (!out.length) return null; out.pop(); } else out.push(x);
  }
  try { return normPath("/" + out.join("/")); } catch { return null; }
}

/** The folders of a \graphicspath{{dir/}{../figs/}} in the preamble (the last one, as LaTeX keeps the last), in order;
 * comments are skipped. */
export function graphicsPathOf(text: string): string[] {
  const pre = String(text).slice(0, 2 ** 20).split(/\\begin\s*\{document\}/)[0].replace(/(^|[^\\])%.*$/gm, "$1");
  let last: string[] = [];
  for (const m of pre.matchAll(/\\graphicspath\s*\{((?:\s*\{[^{}]*\})*)\s*\}/g)) last = [...m[1].matchAll(/\{([^{}]*)\}/g)].map((d) => d[1].trim()).filter(Boolean).slice(0, 16);
  return last;
}

/** The workspace paths an \includegraphics argument may name, in the order LaTeX tries them: relative to the opened
 * file's folder, then to each \graphicspath folder (`dirs`, themselves relative to the file's folder), each as written
 * and then with each allowed extension; and the folders searched. Or why it names none. A name may go up ("../x.png")
 * as TeX's may, but never above the workspace's top folder; a leading "/" is that top folder (`root`; William, Nov 2:
 * never the real filesystem's), searched alone, as TeX searches an absolute name; never a URL or a backslash. */
export function imageCandidates(arg: string, docPath: string, dirs: string[] = [], root = "/"): { ok: true; paths: string[]; searched: string[] } | { ok: false; why: string } {
  return candidates(arg, docPath, dirs, root, (base) => (IMAGE_EXTS.some((x) => base.toLowerCase().endsWith(x)) ? [base] : [base, ...IMAGE_EXTS.map((x) => base + x)]));
}

/** The workspace paths an \input or \include argument may name, as TeX tries them (with .tex added first, then as
 * written; \include{x} reads x.tex), found as images are (imageCandidates: the file's folder, ../, a leading "/";
 * TeX's \input doesn't search \graphicspath), and the folders searched; or why it names none. */
export function texCandidates(arg: string, docPath: string, root = "/"): { ok: true; paths: string[]; searched: string[] } | { ok: false; why: string } {
  return candidates(arg, docPath, [], root, (base) => (base.toLowerCase().endsWith(".tex") ? [base] : [base + ".tex", base]));
}

function candidates(arg: string, docPath: string, dirs: string[], root: string, names: (base: string) => string[]): { ok: true; paths: string[]; searched: string[] } | { ok: false; why: string } {
  const s = String(arg).trim();
  if (s === "" || s.length > 512) return { ok: false, why: "not a file name" };
  if (/[\u0000-\u001f\u007f]/.test(s)) return { ok: false, why: "not a file name" };
  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(s)) return { ok: false, why: "a URL: only files in this workspace are shown" };
  if (s.includes("\\")) return { ok: false, why: "a backslash: write the path with / (e.g. figs/" + s.replace(/^.*[\\/]/, "") + ")" };
  if (/%(2f|2e|5c)/i.test(s)) return { ok: false, why: "not a file name" };

// The files a .tex reads with \input and \include (William's L4, Nov 2: they were silently ignored, which broke his
// shared macros file). Found as TeX finds them (images.ts texCandidates: the .tex's folder, ../, a leading "/" for
// the workspace's top; .tex added first), read by the host (the page from the workspace, the CLI from the folder it
// runs in, each with its own read rules), bounded here, and given to the engine as a snapshot: the engine never reads
// a file itself (engine/pipeline.mjs inputs, engine/demo-machine.mjs doInput). Pure: test-latex-units.mjs checks it.
import { texCandidates, notFoundWhy } from "./images";
import { openBytes, EDIT_MAX } from "./save";

/** At most this many included files, of at most EDIT_MAX bytes each and INPUT_BOUNDS.total in all. */
export const INPUT_BOUNDS = { files: 64, perFile: EDIT_MAX, total: 16 * 2 ** 20 };

/** What the host knows of a candidate path: its text, why it isn't read (refused, too large, not text), or absent. */
export type Known = { text: string } | { why: string } | { absent: true };

/** The engine's inputs, for the .tex at `docPath`, from what the host has read (`known`, by workspace path):
 * `files` (key -> text: the read ones), `resolve(name)` (the key, or why there is none) and `wanted(names)` (the
 * candidate paths the host should look at next: unknown ones for each name, in order, up to the first that might
 * be it). The .tex itself is the engine's main.tex. `relativeToFile`: the folders named from the file's (the CLI). */
export function engineInputs(docPath: string, known: Map<string, Known>, relativeToFile = false) {
  const files = new Map<string, string>();
  for (const [p, k] of known) if ("text" in k && p !== docPath) files.set(p, k.text);
  const resolve = (name: string): { key?: string; why?: string } => {
    const c = texCandidates(name, docPath);
    if (!c.ok) return { why: c.why };
    for (const p of c.paths) {
      if (p === docPath) return { key: "main.tex" };
      const k = known.get(p);
      if (k === undefined) return { why: "not read yet" };
      if ("text" in k) return { key: p };
      if ("why" in k) return { why: k.why };
    }
    return { why: notFoundWhy(docPath, c.searched, [], relativeToFile, name) };
  };
  const wanted = (names: string[]): string[] => {
    const out: string[] = [];
    for (const name of names) {
      const c = texCandidates(name, docPath);
      if (!c.ok) continue;
      for (const p of c.paths) {
        if (p === docPath) break;
        const k = known.get(p);
        if (k === undefined) { if (!out.includes(p)) out.push(p); break; }
        if (!("absent" in k)) break;
      }
    }
    return out;
  };
  return { files, resolve, wanted };
}

/** An included file's bytes as the engine's text, or why not, against what is already kept (`kept` bytes, `count`
 * files). */
export function admitInput(bytes: Uint8Array, kept: number, count: number, b = INPUT_BOUNDS): Known {
  if (count >= b.files) return { why: "too many included files (" + b.files + ")" };
  if (bytes.length > b.perFile || kept + bytes.length > b.total) return { why: "too large" };
  const o = openBytes(bytes);
  if (o.kind === "binary") return { why: o.why };
  return { text: o.text };
}

// The LaTeX editor's @interact (a Sagebrush extension, William Nov 8: "@interact inside sagesilent/sageblock as a
// documented Sagebrush extension"; upstream SageTeX and Sage 10.10 raise NameError on it): a chunk of its own,
// /sagebrush-latex-interact.js, fetched only once a preview has an interact (sagetex.mjs interactsAt's placeholder, its
// interacts as escaped JSON). Each is drawn with its controls at their defaults, not live here, what its function
// printed and showed at those values, and a line saying it is interactive in Sagebrush (William's Q2: the PDF shows it
// so). Everything from the results file reaches the HTML through esc(); a shown plot only as a base64 SVG data URL
// (DATA_SVG), as \sageplot's.
import { DATA_SVG, STALE_TITLE, utf8len } from "./engine/sagetex.mjs";

// ---- an item's @interacts, as the Run's session printed them (run-core's driver), checked before the results file
// holds them, as a result is (this chunk's, so Run's own carries only the driver: daybreak2's SIZE design, Beamer plan PR
// 3): at most INTERACT_LIMITS.n an item, each with its controls (only the fields drawn, by kind), what its function
// printed at the defaults (bounded) and what it showed (a plot only as an SVG, as \sageplot's; text bounded)
export const INTERACT_LIMITS = { n: 8, controls: 20, shows: 4, text: 4000, options: 50, label: 200, svg: 2 * 2 ** 20 };   // (svg: Run's RUN_LIMITS.svg)
const CONTROL_KINDS = new Set(["slider", "range", "selector", "checkbox", "input", "color", "text", "button"]);
const num = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const str = (v: unknown, n: number) => (typeof v === "string" ? v.slice(0, n) : undefined);
const b64 = (s: string) => {
  const u = new TextEncoder().encode(s);
  let t = "";
  for (let i = 0; i < u.length; i += 0x8000) t += String.fromCharCode(...u.subarray(i, i + 0x8000));
  return btoa(t);
};
function controlOf(c: any): Record<string, unknown> | null {
  if (!c || typeof c !== "object" || !CONTROL_KINDS.has(c.kind)) return null;
  const L = INTERACT_LIMITS.label;
  const o: Record<string, unknown> = { kind: c.kind, name: str(c.name, L) ?? "", label: str(c.label, L) ?? str(c.name, L) ?? "" };
  for (const k of ["min", "max", "step"]) if (num(c[k])) o[k] = c[k];
