// Positions through edits (plan L1b r4b §2 items 1 and 1b, §5 step 0): the LaTeX editor's own marker mapping, as
// CodeMirror's mapPos does for its documents (William, Nov 2: "if we were using Codemirror ... it would track how that
// moves on every edit operation. Since our editor is 'from scratch' we have to own that"). The code items of a .tex
// keep their identity through the person's edits, an undo or redo, and the changes that come from outside (another
// tab, an agent, sync, git), because each edit is a change set and every item's range is mapped through it.
//
// A change set is a list of changes {from, to, insert}, in OLD-text coordinates (UTF-16 offsets), sorted by `from`,
// non-overlapping (a change may touch the next: to === next.from): the text [from, to) is replaced by `insert`
// characters. All the changes of a set are applied at once.
//
// A position is a gap between two characters, and it follows them:
//   - its left character kept: just after it (what follows it was deleted or inserted);
//   - its left character deleted, its right one kept: just before the right one;
//   - both kept with text inserted between them, or both deleted: by its bias, before (-1) or after (+1) the text
//     inserted there.
// (The document's ends count as characters always kept.) An item's range [start, end) maps its start with bias +1 and
// its end with bias -1, so text typed at either edge of an item stays outside it; an item all of whose characters
// were deleted maps to an empty range.
// Pure: test-latex-posmap.mjs checks it against a reference that tracks each character's identity.

export interface Change { from: number; to: number; insert: number }
export type ChangeSet = readonly Change[];
export type Bias = -1 | 1;

/** Whether `cs` is a well-formed change set for a text of `len` characters. */
export function validChanges(cs: ChangeSet, len: number): boolean {
  let last = 0;
  for (const c of cs) {
    if (!Number.isInteger(c.from) || !Number.isInteger(c.to) || !Number.isInteger(c.insert)) return false;
    if (c.from < last || c.to < c.from || c.to > len || c.insert < 0) return false;
    last = c.to;
  }
  return true;
}

/** `pos` (a gap of the old text) in the new text. Changes that touch (one's `to` the next's `from`) are taken as one
 * region: a gap between them has no kept character on one side, so it is inside the region (by its bias), or at its
 * end (its right character kept: after everything inserted). */
export function mapPos(pos: number, cs: ChangeSet, bias: Bias = -1): number {
  let delta = 0, i = 0;
  while (i < cs.length) {
    const from = cs[i].from;
    let to = cs[i].to, ins = cs[i].insert;
    while (i + 1 < cs.length && cs[i + 1].from === to) { i++; to = cs[i].to; ins += cs[i].insert; }
    i++;
    if (from > pos) break;
    if (to < pos) { delta += ins - (to - from); continue; }
    if (from === to) return pos + delta + (bias > 0 ? ins : 0); // a pure insertion at the gap: by the bias
    if (pos === from) return from + delta; // its left character kept: before the inserted text
    if (pos === to) return from + delta + ins; // its right character kept: after it
    return from + delta + (bias > 0 ? ins : 0); // inside the deleted text: by the bias
  }
  return pos + delta;
}

/** A range [start, end) in the new text: start with bias +1, end with bias -1 (an edit at its edges stays outside);
 * empty (start === end) if all of it was deleted or it was empty. */
export function mapRange(start: number, end: number, cs: ChangeSet): { start: number; end: number } {
  const s = mapPos(start, cs, 1), e = mapPos(end, cs, -1);
  return e <= s ? { start: s, end: s } : { start: s, end: e };

// The LaTeX editor's presenter: a beamer document's slides one at a time, full screen, step by step through their
// overlays (overlay.ts), as an audience sees them. A chunk of its own, /sagebrush-latex-present.js, fetched when the
// person (or an agent) presses Present. The slide shown is a copy of the preview's, made again whenever the preview
// is redrawn, so an edit made while presenting shows at once. Each slide is a size container (style.ts), so its
// type scales with the width it is given: no transform.
//   Keys: Right, Down, Page Down, Space, Enter, N: next step (then the next slide); Left, Up, Page Up, Backspace, P:
//   back; Home, End: the first and the last slide; a number then Enter: that slide; F: full screen on and off;
//   Escape: stop; Shift+Enter: run the document's code (opts.onRun), the slide staying as it is shown, its values
//   updated when the Run's results are; S: stop that Run (opts.onStop), nothing without one. While a Run is under way
//   the count says so (running()). A click on the left third goes back, elsewhere forward. A live @interact on the
//   slide (opts.onShow) takes its own clicks and keys; Escape still stops.
import { applyStep, stepsOf } from "./overlay";

export interface PresentOpts {
  /** The preview's slides, in order, as they are now. */
  slides: () => HTMLElement[];
  /** Calls back after each redraw of the preview; returns a function that stops it. */
  onRendered?: (f: () => void) => () => void;
  /** The slide to start at (1-based), and its step. */
  start?: number;
  step?: number;
  /** Shift+Enter: run the document's code (the page's Run), presenting on. */
  onRun?: () => void;
  /** S: stop the Run under way (the page's Stop); the page does nothing when there is none. */
  onStop?: () => void;
  /** After each slide shown (a fresh copy on the stage): the page makes its @interacts live there. */
  onShow?: (stage: HTMLElement) => void;
  /** Full screen (default true; it needs the person's click). */
  fullscreen?: boolean;
  onExit?: () => void;
}
export interface Presenter { at: () => { frame: number; step: number; frames: number; steps: number }; go: (frame: number, step?: number) => void; next: () => void; prev: () => void; stop: () => void; running: (on: boolean) => void; el: HTMLElement }

const CSS = `
.tex-page.tex-present { position: fixed; inset: 0; z-index: 2147483000; display: flex; align-items: center; justify-content: center; background: #000; overflow: hidden; }
.tex-present .tp-stage { position: relative; }
.tex-present .tp-stage > .slide { margin: 0; border: none; box-shadow: none; width: 100%; }
.tex-present .tp-count { position: fixed; right: 14px; bottom: 10px; font: 13px system-ui, sans-serif; color: rgba(255,255,255,.55); pointer-events: none; }
.tex-present.tp-idle { cursor: none; }
.tex-present .tp-count:empty { display: none; }
.tex-present .sagechip.s-notrun { display: none; }
`;

export function present(o: PresentOpts): Presenter {
  const root = document.createElement("div");
  root.className = "tex-page tex-present";
  root.setAttribute("role", "dialog"); root.setAttribute("aria-label", "Presentation"); root.tabIndex = -1;
  const style = document.createElement("style"); style.textContent = CSS; root.appendChild(style);
  const stage = document.createElement("div"); stage.className = "tp-stage"; root.appendChild(stage);
  const count = document.createElement("div"); count.className = "tp-count"; count.setAttribute("aria-live", "polite"); root.appendChild(count);
  document.body.appendChild(root);
  let frame = Math.max(1, o.start ?? 1), step = Math.max(1, o.step ?? 1), typed = "", stopped = false, busy = false, at = "";
  // (the count: the slide and its step, and while a Run is under way, that S stops it (board's words))
  const counted = () => { count.textContent = at + (busy ? " · running… (S stops)" : ""); };

  const fit = () => {
    const s = stage.firstElementChild as HTMLElement | null;
    if (!s) return;
    // (the slide's aspect ratio, from its own style; the largest box of that ratio in the window)
    const ar = getComputedStyle(s).aspectRatio.split("/").map(Number), r = ar.length === 2 && ar[0] > 0 && ar[1] > 0 ? ar[0] / ar[1] : 4 / 3;

// The LaTeX editor's preview host (web/build.ts; read by the build script only, never bundled): with
// SAGEBRUSH_LATEX_PREVIEW=1, SAGEBRUSH_PREVIEW_HOST names one more host where the editor may be turned on (the user
// still asks, with ?latex=1). It must be exactly one hostname under sagebrush.cloud; anything else stops the build.
// Unset, or with the flag unset or "test", it is ignored.
const LABEL = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

/** The extra host for this build: null when there is none; throws on a value that isn't allowed. */
export function previewHost(mode, raw) {
  if (mode !== "1" || raw === undefined || raw === "") return null;
  const h = String(raw);
  const labels = h.split(".");
  const ok = h.length <= 253 && h.endsWith(".sagebrush.cloud") && labels.length >= 3 && labels.every((l) => LABEL.test(l));
  if (!ok) throw new Error(`SAGEBRUSH_PREVIEW_HOST must be one lowercase hostname under .sagebrush.cloud, not ${JSON.stringify(h)}`);
  return h;
}

// The SageTeX results file checked against the files its Run imported from the .tex's folder (Codex W01): the page
// reads results when it opens and on focus, without Run's own code (run-core.mjs, a lazy chunk since #824), so these
// are a module of their own, in the page's bundle; run-core.mjs re-exports them.
import { depsOf, staleOf } from "./engine/sagetex.mjs";

// ---- the editor reading a results file's record of what its Run imported (Codex W01)
/** The .tex's folder's reader of recorded files, the CLI's rule (sagetex.mjs staleOf): the file's bytes, at most
 * `left`; null if it isn't there or is in the Trash; "over" if larger than `left`. */
export const wsReader = (ws, dir) => async (rel, left) => {
  const p = (dir === "/" ? "" : dir) + "/" + rel;
  try { const r = await ws.readUpTo(p, left); return r.entry?.trashed ? null : r.content; }
  catch (err) { return err?.code === "limit" ? "over" : null; }
};
/** What was seen of a results file (`e`, its entry) and of each file its Run imported: their ids, revisions and
 * sizes in one string; null if there is no results file. */
export async function seenOf(ws, e, dir, deps) {
  if (!e || e.trashed) return null;
  const base = dir === "/" ? "" : dir;
  const ds = await Promise.all(deps.map(([rel]) => ws.stat(base + "/" + rel).catch(() => undefined)));
  // (rev counts every write: `updated` is a time in ms and two writes may share it (daybreak3's ENGINE-SEEN-REV-1))
  return `${e.fid}:${e.rev}:${e.updated}:${e.size}#` + ds.map((d) => d && !d.trashed ? `${d.fid}:${d.rev}:${d.updated}:${d.size}` : "-").join("|");
}
/** A results file `j` (read from `p`, its entry `e`) checked against the files its Run imported: {saved, deps, stale,
 * seen}. `saved`: its items if they may be used, else []; `stale`: why not (sagetex.mjs staleWhy), or null. `seen`
 * is the state checked, or null if anything changed while it was checked (astra's DEP-SEEN-1, daybreak3's
 * ENGINE-SEEN-COMMIT-1): then nothing is used and nothing counts as seen, so the next read checks again. */
export async function checkedResults(ws, p, e, j, dir) {
  const deps = depsOf(j);
  if (deps === "invalid" || deps === "incomplete") return { saved: [], deps: [], stale: deps, seen: await seenOf(ws, e, dir, []) };
  if (!deps) return { saved: j.items, deps: [], stale: null, seen: await seenOf(ws, e, dir, []) };
  const before = await seenOf(ws, e, dir, deps);
  const stale = await staleOf(deps, wsReader(ws, dir));
  const after = await seenOf(ws, await ws.stat(p).catch(() => undefined), dir, deps);
  const stable = before !== null && before === after;
  return { saved: stale || !stable ? [] : j.items, deps, stale: stable ? stale : null, seen: stable ? after : null };
}

// The editor's Run (page.ts, William's "sagetex exists tomorrow"): a document's SageTeX items run, in page order, in
// one Sage session of the site's own engine (the board's siteEngine, in the opaque-origin runner), on the person's
// click only; their states written as `sagebrush latex run`'s results file (results v1, FILE.tex.results.json), which
// the page then reads and shows as it shows the CLI's. This file is the part without a page: the session's script,
// and how what it printed becomes the results.
// An item that fails stops the rest, as in the CLI (@sagebrush's ruling, Nov 10, for every language): the script ends
// there, a refused item isn't sent nor anything after it, and each later item says so (BLOCKED, board's M4).
// SECURITY: the items' code reaches the session only as base64 inside the script (never spliced into it as text); what
// the session prints is parsed, never evaluated, and each result is checked here as the CLI checks it (the LaTeX's
// size, the plot's SVG), and again where it is shown (sagetex.mjs).
import { namesIn } from "./names.mjs";
import { MAX_RESULT, WRAPPER_VERSION, utf8len, whyRejected, safeRel, sha256hex, DEPS_MAX, isPy, isNonSage, BLOCKED } from "./engine/sagetex.mjs";

export const RESULTS_FORMAT = "sagebrush-latex-results";
export const RUN_LIMITS = { svg: 2 * 2 ** 20, msg: 4000 };   // (the CLI's SVG_MAX and MSG_MAX, src/latex-cli.ts)
/** The .tex's folder a Run is given (its files, and their bytes): past either, Run says so and runs nothing. */
export const FOLDER_LIMITS = { files: 500, bytes: 64 * 2 ** 20 };
/** what starts each result line the session prints (a record separator: never in an item's own printing, which is kept apart) */
// (what a plot's SVG starts with: checked here and, the same pattern, in the session's script)
const SVG_HEAD = /^\s*(<\?xml[^>]*>\s*)?<svg[\s>]/;
export const MARK = "\u001eSBTX";
/** what starts the line the session prints last: the modules its Run imported from the .tex's folder (Codex W01) */
export const DEPS_MARK = MARK + "D";

const b64 = (s) => {
  const u = new TextEncoder().encode(s);
  let t = "";
  for (let i = 0; i < u.length; i += 0x8000) t += String.fromCharCode(...u.subarray(i, i + 0x8000));
  return btoa(t);
};

// The driver's notes (Python comments once, kept here so the chunk doesn't carry them; its Python indented by 2, also
//  for the chunk's size):
// (each item compiled as Sage source by the runtime itself, so its code object keeps Sage's semantics when it
//  runs: 1/3 exact, as in a .sage file; plain exec of preparsed text is Python's, 1/3 a float (#706). Given the
//  raw item: that compile preparses it, and preparsing twice would make ^^ a power. CPython: preparsed, exec'd)
// (_sx_prev: the previous Run's folder, whose modules go too; _sx_added: the sys.path entry a Run appended, the only
//  one taken off: "/" and the runtime's own entries, there before, stay where they are)
// (a result over its cap, or a plot that isn't an SVG (SVG_HEAD), fails in the script too, before the next item runs
//  (daybreak3's STOP-RESULT-1 on #985): statesOf's own check says so, the same tests)
// (the modules imported from the .tex's folder so far: printed with each item, before its result (daybreak3's
//  ENGINE-DEPS-PARTIAL-1: a Run stopped later still records what its earlier results used; astra's DEP-PARTIAL-COMMIT-1:
//  a result printed is always after a line naming what it used), the last line counting; the results file records
//  them with their hashes, so an edited helper's old results are never used (Codex W01))
/** The session's script (run in Sage mode, so preparsed itself: it is written to mean the same after that): each item
 * preparsed, then exec'd (sagesilent, sageblock) or eval'd (\sage: its latex(); \sageplot: its SVG), in the session's
 * globals (Sage's var() defines its names there), put back first as they were before the first Run (a name from an
 * earlier Run is gone, a Sage name it redefined, x say, is Sage's again), in order; each result printed
 * as one line at once. `items`: [{mode, code}], the runnable ones. `dir`: the .tex's folder (its files given to the
 * session by putFolder), the working folder and on sys.path last, as real SageTeX has it: `sage doc.sagetex.sage`,
 * run in the document's folder, imports a helper.py beside the .tex, and its sys.path ends with that folder, so a
 * statistics.py there doesn't hide the standard one (the CLI's own, src/latex-cli.ts). The previous Run's folder is
 * taken off, and the modules imported from either dropped: a helper is imported afresh each Run, its edits seen, as by
 * a fresh sage process; and a document in another folder imports its own.
 * @interact in a Run, a Sagebrush extension (William, Nov 8: "@interact inside sagesilent/sageblock as a documented
 * Sagebrush extension"; upstream SageTeX and Sage 10.10 raise NameError on it): each interact an item makes is kept with
 * that item's result (its "interacts"), its controls (the spec _interact gives a host that draws them) and what its
 * function shows at the defaults, its printing and what it show()s (a plot as its SVG, anything else as text), bounded.
 * The script is that host only while it runs: the runtime's own host and display are put back after it, a Stop
 * included (the loop's finally). */

// The LaTeX editor's file bytes <-> text (plan sbspace r5 §4, r6b E5): a file is opened as text only if it can be
// written back exactly, and saved only as what it was opened as.
//  - UTF-8, decoded fatally, with a leading BOM kept as U+FEFF in the text (ignoreBOM), so it is encoded once, never
//    prepended; a NUL or invalid UTF-8: not text (no editor, no preview).
//  - Line endings: a <textarea> turns CRLF into LF, so a file that is all CRLF is saved with CRLF; one that mixes line
//    endings, or has a lone CR, opens without Save.
//  - The round trip is asserted when the file is opened: the text, encoded back, must be the bytes read, or the file
//    opens without Save ("can't be written back exactly"). Saving encodes the same way.
export const EDIT_MAX = 4 * 2 ** 20;   // bytes: the editable limit, opening and saving

export type Opened =
  | { kind: "text"; text: string; eol: "\n" | "\r\n"; saveable: true }
  | { kind: "text"; text: string; eol: "\n" | "\r\n"; saveable: false; why: string }
  | { kind: "binary"; why: string };

const sameBytes = (a: Uint8Array, b: Uint8Array) => a.length === b.length && a.every((x, i) => x === b[i]);

/** The text and line ending of a file's bytes, and whether it may be saved. */
export function openBytes(bytes: Uint8Array): Opened {
  if (bytes.includes(0)) return { kind: "binary", why: "it isn't valid UTF-8 text (it has a NUL byte)" };
  let decoded: string;
  try {
    decoded = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes);
  } catch {
    return { kind: "binary", why: "it isn't valid UTF-8 text" };
  }
  const crlf = (decoded.match(/\r\n/g) ?? []).length, cr = (decoded.match(/\r/g) ?? []).length, lf = (decoded.match(/\n/g) ?? []).length;
  if (cr !== crlf || (crlf > 0 && lf !== crlf)) return { kind: "text", text: decoded.replace(/\r\n?/g, "\n"), eol: "\n", saveable: false, why: "this file mixes line endings" };
  const eol = crlf > 0 ? "\r\n" : "\n";
  const text = eol === "\r\n" ? decoded.replace(/\r\n/g, "\n") : decoded;
  if (bytes.length > EDIT_MAX) return { kind: "text", text, eol, saveable: false, why: "it is over the prototype's 4 MiB limit" };
  if (!sameBytes(encodeText(text, eol), bytes)) return { kind: "text", text, eol, saveable: false, why: "this file can't be written back exactly" };
  return { kind: "text", text, eol, saveable: true };
}

/** The bytes a text is saved as: UTF-8 (a leading U+FEFF is the BOM, once), with the file's own line ending. */
export function encodeText(text: string, eol: "\n" | "\r\n"): Uint8Array {
  // (a textarea's value has only LF; a CR that reached it anyway is normalized the same way)
  const t = text.replace(/\r\n?/g, "\n");
  return new TextEncoder().encode(eol === "\r\n" ? t.replace(/\n/g, "\r\n") : t);
}

// A shared talk on the share page (/s/<id>, web/share-client/view.ts, sync-docs' side): its slides drawn read only with
// the author's results, and its code run on the visitor's click, in the runner (the opaque-origin sandbox, no storage,
// no network, never a fallback), with the share's files of the .tex's folder mounted read only. The results stay in this
// page: nothing is written or published, and a reload shows the author's again. The agreed shape:
// /scratch/sagebrush-plans/specs/S2-runner.md (astra's SEC design, Nov 12).
// A chunk of its own, /sagebrush-latex-share.js: the editor's parts are loaded by URL (the files the editor caches),
// never bundled here: the page module's mountEditor (the read-only preview), Run's (run-core), the presenter's and the
// interacts'.
import type { LatexEditor, mountEditor as MountEditor } from "./component";

type Remote = { url: string; sha256: string; size: number };
export type SharedOpts = {
  /** The .tex's path in the share's manifest ("talks/st.tex"). */
  path: string;
  /** Its text, SHA-checked by the share page. */
  text: string;
  /** The author's "<path>.results.json", parsed and SHA-checked by the share page; null if the share has none. */
  results: unknown | null;
  /** The page's kernel and runner classes, and the runner's URL; null where this browser can't make the runner. */
  sandbox: { WorkerKernel: unknown; RunnerWorker: unknown; runnerUrl: string } | null;
  /** The share's files ([manifest path, {url, sha256, size}]): only those under the .tex's folder are given to Sage. */
  mount: [string, Remote][];
  say(text: string): void;
  onRunning(on: boolean): void;
  /** After each render, what the document has: code to run (Run's own items) and slides to present (as the editor
   *  decides its Run and Present), so the page offers only those (an article shared from a folder has neither). */
  onShape?(shape: { hasCode: boolean; hasSlides: boolean }): void;
};
export type Shared = { run(): void; stop(): void; present(): void; dispose(): void };

const at = (f: string) => new URL(f, import.meta.url).href;
type RunCore = typeof import("./run-core.mjs");
let runMod: Promise<RunCore> | null = null, presentMod: Promise<typeof import("./present")> | null = null, interactMod: Promise<typeof import("./interact")> | null = null;
// (a load that fails is forgotten: the next click tries again)
const load = <T>(get: () => Promise<T> | null, set: (p: Promise<T> | null) => void, f: string): Promise<T> => get() ?? (set((import(at(f)) as Promise<T>).catch((e) => { set(null); throw e; })), get()!);
const loadRun = () => load(() => runMod, (p) => { runMod = p; }, "sagebrush-latex-run.js");
const loadPresent = () => load(() => presentMod, (p) => { presentMod = p; }, "sagebrush-latex-present.js");
const loadInteract = () => load(() => interactMod, (p) => { interactMod = p; }, "sagebrush-latex-interact.js");
// (this page's words where the editor's would point elsewhere (board): the visitor is on the site already, and sees only
//  the slides)
const NO_SANDBOX = "Run needs the sandbox Sagebrush runs code in, which this browser doesn't have: open this page in Chrome or Edge";
// (the results file's whole size, as the editor's Run bounds it)
const RESULTS_MAX = 8 * 2 ** 20;

/** The folder of a manifest path ("" for the share's top), or null for one that isn't a plain relative path: no leading
 *  "/", no "\\", no empty, "." or ".." part (astra: the folder boundary normalized, never trusted). */
export function folderOf(path: string): string | null {
  if (typeof path !== "string" || !path || path.startsWith("/") || path.includes("\\")) return null;
  const parts = path.split("/");
  if (parts.some((p) => p === "" || p === "." || p === "..")) return null;
  return parts.slice(0, -1).join("/");
}
/** The entries of `mount` in `dir` (folderOf's) or under it, each a plain relative path; anything else left out. */
export function mountIn(mount: [string, Remote][], dir: string): [string, Remote][] {
  return (Array.isArray(mount) ? mount : []).filter((e) => Array.isArray(e) && folderOf(e[0]) !== null && (dir === "" || e[0].startsWith(dir + "/")) && !!e[1] && typeof e[1].url === "string" && typeof e[1].sha256 === "string" && Number.isSafeInteger(e[1].size))
    .map(([p, r]) => [p, { url: r.url, sha256: r.sha256, size: r.size }]);
}
/** The author's results as the renderer reads them, or none: the editor's results file (format, version, wrapper,
 *  items), its items' own checks left to the renderer (savedStates). */
export function savedOf(j: any): { wrapper: string | null; saved: unknown[] } {

// Splitting a large top-level chunk of the renderer's HTML into pieces (plan sbspace r5 §4, in the Worker), so that
// no single insertion is larger than PIECE_MAX:
//  - a container (a theorem div.thm, a proof div.proof, a list ol/ul.list, and the other block divs) is split at its
//    top-level children; each later piece is a COPY of the container (same tag and classes, plus "cont"; no id, no
//    head), so styles carry over; list items keep their explicit labels (span.lbl: the list CSS has no counters);
//  - a paragraph div.p is split at the boundaries between its inline runs, each later piece a div.p.cont;
//  - a table is never split (its columns would misalign): over PIECE_MAX it is a placeholder, with its size;
//  - nor a beamer slide (section.slide: a box of fixed size), the same way, its placeholder still that slide (its own
//    open tag: Present and the tools find every frame);
//  - anything that can't be split into pieces of PIECE_MAX or less (one inline element, one cell, one formula), and
//    any chunk over CHUNK_MAX, is a placeholder saying so, with its size.
// A piece's size against PIECE_TARGET and PIECE_MAX leaves out the data: URLs of its images' src (a \sageplot's SVG,
// sagetex.mjs): one attribute value, read in one pass, not markup to parse; CHUNK_MAX counts every byte.
// The input is the renderer's own HTML: well formed, every text escaped (no raw "<" in text), attributes quoted.
export const PIECE_MAX = 128 * 1024, CHUNK_MAX = 2 * 2 ** 20;
// (the size aimed for: smaller pieces parse in less time each; PIECE_MAX stays the most any piece may be)
