type Content = ({ type: "text"; text: string } | { type: "image"; data: string; mimeType: string })[];
const SLIDE_W = 1024, PAGE_W = 816, MAX_SHOTS = 40;
export const DEFAULT_SHOTS = 12;

function report(t: ToolTarget): CheckResult | null {
  const c = t.lastCheck();
  if (!c) return null;
  const imgs = Object.entries(t.images).map(([name, v]) => (typeof v === "string" ? { name, found: true } : { name, found: false, why: v.why }));
  return checkResult(t.file(), t.text(), c, imgs);
}

export function latexCheck(t: ToolTarget, format?: string): { content: Content } {
  const r = report(t)!;
  return { content: [{ type: "text", text: format === "text" ? checkText(r) : JSON.stringify(r) }] };
}

export async function latexRender(t: ToolTarget, frames?: number[], steps?: boolean): Promise<{ content: Content }> { return shots(t, frames, !!steps); }

/** latex_build's pages (chat plan PR 4b, packet §8 as daybreak2's Q3 amends it, f376e681; astra's and daybreak3's
 * acceptance), each in turn, serially:
 *   - its natural scale s0 = min(1, maxPx/w, maxPx/h); under `minScale` it is omitted (`overflow`), never drawn;
 *   - `room(kept)`: the exact base64 bytes the next page's PNG may take, the result as serialized with what is kept;
 *   - the scale s = min(s0, the scale whose estimate fits room), the estimate the running maximum of base64 bytes per
 *     output pixel (seeded `bpp`, raised by every PNG measured, dropped ones too); under `minScale`, dropped unencoded;
 *   - encoded at s and measured: kept if it fits; else one retry at s·(0.95·room/B), from the scale used (linear: text
 *     costs more per pixel as it shrinks, about s^1.3, so for any exponent of at least 1 it lands within 0.95·room;
 *     daybreak2's measured amendment), only if that is at least `minScale` (always below s); still too large, dropped.
 *     At most 2 encodes a page;
 *   - `alive()` asked before and after each encode: false, and nothing more is drawn or returned (null). */
export type PageFit = { maxPx: number; minScale: number; bpp: number; room(kept: { n: number; w: number; h: number; png: string }[]): number; alive(): boolean };
export type PageAttempt = { n: number; s: number; w: number; h: number; bytes: number; kept: boolean };
export async function buildPages(t: ToolTarget, want: number[], fit: PageFit) {
  try {
    const r = await shots(t, want, false, fit);
    return { summary: JSON.parse((r.content[0] as { text: string }).text), pages: r.pages!, overflow: r.omitted!, dropped: r.dropped!, attempts: r.attempts! };
  } catch (e) { if (e === ENDED) return null; throw e; }
}
const ENDED = new Error("ended");

let katexCss: Promise<string> | null = null;
const dataUrl = async (blob: Blob) => await new Promise<string>((ok, no) => { const f = new FileReader(); f.onload = () => ok(String(f.result)); f.onerror = () => no(f.error); f.readAsDataURL(blob); });
/** KaTeX's stylesheet as the page has it, its fonts (WOFF2) as data: URLs: an SVG drawn as an image loads nothing. */
function katexStyles(): Promise<string> {
  return (katexCss ??= (async () => {
    const url = new URL("katex/katex.min.css", location.href);
    const css = await (await fetch(url)).text();
    const names = [...new Set([...css.matchAll(/url\((fonts\/[A-Za-z0-9_-]+\.woff2)\)/g)].map((m) => m[1]))];
    const urls = new Map<string, string>();
    await Promise.all(names.map(async (n) => { try { urls.set(n, await dataUrl(await (await fetch(new URL(n, url))).blob())); } catch {} }));

// Where you were in a .tex (design/view-state.md, kind tex): the source's top line and cursor, and the preview's top
// group and the offset in it, kept in this browser and put back when the file is opened again. Its own chunk,
// /sagebrush-latex-view.js, fetched as the page opens a file; the page keeps only the import and the guard that says
// the person has moved before it came (daybreak2's SIZE plan for V1, Nov 10)
import { keepView, viewToRestore, type View } from "../workspace/view-state";

type Ed = {
  src: HTMLTextAreaElement; hl: HTMLElement;
  groups: () => { el: HTMLElement; start: number; end: number }[];
  onRendered: (f: () => void) => () => void;
};

// the source line of an offset
const lineAt = (t: string, off: number) => { let n = 0; for (let i = t.indexOf("\n"); i >= 0 && i < off; i = t.indexOf("\n", i + 1)) n++; return n; };
const num = (v: unknown, d: number) => (typeof v === "number" && Number.isFinite(v) ? v : d);

/** Keeps `fid`'s view from now on, and puts the kept one back once, after the preview's first layout, unless `moved`
 *  (the person scrolled, typed, clicked or touched before this came, or the URL has a target). Ends with `signal`. */
export function attachView(E: Ed, right: HTMLElement, fid: string, moved: boolean, signal: AbortSignal) {
  const key = { kind: "tex" as const, id: fid }, { src, hl } = E;
  const read = (): View | null => {
    const lines = hl.children, t = src.value;
    let line = 0;
    while (line < lines.length - 1 && (lines[line + 1] as HTMLElement).offsetTop <= src.scrollTop) line++;
    const v: View = { src: { line, sel: src.selectionStart } };
    const gs = E.groups(), top = right.getBoundingClientRect().top, g = gs.find((x) => x.el.getBoundingClientRect().bottom > top);
    const max = right.scrollHeight - right.clientHeight;
    if (g) v.preview = { anchor: lineAt(t, g.start), dy: Math.round(top - g.el.getBoundingClientRect().top), frac: max > 0 ? right.scrollTop / max : 0 };
    return v;
  };
  // (asked once: its listeners go then, or when the file closes first)
  const ask = viewToRestore(key, right.parentElement ?? right, moved);
  let asked = false;
  const restore = () => (asked ? null : ((asked = true), ask()));
  signal.addEventListener("abort", () => void restore());
  const apply = (v: View | null) => {
    // (done, put back or not: the page test's mark)
    right.dataset.view = "1";
    if (!v) return;
    const s = v.src as View | undefined, p = v.preview as View | undefined;
    if (s) {
      // (the cursor first, the scroll after: placing the cursor can't move the source then)
      const sel = num(s.sel, -1);
      if (sel >= 0 && sel <= src.value.length) src.setSelectionRange(sel, sel);
      const l = hl.children[num(s.line, 0)] as HTMLElement | undefined;
      if (l) src.scrollTop = l.offsetTop;
    }
    if (p) {
      // (the group that began on that line; gone, the fraction; else the top: never an error)
      const t = src.value, g = E.groups().find((x) => lineAt(t, x.start) === num(p.anchor, -1));
      if (g) right.scrollTop += g.el.getBoundingClientRect().top - right.getBoundingClientRect().top + num(p.dy, 0);
      else right.scrollTop = Math.max(0, Math.min(1, num(p.frac, 0))) * (right.scrollHeight - right.clientHeight);
    }
  };
  // (once, after the first layout: now if the preview is already there, else at its first render)
  if (E.groups().length) apply(restore());
  else { const off = E.onRendered(() => { off(); apply(restore()); }); signal.addEventListener("abort", off); }
  const kept = keepView(key, read);
  const changed = () => kept.changed();
  for (const [el, evs] of [[src, ["scroll", "keyup", "click"]], [right, ["scroll"]]] as const)

// The LaTeX editor's engine (a module Worker, dist/sagebrush-latex-worker.js; plan sbspace r5 §4): the source text
// expanded and rendered off the page's thread, its chunks split into pieces (split.ts), bounded.
// In:  {doc, rev, text, images, inputs?, cold?, reset?}   (doc and rev: the page's request token, echoed back;
//      inputs: {docPath, known, version}, the files \input reads, inputs.ts: kept until the next)
// Out: {doc, rev, ok, items: [{g, h}], groups, pos, imageRefs, inputRefs, stats, check} or {doc, rev, ok: false, error}
//   items: every piece in order; g: the index of the chunk it came from (a group is replaced as one unit).
//   pos: per group, the source offset where it begins (-1: none known), for keeping source and preview in sync.
// KaTeX's renderToString comes from the site's shared sagebrush-math.js, imported once (no copy of KaTeX here).
import "./engine/shim.mjs";
import { Engine, withBeamer, withPythontex, installPythontex, once, declaresBeamer } from "./engine/pipeline.mjs";
import { setKatex, installBeamer } from "./engine/render.mjs";
import { splitChunk, bytes, tooLargeProblem } from "./split";
import { WRAPPER_VERSION, itemKey } from "./engine/sagetex.mjs";
import { engineInputs, type Known } from "./inputs";

export const RENDER_BOUNDS = { chunks: 20000, html: 16 * 2 ** 20 };
const TOO_LARGE = '<div class="bounderr">This document is too large for the prototype\'s preview.</div>';

let eng: any = null;
// (the page's included files, kept from the last message that had them: inputs.ts)
let inputs: { docPath: string; known: Map<string, Known>; version: number } | null = null;
const ready = import(/* @vite-ignore */ new URL("sagebrush-math.js", self.location.href).href).then((m: any) => setKatex(m.renderToString));
// (beamer's code, engine/beamer.mjs: a chunk of its own beside this worker (same origin, the same dist/ as the worker
//  itself), fetched once, when a render first says it needs it; a failed fetch stays failed until a reload)
const loadBeamer = once(() => import(/* @vite-ignore */ new URL("sagebrush-latex-beamer.js", self.location.href).href).then(installBeamer));
// (PythonTeX's results pass, engine/pythontex.mjs: a chunk of its own too, fetched only when a document has a PythonTeX
//  result to read back (the update's needPy); then the same text rendered again, not expanded again)
const loadPythontex = once(() => import(/* @vite-ignore */ new URL("sagebrush-latex-pythontex.js", self.location.href).href).then(installPythontex));

self.onmessage = async (e: MessageEvent) => {
  const m = e.data || {};
  const echo = { doc: m.doc, rev: m.rev };
  try {
    // (a document that declares beamer: its chunk fetched with KaTeX's, before the first render, so that render is the
    //  only one; a failed fetch is withBeamer's below, the notice)
    await Promise.all([ready, declaresBeamer(String(m.text ?? "")) && loadBeamer().catch(() => {})]);
    // (saved results only of this wrapper: sagetex.mjs's WRAPPER_VERSION is part of every item's key too)
    const sage = m.sage && m.sage.wrapper === WRAPPER_VERSION && Array.isArray(m.sage.saved) ? { saved: m.sage.saved.slice(0, 1000) } : undefined;
    if (!eng || m.reset) eng = new Engine({ images: m.images || {}, sage });
    else eng.opts = Object.assign({}, eng.opts, { images: m.images || {}, sage });
    if (m.inputs && typeof m.inputs.docPath === "string" && Array.isArray(m.inputs.known)) inputs = { docPath: m.inputs.docPath, known: new Map(m.inputs.known.slice(0, 1024)), version: Number(m.inputs.version) || 0 };
    const ei = inputs ? engineInputs(inputs.docPath, inputs.known) : null;
    const text = String(m.text ?? ""), opts = ei ? { inputs: { files: ei.files, resolve: ei.resolve, version: inputs!.version } } : {};
    // (rendered again with beamer's code: the same text, so not expanded again)
    let r = await withBeamer(eng.update(text, { cold: !!m.cold, ...opts }), loadBeamer, () => eng.update(text, opts));
    if (r.needPy) r = await withPythontex(r, loadPythontex, () => eng.update(text, opts));
    // (each piece with its UTF-8 size, b: the page's patch budget charges the same measure as split.ts)
    const items: { g: number; h: string; b: number }[] = [];
    let total = 0, stopped = false;
    // (a chunk shown as a placeholder: latex_check's warning at its place, check.ts)
    const tooLarge: { kind: string; name: string; at: number }[] = [];
    if (r.chunks.length > RENDER_BOUNDS.chunks) stopped = true;
    for (let g = 0; g < r.chunks.length && !stopped; g++) {
      for (const h of splitChunk(r.chunks[g], (why, size) => tooLarge.push(tooLargeProblem(why, size, r.chunkPos?.[g])))) {
        const b = bytes(h);
        total += b;
        if (total > RENDER_BOUNDS.html) { stopped = true; break; }
        items.push({ g, h, b });
      }
    }

// The Python library for the browser in chunks (web/build.ts): the worker
// carries only a manifest, and fetches a chunk the first time a module of it
// is imported (web/lib-lazy.ts), or when a mode that needs it starts.  A blank
// Python notebook then loads none of it; Sage mode fetches Sage's.
//
// A group is a set of library files, and has two chunks: its sources ("src",
// needed to import any of them) and their code compiled when the site was
// built ("pre", src/compile.ts's precompiled entries; used only if it is
// there).  The groups come from what each mode's start compiled (the
// recordings, SAGEBRUSH_PRECOMPILE_OUT): a file goes to the first of
//   core    what plain Python imports first, and what Sage and the
//           scientific modules share
//   sci     numpy, matplotlib, k3d, ipywidgets (MATLAB's start too; scipy.io
//           is a package's, @sagebrush/scipy-io)
//   sage    Sage mode's start (Magma's too)
//   matlab  MATLAB mode's start
//   magma   Magma mode's start
//   rill    Rill's (R's) start, checked after the others, so a file another start
//           uses stays in theirs (design/rill.md §6.1)
//   sprig   Sprig's start, checked last (design/sprig-mvp.md §6.1)
// that it is in; files no start uses are grouped by family (sage-more,
// matlab-more, magma-more; MATLAB's sparse LU, _matlab_lu and _matlab_colamd,
// is matlab-lu) or are a group of their own (mod-<name>: a
// top-level module or package, its name in lowercase letters, digits and
// "-"; scipy.special, scipy.stats and scipy.optimize are mod-scipy-special,
// mod-scipy-stats and mod-scipy-optimize, apart from scipy's other submodules;
// fredapi, yfinance and _sbdata_live together are mod-live-data).  Each package (packages/<name>/, scripts/packages.mjs) is a group too,
// pkg-<name>, its files by "<name>/<path>", with its compiled code too if a
// mode's start imports it (recorded as "pkg:<name>/<path>"), and in that
// mode's start then; the manifest carries the packages' registry
// (src/compile.ts checks each file against it).  A chunk's file name has its content's
// SHA-256, and the manifest the whole hash, which the worker checks before it
// uses one (design/security.md, SEC-8D6-1: a cached copy is origin storage).
import { createHash } from "node:crypto";

export type Recording = { build: string; modules: Record<string, { code: string; lineMap: unknown; path: string }> };
export type ChunkRef = { file: string; sha256: string; size: number };
export type LibManifest = {
  build: string;
  /** library path -> its group */
  files: Record<string, string>;
  /** group -> its chunks */
  chunks: Record<string, { src: ChunkRef; pre?: ChunkRef }>;
  /** mode -> the groups its start needs, fetched when the mode starts */
  modes: Record<string, string[]>;
  /** the packages' registry, and each package file ("<dir>/<path>") -> its group */
  packages: { registry: unknown; files: Record<string, string> };
  /** group -> its offline item (web/offline-inventory.mts), set by web/build.ts */
  items?: Record<string, string>;
  /** the pinned zone data's index (web/tzdata-chunks.mts), for a browser's time */
  tzdata?: ChunkRef & { version: string };
};
export type Packages = { registry: { packages: Record<string, { dir: string }> }; files: Record<string, string> };

export const START_ORDER = ["core", "sci", "sage", "matlab", "magma", "rill", "sprig"] as const;

// (the mod- groups groupOf gives several top-level names on purpose, which the clash check below lets through)
const SHARED_MOD_GROUPS = new Set(["mod-live-data", "mod-pathlib", "mod-xml", "mod-time"]);
// (each mode's own families: a mode's group holds only these.  Any other file its start imports gets a group of its
// own (or its family's: the time module's _pytime and _tzrules, mod-time), so importing it never fetches a mode's

// The Python library in the browser's worker, fetched in chunks
// (web/lib-chunks.mts, made by web/build.ts): this worker carries only the
// manifest, and globalThis.__PYJS_LIB__ (src/compile.ts) is an object with a
// property per library file whose getter fetches that file's group the first
// time any of its files is read (an import: synchronously, as the engine is
// fetched).  A mode's start fetches its groups beforehand, asynchronously
// (prefetchMode).  A chunk is used only if its bytes have the SHA-256 in the
// manifest: a cached copy is origin storage, which any script of the origin
// can write (design/security.md, SEC-8D6-1).  Sources must be there to import
// a module; compiled code ("pre") is used when it is, and otherwise the
// module compiles from its source.
//
// The packages' files (packages/, src/compile.ts) are fetched the same way,
// as globalThis.__SAGEBRUSH_PACKAGES__ {registry, files}.
//
// It must be imported before src/compile.ts, which reads __PYJS_LIB__ and
// __SAGEBRUSH_PACKAGES__ when it is loaded.
import { sha256Hex } from "../src/runtime/sha256";
import type { LibManifest } from "./lib-chunks.mts";

declare const __SB_LIB__: LibManifest;
const g = globalThis as any;
const M = __SB_LIB__;
type Kind = "src" | "pre";
const sources: Record<string, string> = Object.create(null);
const pkgSources: Record<string, string> = Object.create(null);
const installed = new Set<string>(); // group + "." + kind
const precompiled = { build: M.build, modules: Object.create(null) };
g.__SAGEBRUSH_PRECOMPILED__ = precompiled;

// A chunk's URL: beside this worker, or (a downloaded file's runner, files
// mode) the blob: URL it was given, or none (that file doesn't carry it)
function chunkUrl(file: string): string | null {
  const files: Record<string, string> | undefined = g.__SB_FILES__;
  if (files) return files[file] ?? null;
  return new URL(file, g.__SB_BASE__ ?? self.location.href).href;
}

export async function digestHex(bytes: ArrayBuffer | Uint8Array): Promise<string> {
  // (the native digest where there is one: 15 MB took 130 ms in the
  // synchronous JS SHA-256, 11 ms natively; the runner's worker is not a
  // secure context, so no crypto.subtle there: the synchronous one)
  const subtle = g.isSecureContext ? globalThis.crypto?.subtle : undefined;
  const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  if (!subtle) return sha256Hex(view);
  const h = new Uint8Array(await subtle.digest("SHA-256", view));
  return Array.from(h, (b) => b.toString(16).padStart(2, "0")).join("");
}

