  try { const r = await fetch(new URL("sagebrush-math.js", base).href, { cache: "no-store" }); k = `${r.status} ${r.headers.get("content-type") ?? ""}`; await r.body?.cancel(); } catch (e) { k = "error " + (e?.message ?? e); }
  const analyzed = !a?.error && (a?.defs ?? []).includes("selftest_board_y");
  out.push([BOARD_CHECKS[2], analyzed && /^200 .*javascript/.test(k), `at ${new URL(base).pathname}: analyzer ${analyzed ? "answered" : JSON.stringify(a?.error ?? a).slice(0, 120)}; sagebrush-math.js ${k}`]);
  return out;
}

// The app self-test's diagnosis of cross-origin isolation, a module of its
// own (web/build.ts -> sagebrush-selftest.js), imported by selftest() in
// web/index.html only when the app's self-test runs, so the page everyone
// loads carries only that call (app/selftest/check-diagnose-lazy.mjs checks
// it).  diagnoseLines(kernel) gives the report's "info <key>: <value>" lines,
// every key once, in SELFTEST_INFO_KEYS's order (android-report.py's closed
// list).
//
// What the page and its kernel see, and what the app's server
// answers to two marked same-origin fetches (?sb-diag=, which the debug
// app's server log tells apart from the page's own loads).  Bounded: 5 s per
// fetch, 15 s in all; a key not reached keeps 'error: "not reached"'.  Each
// value is one line of at most 200 characters (400 for the fetches' two
// full URLs), longer ones cut with "...(truncated N)".
export const SELFTEST_INFO_KEYS = ["origin", "secure-context", "top-level", "isolated-document", "sab-document", "coi-policy", "kernel-interrupt-shared", "kernel-isolated", "kernel-sab", "fetch-page", "fetch-kernel-script", "user-agent"];
async function diagnose(info, kernel) {
  const cap = (s, n = 200) => (s.length > n ? s.slice(0, n) + "...(truncated " + (s.length - n) + ")" : s);
  const str = (v) => cap(JSON.stringify(String(v)));
  const err = (e) => "error: " + str((e?.name ?? "Error") + ": " + (e?.message ?? e));
  const bool = (v) => (v === true ? "true" : v === false ? "false" : "error: " + str("not a boolean: " + v));
  // (each fetch aborts after 5 s, or when the whole diagnosis runs out)
  const pending = new Set();
  let retired = false;  // (set when the whole diagnosis runs out: no new fetch starts after it)
  const probe = async (url, corp) => {
    if (retired) return "timeout";
    const ac = new AbortController();
    pending.add(ac);
    const timer = setTimeout(() => ac.abort(), 5000);
    try {
      const r = await fetch(url, { cache: "no-store", signal: ac.signal });
      const q = new URL(url), u = new URL(r.url);
      const o = { status: r.status, ok: r.ok, requested: q.origin + q.pathname + q.search, final: u.origin + u.pathname + u.search, redirected: r.redirected, COOP: r.headers.get("cross-origin-opener-policy"), COEP: r.headers.get("cross-origin-embedder-policy") };
      if (corp) o.CORP = r.headers.get("cross-origin-resource-policy");
      await r.body?.cancel().catch(() => {});
      return cap(JSON.stringify(o), 400);  // (two full URLs and the headers)
    } catch (e) {
      return ac.signal.aborted ? "timeout" : err(e);
    } finally {
      clearTimeout(timer);
      pending.delete(ac);
    }
  };
  const facts = async () => {
    info.origin = str(location.origin);
    info["secure-context"] = bool(window.isSecureContext);
    info["top-level"] = bool(window.top === window);
    info["isolated-document"] = bool(window.crossOriginIsolated);
    info["sab-document"] = str(typeof SharedArrayBuffer);
    // (the permission policy, where it can be asked, and only for a feature
    // name it knows)
    try {
      const pp = document.permissionsPolicy ?? document.featurePolicy;
      info["coi-policy"] = !pp ? "unsupported" : !pp.features().includes("cross-origin-isolated") ? "unrecognized" : bool(pp.allowsFeature("cross-origin-isolated"));
    } catch (e) { info["coi-policy"] = err(e); }
    info["kernel-interrupt-shared"] = bool(!!kernel.interruptFlag);
    const c = kernel.context;
    info["kernel-isolated"] = c ? bool(c.isolated) : 'error: "the kernel sent no context"';
    info["kernel-sab"] = c ? str(c.sab) : 'error: "the kernel sent no context"';
    info["user-agent"] = str(navigator.userAgent);
    info["fetch-page"] = await probe(new URL(location.pathname + "?sb-diag=1", location.href).href, false);

// sagebrush-selftest.js's entry (web/build.ts): the app self-test's lazily loaded module, imported by selftest()
// in web/index.html only when the app's self-test runs.  The COI diagnosis (selftest-diagnose.js, whose source
// app/selftest/test-diagnose.mjs also runs as a plain script, so it holds no re-export) and the Terminal's checks
// of its shell worker in the real app (selftest-terminal.js), and the LaTeX editor's (selftest-latex.js).
export * from "./selftest-diagnose.js";
export { terminalChecks, TERMINAL_CHECKS } from "./selftest-terminal.js";
export { latexChecks, LATEX_CHECKS } from "./selftest-latex.js";
export { boardChecks, BOARD_CHECKS } from "./selftest-board.js";

// The LaTeX editor in the desktop app, for the app's self-test (selftest() in web/index.html, last: its page takes the
// notebook page over): the editor on, with File ▸ New ▸ LaTeX document; a .tex written to the workspace, mounted as
// /?tex=<fid> mounts it (web/latex/boot.ts mountTex, with this page's own sandbox and Share) and rendered, a section
// title and a formula in its preview; and what the app doesn't offer said rather than done: Share disabled with its
// reason, no Agent, and Run answering why it doesn't run (no sandbox in the app), its Sage never started.
export const LATEX_CHECKS = ["the LaTeX editor is on in the desktop app", "a .tex opens in the editor and renders", "Share, Agent and Run say what the app doesn't offer"];
// (a SageTeX item, so that Run is shown; a formula, so that the preview's math is drawn)
const TEX = "\\documentclass{article}\n\\usepackage{sagetex}\n\\begin{document}\n\\section{Hello from the app}\nTwo is $\\sage{1+1}$, and $x^2 + 1$.\n\\end{document}\n";
const until = async (f, ms) => {
  for (const t = Date.now(); Date.now() - t < ms; await new Promise((r) => setTimeout(r, 100))) { const v = f(); if (v) return v; }
  return null;
};

/** The checks, each [name, ok, detail], in the desktop app only (`desktop`, the page's desktopApp(): none elsewhere, so
 * a phone's report has none, as its judge requires, app/selftest/android-report.py without --desktop): `on`, the page's
 * latexHere; `menu`, its File menu; `ws`, its workspace; `mount(root, ws, fid)`, the editor mounted as the page does. */
export async function latexChecks({ desktop, on, menu, ws, mount }) {
  if (desktop !== true) return [];
  const out = [];
  const item = menu?.querySelector('[data-item="newLatex"]');
  const itemState = item ? (item.hidden ? "hidden" : item.disabled ? "disabled" : "shown") : "none";
  out.push([LATEX_CHECKS[0], on === true && itemState === "shown", "on=" + on + " New > LaTeX document: " + itemState]);
  if (!ws) return [...out, [LATEX_CHECKS[1], false, "no workspace"], [LATEX_CHECKS[2], false, "not opened"]];
  const path = "/selftest-latex-" + crypto.randomUUID().slice(0, 8) + ".tex";
  const root = document.createElement("div");
  document.body.append(root);
  try {
    const e = await ws.createByPerson(path, { content: new TextEncoder().encode(TEX) });
    await mount(root, ws, e.fid);
    const preview = () => root.querySelector(".tex-preview");
    const shown = await until(() => /Hello from the app/.test(preview()?.textContent ?? "") && preview().querySelector(".katex"), 60000);
    out.push([LATEX_CHECKS[1], !!shown, shown ? "the title and the formula shown" : "preview: " + JSON.stringify((preview()?.textContent ?? "(none)").slice(0, 120))]);
    // (Share: the item the editor's File menu draws, disabled, its reason as its title; Agent: no button; Run: shown for
    //  the SageTeX item, and a click answered with why, nothing started)
    const share = root.querySelector('[data-item="share"]'), agent = root.querySelector(".tex-agent");
    const shareOk = !!share && share.disabled && /Sharing isn't available here/.test(share.title);
    const agentOk = !agent || agent.hidden;
    const run = await until(() => { const b = root.querySelector(".tex-run"); return b && !b.hidden ? b : null; }, 30000);
    let runSaid = "";
    if (run) {
      run.click();
      runSaid = (await until(() => { const t = root.querySelector(".tex-status")?.textContent ?? ""; return /desktop app/.test(t) ? t : ""; }, 10000)) ?? "";
    }
    const runOk = !!run && !!runSaid && /desktop app/.test(run.title) && run.textContent === "Run";
    out.push([LATEX_CHECKS[2], shareOk && agentOk && runOk,
      "share=" + (share ? (share.disabled ? "disabled" : "enabled") + " " + JSON.stringify(share.title.slice(0, 60)) : "none") +
      " agent=" + (agent ? (agent.hidden ? "hidden" : "shown") : "none") +
      " run=" + (run ? JSON.stringify(run.textContent) + " said " + JSON.stringify(runSaid.slice(0, 60)) : "not shown")]);
  } catch (e) {
    while (out.length < 3) out.push([LATEX_CHECKS[out.length], false, String(e?.message ?? e)]);
  } finally {
    root.remove();
    await ws.remove(path).catch(() => {});
  }
  return out;
}

// The app self-test's checks of the Terminal's shell worker in the real app (plan-native-checks r2.2, after
// #380; astra's R-NC-1..3, the grader's A/B/AM-1/AM-2), part of sagebrush-selftest.js (imported only when the
// self-test runs).  Three checks, each a REQUIRED report key (app/selftest/run.mjs, android-report.py):
//   1 "the shell worker's policy (lib.rs)": worker-boot.js, 200, not redirected, at its exact URL, JavaScript,
//     with exactly the site's shell worker policy (web/csp-policy.mts shellWorkerPolicy, as lib.rs sends it);
//   2 "the page reaches the app's bridge": the page's own app_log, and the probe (terminal-probe.js) run in the
//     page, which must find a real route and reach the native log (the positive; its detail is the grammar's
//     "nonce=… routes=…", read by app/selftest/probe-log.py with the app's log);
//   3 "the shell worker can't reach the app's bridge": the same probe in a real shell worker (worker-boot.js,
//     as the Terminal starts it, with that response's policy): no route, and every fetch refused WITH its
//     connect-src violation; a worker that never reports fails.
import { shellWorkerPolicy } from "../csp-policy.mts";
import probeText from "./terminal-probe.js" with { type: "text" };

export const TERMINAL_CHECKS = ["the shell worker's policy (lib.rs)", "the page reaches the app's bridge", "the shell worker can't reach the app's bridge"];
const ROUTES = ["tauri-internals-invoke", "tauri-core-invoke", "ipc-postmessage", "webkit-ipc-postmessage", "webview2-postmessage"];

// Check 1's verdict, pure: what the fetch saw against what it must be.
export function policyVerdict(r, expectedUrl, policy = shellWorkerPolicy()) {
  const bad = [];
  if (r.status !== 200) bad.push("status " + r.status);
  if (r.redirected) bad.push("redirected");
  if (r.url !== expectedUrl) bad.push("url " + JSON.stringify(r.url));
  if (!/^(text|application)\/javascript\b/.test(r.contentType ?? "")) bad.push("content type " + JSON.stringify(r.contentType));
  if (r.csp !== policy) bad.push("policy " + JSON.stringify(r.csp));
  return [bad.length === 0, bad.length ? bad.join("; ") : JSON.stringify(r.csp)];
}

// The engine family, from a closed table of the user agent (the grader's condition: fixed by the engine, never by
// what a run observed; the judges outside the page cross-check it with the platform they run on): "chromium"
// (Chrome, Edge/WebView2, Android's WebView), "webkit" (Safari, WKWebView, WebKitGTK), else "unknown" (a FAIL).
export function engineOf(ua) {
  if (typeof ua !== "string" || !ua) return "unknown";
  // (HeadlessChrome/ too: no word boundary before "Chrome" there)
  if (/(?:\b|Headless)(?:Chrome|Chromium|Edg)\//.test(ua)) return "chromium";
  if (/\bAppleWebKit\//.test(ua) && !/\b(Firefox|Gecko\/\d{8})\b/.test(ua)) return "webkit";
  return "unknown";
}

// The three requests the shell worker makes, each of which its policy must refuse (terminal-probe.js start()).
export const REQUESTS = ["ipc-scheme", "ipc-localhost", "own-origin"];
export const requestUrls = (ownUrl) => ({ "ipc-scheme": "ipc://localhost/app_log", "ipc-localhost": "http://ipc.localhost/app_log", "own-origin": ownUrl });

// The forms a violation event's blockedURI may take for a request to `url` from a worker of `origin` (astra's
// NC-R1-A1: explicit normalization rules, nothing looser):
//   not HTTP(S): its scheme alone (CSP 3, "strip URL for use in reports"), or the URL without fragment/credentials;
//   HTTP(S), same origin: the URL without fragment or credentials, only;
//   HTTP(S), another origin: that, or the origin alone (CSP 2's cross-origin rule, which WebKit may still follow).
export function reportForms(url, origin) {
  let u;
  try { u = new URL(url); } catch { return []; }
  u.hash = ""; u.username = ""; u.password = "";
  if (u.protocol !== "http:" && u.protocol !== "https:") return [u.protocol.slice(0, -1), u.href];
  return u.origin === origin ? [u.href] : [u.href, u.origin];
}

// Match the recorded events to the requests, one to one: an event counts for a request only if it is enforced
// (disposition "enforce"), its directive is connect-src and its blockedURI is one of that request's forms; any other
// event (a report-only one, another directive, a URI of no request, or a second for the same request) is
// "unmatched".  -> { per: {request: matching events}, unmatched, total }.

// Turning sync on starts every one of this device's notebooks' synced histories (sync-docs, #1 (a) of William's first
// DEV sync try, Oct 30): a notebook's history starts only at a writer's load with DOC_SYNC on (journal/store.js load,
// then startSynced), so one nobody opens after sync is turned on never goes up, and the other device lists it with
// no content ever.  This walks them, each loaded as its writer and let go, exactly as opening it would: recovery and
// startSynced run as they always do, through no other write path.
//   startAll(seams) -> { total, started, held, tooLarge: [path], noRoom: [path], failed: [path], stopped }
// Seams (the page's; a test's fakes):
//   list()          this device's own notebooks: [{ ref, path }] (not listed from the server, not missing, not in Trash)
//   startOf(ref)    the notebook's synced history's start, or null if it hasn't started here (readJournal's)
//   storeFor(ref)   a journal store for it (the page's storeFor), or one that isn't journaled
//   syncOn()        whether the page's notebooks' sync is (still) on (DOC_SYNC.on)
//   current()       the notebook the page has open (its own load already started it), or null
//   idle()          a pause between notebooks (the page's idle time), resolved when the next may go
//   stopped()       true once the page is leaving: the walk ends where it is, and the next load goes on from there
//   progress(done, total)
// Each load's outcome is the store's own (store.js keeps why a start was refused, `startRefused`): started; another
// tab writes it (a read-only load: held, that tab or a later walk starts it); too large (its root patch, measured under
// the writer's lock as doc-sync would send it, over the batch bound: never started, counted by name); refused for room
// (the walk ends: the rest would be refused the same way); anything else (counted by name, the walk goes on).  Sync
// turned off meanwhile ends the walk (nothing said of the rest; what was counted before may still be said).  Every
// store loaded is let go.
export async function startAll(s) {
  const out = { total: 0, started: 0, held: 0, tooLarge: [], noRoom: [], failed: [], stopped: false };
  const cur = s.current();
  const todo = [];
  for (const n of await s.list()) {
    if (n.ref === cur) continue;
    try {
      if ((await s.startOf(n.ref)) === null) todo.push(n);
    } catch (e) {
      out.failed.push(n.path);
      console.warn("sync: a notebook's synced history not read:", n.path, e);
    }
  }
  out.total = todo.length;
  for (let i = 0; i < todo.length; i++) {
    if (s.stopped() || !s.syncOn()) { out.stopped = true; break; }
    const { ref, path } = todo[i];
    s.progress(i, todo.length);
    let st = null, end = false;
    try {
      // (checked again: another tab may have started it since the list was read)
      if ((await s.startOf(ref)) !== null) continue;
      st = await s.storeFor(ref);
      if (!st?.journaled) continue;
      await st.load();
      if (!st.writer) out.held++;
      else if (st.synced) out.started++;
      else if (!s.syncOn()) { out.stopped = true; end = true; }
      else if (st.startRefused?.tooLarge) out.tooLarge.push(path);
      else if (st.startRefused?.room) { out.noRoom.push(path); end = true; }
      else out.failed.push(path);
    } catch (e) {
      out.failed.push(path);
      console.warn("sync: a notebook's synced history not started:", path, e);
    } finally {
      try { await st?.release?.(); } catch {}
    }
    if (end) break;
    await s.idle();

// A cell's ▶ is its Stop (■) while the cell is queued or running.  On a
// remote kernel the cell shows that it is queued a round trip or more after
// the Run, so a second click meant as Run (a double click, an impatient one)
// could land on Stop.  A bounded UI guard, not a promise about any network:
// a click on Stop within STOP_GUARD_MS of the button turning into Stop, or
// the second click of a double click, is ignored.  The toolbar's Stop and
// the interrupt keys are never guarded.

export const STOP_GUARD_MS = 400;

/** The button turns into Stop: the time is kept only on the actual change from Run (a repeated queued or running update keeps it). */
export function armStop(cell, now = performance.now()) {
  if (cell.runb.textContent !== "■") cell.stopArmedAt = now;
  cell.runb.textContent = "■";
}

/** The button is Run again (the cell settled): no guard is held. */
export function disarmStop(cell) {
  cell.stopArmedAt = null;
  cell.runb.textContent = "▶";
}

/** Whether a click on Stop is ignored: `detail` is the click's count (the event's detail; 0 from the keyboard). */
export function stopIgnored(armedAt, now, detail) {
  return detail > 1 || (armedAt != null && now - armedAt < STOP_GUARD_MS);
}

// Stores for notebook documents (web/notebook/types.ts Store): where a
// notebook is kept, and how changes made elsewhere arrive.
//
//   MemoryStore   a document in memory (embeds, tests)
//   IdbStore      a document in this browser's IndexedDB; other tabs with the
//                 same notebook see each other's changes (BroadcastChannel)
//
// A CoCalc store (the Jupyter syncdb of a .ipynb in a project) has the same
// shape: load() reads the cells, save(doc) writes the changed records,
// subscribe() reports remote changes.
//
// Revisions: a stored document has a revision `rev`, one more at each write.
// A save carries `baseRev`, the revision it was made from, and is written
// only if that is still the stored one (compare and swap): {saved, rev};
// otherwise nothing is written and the result is {conflict: the stored
// document}, which the notebook merges (three ways, from the revision both
// started at) and saves again.  So two tabs editing different cells keep both
// edits, and no write is lost to a stale one (the systematic review's
// R2-DOC-F1).  A save without baseRev is written as it is.
import { noteToken, HIST_STORES } from "../history/tokens";

// The record to write for doc over cur (the stored one), or null on a conflict.
function revise(cur, doc) {
  const { baseRev, ...rec } = doc;
  if (baseRev !== undefined && cur && (cur.rev ?? 0) !== baseRev) return null;
  return { ...rec, rev: (cur?.rev ?? 0) + 1 };
}

export class MemoryStore {
  constructor(doc = { mode: "python", cells: [] }) { this.doc = doc; this.subs = new Set(); }
  async load() { return structuredClone(this.doc); }
  async save(doc) {
    const rec = revise(this.doc, doc);
    if (!rec) return { conflict: structuredClone(this.doc) };
    this.doc = structuredClone(rec);
    return { saved: "saved", rev: rec.rev };
  }
  /** Simulate a change made elsewhere (a new revision). */
  push(doc) {
    this.doc = { ...structuredClone(doc), rev: (this.doc?.rev ?? 0) + 1 };
    for (const f of this.subs) f(structuredClone(this.doc));
  }
  subscribe(f) { this.subs.add(f); return () => this.subs.delete(f); }
}

// IndexedDB "sagebrush": object stores "notebooks" (by id) and "files" (by
// path); "sagebrush-history": "history" (TimeTravel's patches, by [notebook
// id, patch id]); "sagebrush-blobs" (below).  They are opened at whatever version they have, never
// upgraded: an upgrade waits until every page holding the database closes,
// and a page of an older version of the site (another tab, the installed
// app) would hold it.  New stores go in new databases.  A page lets go of a
// database when a newer page needs it (onVersionChange, e.g. to ask for a
// reload).
// (what refuses every save to the notebooks while it says why: set by the page, design/workspace-durability.md A.3)
let saveGate = null;
/** `f()`: why saves are refused now (a string), or nothing to let them go. */
export function setSaveGate(f) { saveGate = f; }
/** The workspace's fence, a record of its own in the notebooks' store (and in their history's): its identity and
 * whether it is quarantined or being reset, written by the workspace (design/workspace-durability.md A.3).  A
 * notebook's or its history's write reads it in the write's own transaction, and is refused when it says the

// Sync's own rows in the history databases (plan-sync-slice2-client r4 §4, F1, F2, F8): where the journal keeps its
// state for a document, beside the document's TimeTravel patches and never among them.
//
// Both history databases ("sagebrush-history", "sagebrush-board-history") are keyed [nb, time].  A document's patches
// are under nb = its id; sync's rows are under nb values that begin with "\u0001" (isSyncKey, stores.js), which no
// document id can (stores.js refuses one at every store it opens), so no per-document range ever holds a sync row:
//   - the registry row (SYNC_NB, "d:" + ns + ":" + doc) gives a document its short handle h, a base-36 counter;
//   - a document's rows are under nb = SYNC_NB + h, their time a family letter and its key:
//       l lseq · o outbox · j jseq · p pending · r recovery · g recgen, reconciling · c receipts · m mode · x op
//       s slots, claims · k cursors · z the collapse marker
//     (lseq-ordered rows zero-padded to 16 digits, so string order is numeric order).
// Every key is bounded before it is built: a handle at most 12 characters, a time at most 40 ASCII characters.
// Every row is charged (F8): its key and value as the store measures them (inert JSON, two bytes a character), plus
// 64 B of overhead, written and released in the same transaction as the row (the journal's PRs).
import { SYNC_KEY_PREFIX, isSyncKey, jsonTextSize } from "./stores.js";

export { isSyncKey };
/** The nb of sync's rows: the registry, and every document's (with its handle after it). */
export const SYNC_NB = SYNC_KEY_PREFIX + "s:";
/** The bounds of a key (F1). */
export const SYNC_KEY_BOUNDS = { handle: 12, time: 40 };
/** The fixed overhead a sync row is charged beside its key and value (F8). */
export const SYNC_ROW_OVERHEAD = 64;
/** The key families: a row's time begins with its family's letter (F2). */
export const FAMILIES = Object.freeze({ lseq: "l", outbox: "o", jseq: "j", pending: "p", recovery: "r", recgen: "g", receipt: "c", mode: "m", op: "x", slot: "s", cursor: "k", collapse: "z" });
const LETTERS = new Set(Object.values(FAMILIES));
const MAX_SAFE = Number.MAX_SAFE_INTEGER;

/** A handle from the registry's counter: base 36, at most 12 characters. */
export function handleOf(n) {
  if (!Number.isSafeInteger(n) || n < 0) throw new RangeError("sync rows: a handle's counter is a safe integer >= 0");
  const h = n.toString(36);
  if (h.length > SYNC_KEY_BOUNDS.handle) throw new RangeError("sync rows: a handle past 12 characters");
  return h;
}
const isHandle = (h) => typeof h === "string" && h.length >= 1 && h.length <= SYNC_KEY_BOUNDS.handle && /^[0-9a-z]+$/.test(h);

/** The nb of a document's rows, from its handle. */
export function docNb(h) {
  if (!isHandle(h)) throw new RangeError("sync rows: a handle is 1 to 12 base-36 characters");
  return SYNC_NB + h;
}

/** The registry row's key for a document of a namespace: [SYNC_NB, "d:" + ns + ":" + doc].  (Its time may be longer
 * than a family key's: it names the document; ns and doc are bounded by their own forms, checked here.) */
export function registryKey(ns, doc) {
  if (typeof ns !== "string" || !/^[0-9A-Za-z_:-]{1,128}$/.test(ns)) throw new RangeError("sync rows: a namespace of 1 to 128 key characters");
  // (every form a document id takes here: a notebook's (a uuid, or where there is none a base-36 time and random part),
  // a board's 12 hex; at most 96 word characters, "-" and ":")
  if (typeof doc !== "string" || !/^[\w:-]{1,96}$/.test(doc)) throw new RangeError("sync rows: a document id of 1 to 96 word characters, - or :");
  return [SYNC_NB, "d:" + ns + ":" + doc];
}

/** A row's key in a document's rows: [docNb(h), letter + rest], at most 40 ASCII characters. */
export function rowKey(h, letter, rest = "") {
  if (!LETTERS.has(letter)) throw new RangeError(`sync rows: an unknown family ${JSON.stringify(letter)}`);
  if (typeof rest !== "string") throw new TypeError("sync rows: a key's rest is a string");
  const time = letter + rest;
  if (time.length > SYNC_KEY_BOUNDS.time || !/^[\x20-\x7e]*$/.test(time)) throw new RangeError("sync rows: a time is at most 40 printable ASCII characters");
  return [docNb(h), time];

// The Terminal's bridge probe (the app self-test; plan-native-checks r2.2, its marker grammar
// app/selftest/probe-grammar.md): ONE text, run twice.  The page imports it as a blob: module and calls probe()
// on itself, the positive: a real transport there must reach the app's native log.  The shell worker gets the
// same text through worker-boot.js's own protocol ({text, port}), which imports it and calls start(port): there
// every route must be unavailable, and the fetches refused by the worker's own policy.  Self-contained (no
// imports): web/notebook/selftest-terminal.js takes it as text.

// (the routes, a closed set in this order: the app's bridge as a page or a worker might see it)
export const ROUTES = ["tauri-internals-invoke", "tauri-core-invoke", "ipc-postmessage", "webkit-ipc-postmessage", "webview2-postmessage"];

// For each route: present and callable in `scope`?  If so, the benign app_log is attempted through it, with the
// route's marker.  "ok": the call resolved; "no-native-effect": a raw postMessage was made (nothing comes back
// to tell); "failed": it threw or rejected or ran out of time; "unavailable": not there.
export async function probe(scope, marker, ms = 5000) {
  const out = {};
  const get = (f) => { try { return f(); } catch { return undefined; } };
  const call = async (thisArg, fn, args) => {
    let t;
    try {
      await Promise.race([fn.apply(thisArg, args), new Promise((_, no) => { t = setTimeout(() => no(new Error("timed out")), ms); })]);
      return "ok";
    } catch {
      return "failed";
    } finally {
      clearTimeout(t);
    }
  };
  const post = (thisArg, fn, msg) => { try { fn.call(thisArg, msg); return "no-native-effect"; } catch { return "failed"; } };
  const invokeArgs = (route) => ["app_log", { message: marker(route) }];
  const raw = (route) => JSON.stringify({ cmd: "app_log", payload: { message: marker(route) } });
  const internals = get(() => scope.__TAURI_INTERNALS__);
  const core = get(() => scope.__TAURI__?.core);
  const ipc = get(() => scope.ipc);
  const webkit = get(() => scope.webkit?.messageHandlers?.ipc);
  const webview = get(() => scope.chrome?.webview);
  out["tauri-internals-invoke"] = typeof internals?.invoke === "function" ? await call(internals, internals.invoke, invokeArgs("tauri-internals-invoke")) : "unavailable";
  out["tauri-core-invoke"] = typeof core?.invoke === "function" ? await call(core, core.invoke, invokeArgs("tauri-core-invoke")) : "unavailable";
  out["ipc-postmessage"] = typeof ipc?.postMessage === "function" ? post(ipc, ipc.postMessage, raw("ipc-postmessage")) : "unavailable";
  out["webkit-ipc-postmessage"] = typeof webkit?.postMessage === "function" ? post(webkit, webkit.postMessage, raw("webkit-ipc-postmessage")) : "unavailable";
  out["webview2-postmessage"] = typeof webview?.postMessage === "function" ? post(webview, webview.postMessage, raw("webview2-postmessage")) : "unavailable";
  return out;
}

