/** whether the item `id` holds or needs the item `other` (a mode's start may fetch only those: web/build.ts checks) */
export function itemCovers(id: string, other: string): boolean {

// The isolated output renderer's two forms (OUT-ISO plan r3, phase 1), built from one
// script (web/output-shell/shell.js):
// - hosted: dist/output-shell/index.html, served from its own cookie-free site with
//   outputShellPolicy() as its response header (web/csp.ts); its URL per environment
//   is pinned in web/output-shell/sites.mts, empty until that site exists;
// - packaged: the same page as a srcdoc (local server, desktop app, exported files),
//   the policy in a meta tag, the same script hash.  A srcdoc frame also inherits its
//   parent's policy; both apply.
// The script is inlined (no request, no file the frame could be pointed at instead) and
// the policy admits it by its sha-256 alone.
import { createHash } from "node:crypto";
import { outputShellPolicy } from "../csp-policy.mts";

const STYLE = `html,body{margin:0;padding:0;background:transparent;color:#111;font:14px/1.45 system-ui,sans-serif;overflow:hidden}
html[data-theme=dark]{color:#e8e8e8}html[data-theme=contrast]{color:#000;background:#fff}
#root{display:flow-root}section.out{overflow-x:auto}pre{margin:0;white-space:pre-wrap;font:13px/1.4 ui-monospace,monospace}
table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:2px 6px}img,svg{max-width:100%}`;

const hash = (s: string) => `'sha256-${createHash("sha256").update(s).digest("base64")}'`;

export async function buildOutputShell(build: (o: any) => Promise<any>, entry: string): Promise<{ hosted: string; srcdoc: string; scriptHash: string; styleHash: string }> {
  const r = await build({ entrypoints: [entry], target: "browser", format: "iife", minify: true, sourcemap: "none" });
  if (!r.success) throw new Error("the output shell didn't build:\n" + r.logs.join("\n"));
  const js = (await r.outputs[0].text()).replace(/<\/script/gi, "<\\/script");
  const scriptHash = hash(js), styleHash = hash(STYLE);
  const page = (meta: string) => `<!doctype html><html lang="en"><head><meta charset="utf-8">${meta}<title>output</title><style>${STYLE}</style></head><body><div id="root"></div><script>${js}</script></body></html>`;
  const policy = outputShellPolicy([scriptHash], [styleHash]);
  return {
    hosted: page(""),
    srcdoc: page(`<meta http-equiv="Content-Security-Policy" content="${policy.replace(/"/g, "&quot;")}">`),
    scriptHash,
    styleHash,
  };
}

/** The hosted shell's files for one environment's site: its page and the response headers the site serves it with. */
export function hostedShellFiles(built: { hosted: string; scriptHash: string; styleHash: string }, ancestors: string[]): Record<string, string> {
  const policy = outputShellPolicy([built.scriptHash], [built.styleHash], ancestors.length ? ancestors : ["'none'"]);
  return {
    "index.html": built.hosted,
    // (Cloudflare Pages-style headers: the shell page alone; the site serves nothing else, sets no cookie, never redirects)
    "_headers": [
      "/",
      `  Content-Security-Policy: ${policy}`,
      "  Cross-Origin-Embedder-Policy: require-corp",
      "  Cross-Origin-Resource-Policy: cross-origin",
      "  X-Content-Type-Options: nosniff",
      "  Referrer-Policy: no-referrer",
      "  Cache-Control: public, max-age=0, must-revalidate, no-transform",
      "/index.html",
      `  Content-Security-Policy: ${policy}`,
      "  Cross-Origin-Embedder-Policy: require-corp",
      "  Cross-Origin-Resource-Policy: cross-origin",
      "  X-Content-Type-Options: nosniff",
      "  Referrer-Policy: no-referrer",
      "  Cache-Control: public, max-age=0, must-revalidate, no-transform",
      "",
    ].join("\n"),
  };
}

// The isolated output renderer's channel (OUT-ISO plan r3, phase 1): one closed,
// versioned schema shared by the host (web/notebook/output-frames.js) and the
// renderer shell (web/output-shell/shell.js).  Every message is a JSON string on a
// MessagePort, and its length is checked BEFORE it is parsed (daybreak3's ruling:
// the message cap is on serialized size, before allocation or parse).  Unknown
// types and fields, wrong types, oversized values and non-finite numbers are
// refused: decode returns null, and the receiver ignores the message.
//
// host -> frame:  render {generation, area, outputs: [{id, kind, body}]}, theme {theme}, dispose {}
// frame -> host:  ready {}, committed {generation, area, ids, height}, height {generation, height}, error {generation, reason}
//
// The limits below (in the limits census, test/limit-sites.json) are phase-1
// measurement candidates, not approved defaults (astra, Nov 7): they are frozen,
// with their provenance, from the 50/200-area measurements before rich rendering
// is enabled.  messageChars: one message, serialized (its UTF-16 length, checked
// before JSON.parse); outputsPerRender: the outputs of one cell area; heightPx: a
// reported height (larger is refused).
export const VERSION = 1;
export const LIMITS = Object.freeze({ messageChars: 4 * 1024 * 1024, outputsPerRender: 64, idChars: 64, heightPx: 32768, reasonChars: 200 });
// (a render's output kinds: what the shell knows how to draw; phase 1 migrates no MIME)
export const KINDS = Object.freeze(["html", "svg", "text"]);
export const THEMES = Object.freeze(["light", "dark", "contrast"]);

const SHAPES = {
  "to-frame": {
    render: { generation: "gen", area: "id", outputs: "outputs" },
    theme: { theme: "theme" },
    dispose: {},
  },
  "to-host": {
    ready: {},
    committed: { generation: "gen", area: "id", ids: "ids", height: "height" },
    height: { generation: "gen", height: "height" },
    error: { generation: "gen", reason: "reason" },
  },
};

const isId = (v) => typeof v === "string" && v.length > 0 && v.length <= LIMITS.idChars && /^[A-Za-z0-9_.:-]+$/.test(v);
const CHECK = {
  gen: (v) => Number.isSafeInteger(v) && v >= 0,
  id: isId,
  ids: (v) => Array.isArray(v) && v.length <= LIMITS.outputsPerRender && v.every(isId) && new Set(v).size === v.length,
  height: (v) => typeof v === "number" && Number.isFinite(v) && v >= 0 && v <= LIMITS.heightPx,
  reason: (v) => typeof v === "string" && v.length <= LIMITS.reasonChars,
  theme: (v) => THEMES.includes(v),
  outputs: (v) => Array.isArray(v) && v.length <= LIMITS.outputsPerRender && new Set(v.map((o) => o?.id)).size === v.length &&
    v.every((o) => o && typeof o === "object" && !Array.isArray(o) && Object.keys(o).length === 3 && isId(o.id) && KINDS.includes(o.kind) && typeof o.body === "string"),
};

/** A message for `dir` ("to-frame" | "to-host"), as the string to post; throws if the schema doesn't allow it. */
export function encode(dir, type, fields = {}) {
  const m = { v: VERSION, type, ...fields };
  if (!valid(dir, m)) throw new Error(`not a valid ${dir} ${type} message`);
  const s = JSON.stringify(m);
