  includegraphics: [".pdf", ".png", ".jpg", ".jpeg", ".svg", ".eps"], includepdf: [".pdf"],
  lstinputlisting: [], verbatiminput: [], VerbatimInput: [], inputminted: [],
  bibliography: [".bib"], addbibresource: [], bibliographystyle: [".bst"],
