  const out: Published = { count: list.length, latestMs: 1000 * Math.max(...list.map((v) => v.created)), changed: null, latest: typeof vs.latest === "string" ? vs.latest : null };
  const f = c?.manifest?.files?.find((x: { path: string }) => x.path === nb.path);
