/** An absolute workspace path: PATH against the directory `cwd`, with . and .. resolved. */
export function absPath(cwd: string, p: string): string {
  const parts: string[] = [];
  for (const seg of ((p.startsWith("/") ? "" : cwd + "/") + p).split("/")) {
    if (seg === "" || seg === ".") continue;
    if (seg === "..") parts.pop();
    else parts.push(seg);
  }
  return "/" + parts.join("/");
}

