// Static assets are served before this runs.  The atlas's pages are
// rendered here from its static data (web/atlas), and kept in the edge
// cache for as long as their Cache-Control allows (KaTeX makes a large
// page cost tens of milliseconds to render), under a key with the build's
// id (web/build.ts writes it), so that a deploy is seen at once.  The share
// API (/auth/, /api/share/, /api/admin/) is web/share/server.ts, on where
// its bindings are (the dev site for now).  Anything else is a 404 page.
export default {
  async fetch(request, _env, ctx) {
    const url = new URL(request.url);
    const shared = await handleShare(request, env as ShareEnv, ctx);
    if (shared) return shared;
    // engines by their content, from R2 (web/engines.ts)
    const engine = await handleEngines(request, env as EnginesEnv, ctx);
    if (engine) return engine;
    // a library chunk of an earlier build, which a deploy took out of lib/,
    // from R2 (web/engines.ts)
    const chunk = await handleLibChunk(request, env as EnginesEnv, ctx);
    if (chunk) return chunk;
    // an optional package set's index or chunk, by its content, from R2 (web/engines.ts)
    const pkg = await handlePkg(request, env as EnginesEnv, ctx);
    if (pkg) return pkg;
    // a shared collection's page (web/share-client/view.html, at /s/), with its link preview (./preview.ts)
    const share = await handleSharePage(request, url, env as any);
    if (share) return share;
    // a notebook or folder of a public GitHub repository (/gh/<owner>/<repo>/...): the same page, which reads GitHub
    // from the reader's browser (web/gh/source.ts); this Worker never fetches GitHub
    const gh = handleGhPage(request, url, env as any);
    if (gh) return gh;
    if (url.pathname === "/atlas" || url.pathname.startsWith("/atlas/")) {
      const cache = caches.default;
      // JSON and HTML differ by Accept for the same URL
      const k = new URL(url);
      k.searchParams.set("__build", BUILD);
      if (/application\/json/.test(request.headers.get("accept") ?? "")) k.searchParams.set("__accept", "json");
      const key = new Request(k.toString(), { method: "GET" });
      if (request.method === "GET") {
        const hit = await cache.match(key);
        if (hit) return hit;
      }
      const r = await handleAtlas(request, (path) => env.ASSETS.fetch(new URL(path, url)));
      if (r) {
        if (request.method === "GET" && r.status === 200 && /public/.test(r.headers.get("cache-control") ?? "")) ctx.waitUntil(cache.put(key, r.clone()));
        return r;
      }
    }
    return env.ASSETS.fetch(request);
  },
  // The daily jobs, side by side: sharing's, and sync's inventory and receipt prune
  // (design/sync-server.md §9), each on its own, so one failing never stops the other.  Sync's returns at once where its
  // bindings aren't (the flag, §11), so this changes nothing until sync is bound.
  async scheduled() {

// A shared collection's page, /s/<id> and /s/<id>@<version>, with its link
// preview (share-ux-plan r2 §6.3): for a live share, the static page
// (web/share-client/view.html, whose fixed tags are the generic card) with
// the share's title set in its fixed <title> and og/twitter elements, and
// canonical URLs from the site's configured origin; for anything else, the
// generic card: the static page with, where the origin is configured, its
// image made absolute and its og:url (the page of no share) removed, the same
// bytes for every id that isn't live (#171's review, UI-D1: preview fetchers
// show no image for a relative one).  The title is set as text or as an
// attribute (both escaped by HTMLRewriter), never written into HTML.
//
// Visibility: every committed collection today is for anyone with the link,
// so a live share's title reveals nothing its link doesn't; an uncommitted
// draft has no latest version and gets the generic card.  A future private
// or signed-in-only share mode needs its own gate in sharePreview (#171's
// review, astra3).
import { ghPolicy } from "../../csp-policy.mts";
import { noindex, sharePreview } from "../../share/server.ts";

export const SHARE_PAGE = /^\/s\/([a-z2-7]{12})(?:@([0-9a-f]{8,64}))?\/?$/;

type Env = { ASSETS: { fetch(r: Request): Promise<Response> }; SITE_ORIGIN?: string };
type Preview = (env: any, id: string, at: string | null) => Promise<{ title: string; version: string } | null>;

/** The page for /gh/<owner>/<repo>/... (a public GitHub repository's notebook or folder): the /s/ page as the asset
 * serves it, which reads GitHub from the reader's browser, with its policy's fetches to GitHub's hosts only
 * (../../csp-policy.mts ghPolicy, as _headers gives /gh/*); or null if `url` isn't one. Never indexed: the content is
 * GitHub's. */
export function handleGhPage(request: Request, url: URL, env: Env): Promise<Response> | null {
  if (!url.pathname.startsWith("/gh/")) return null;
  return env.ASSETS.fetch(new Request(new URL("/s/", url), request)).then(noindex).then((r) => {
    const csp = r.headers.get("content-security-policy");
    if (csp) r.headers.set("content-security-policy", ghPolicy(csp));
    return r;
  });
}

/** The /s/ page for `request`, or null if `url` isn't one; every answer says noindex (../../share/server.ts NOINDEX). */
export async function handleSharePage(request: Request, url: URL, env: Env, preview: Preview = sharePreview): Promise<Response | null> {
  const r = await page(request, url, env, preview);
  return r && noindex(r);
}

async function page(request: Request, url: URL, env: Env, preview: Preview): Promise<Response | null> {
  const m = SHARE_PAGE.exec(url.pathname);
  if (!m) return null;
  const asset = new URL("/s/", url);
  const origin = env.SITE_ORIGIN?.replace(/\/+$/, "") || null;
  // (only GET and HEAD are rewritten; anything else is the static page as the asset serves it)
  if (request.method !== "GET" && request.method !== "HEAD") return env.ASSETS.fetch(new Request(asset, request));
  const p = await preview(env, m[1], m[2] ?? null).catch(() => null);
  // (without an origin, a share that isn't live is the static page as the asset serves it: the same
  // bytes and headers as an id that never existed)
  if (!p && !origin) return env.ASSETS.fetch(new Request(asset, request));
  // (without the request's conditional headers: a 304 for the static page must never stand in for a
  // rewritten one)
  const page = await env.ASSETS.fetch(new Request(asset, { method: "GET" }));
  if (page.status !== 200) return env.ASSETS.fetch(new Request(asset, request));
  return card(request.method, page, origin, p ? { title: p.title, url: `/s/${m[1]}${m[2] ? "@" + p.version : ""}` } : null);
}

