        return new Uint8Array(await r.arrayBuffer());
      } catch (e) {
        throw why(e);
      }
    }
    const reader = r.body.getReader();
    const parts = [];
    let n = 0;
    for (;;) {
      arm();
      let x;

// A notebook's folder as the page gives it: an absolute path of at most 1024 characters, its segments neither empty
// nor "." nor "..", none holding a control character (U+0000-U+001F or DEL U+007F, the workspace's own rule:
// web/workspace/paths.ts CONTROL), and not the runtime's own (/$pyjs): else null, and the session stays in "/". The
// files here are the workspace's (and the runtime's library under /$pyjs): no other place to reach.
export function startDirOf(v: unknown): string | null {
  if (typeof v !== "string" || v.length > 1024 || !v.startsWith("/")) return null;
  if (v === "/") return "/";
  const segs = v.slice(1).split("/");
  if (segs.some((s) => s === "" || s === "." || s === ".." || /[\u0000-\u001f\u007f]/.test(s))) return null;
  if (segs[0].startsWith("$")) return null;
  return v;
}

// The service worker's test-only hook (B8, the grader's ruling on cases v1): web/sw.js carries one block between
// `//  <offline-test>` and `// </offline-test>` lines.  The shipped dist/sw.js is the same file with that block cut out
// (and nothing else changed); a test build keeps it, outside any deployable directory, as web/dist-test/sw.test.js.
const BLOCK = /^\/\/ <offline-test>\n[\s\S]*?^\/\/ <\/offline-test>\n/m;
const MARKERS = ["<offline-test>", "</offline-test>", "offlineTest"];

/** the shipped text: `text` with its one hook block cut out; throws unless exactly one block and no marker left */
export function stripHook(text: string): string {
  const blocks = text.match(new RegExp(BLOCK.source, "gm")) ?? [];
  if (blocks.length !== 1) throw new Error(`web/sw.js: ${blocks.length} test hook blocks (exactly one expected)`);
  const at = text.indexOf(blocks[0]);
  // (byte for byte: the shipped file is the test file minus exactly the block's bytes)
  const shipped = text.slice(0, at) + text.slice(at + blocks[0].length);
  assertShipped(shipped);
  return shipped;
}

/** the shipped service worker carries no trace of the hook (the grader's (b) and v2 additions 1-2) */
export function assertShipped(shipped: string) {
  for (const m of MARKERS) if (shipped.includes(m)) throw new Error(`dist/sw.js: the shipped service worker contains the test hook's ${JSON.stringify(m)}`);
  // (1) the hook's seams are assigned once, at their declaration: only the test build's block changes them
  for (const [name, decl] of [["timeScale", "let timeScale = 1, estimateFn = "], ["estimateFn", "estimateFn = () => navigator.storage?.estimate?.();"]]) {
    const n = shipped.match(new RegExp(`\\b${name}\\s*=(?!=)`, "g"))?.length ?? 0;
    if (n !== 1 || !shipped.includes(decl)) throw new Error(`dist/sw.js: ${name} is assigned ${n} times (only its declaration may assign it)`);
  }
  // (2) the counters are only written in shipped code: each use is its declaration, an increment, or X = Math.max(X, ...)
  for (const name of ["budgetPeak", "inflightPeak", "keysLooked"]) {
    const uses = shipped.split("\n").filter((l) => new RegExp(`\\b${name}\\b`).test(l));
    const fine = (l: string) => new RegExp(`(^|[,(;{\\s])${name} = Math\\.max\\(${name}, `).test(l) || new RegExp(`\\b${name}\\+\\+`).test(l) || new RegExp(`^(let|const) .*\\b${name} = 0\\b`).test(l.trim());
    const bad = uses.filter((l) => !fine(l));
    if (bad.length) throw new Error(`dist/sw.js: the counter ${name} is read in shipped code: ${bad[0].trim().slice(0, 120)}`);
  }
  // (3) the hook's other seams (the stop point, the grant log, the forced probe) never in shipped code
  for (const [what, re] of [["a patched Cache API", /\bCache\.prototype\b|\bcaches\.open\s*=(?!=)/], ["reserve rebound", /^(?!\s*(?:const|let|var)\b).*(?:^|[^.\w])reserve\s*=(?!=)/m],
    ["the stop point", /\bstopAt\b|sb-offline-test/], ["the grant log", /\bgrants\b/], ["the probe forced", /\bprobed\s*=(?!=)/]] as const) {
    if (re.test(shipped)) throw new Error(`dist/sw.js: the shipped service worker contains the test hook's ${what}`);
  }
}

/** (3) no deployable directory carries the test build: no sw.test.js, no file with a hook marker */
export async function assertNoHookIn(dir: string) {
  const { readdirSync, readFileSync, statSync } = await import("node:fs");
  const { join } = await import("node:path");
  const walk = (d: string): string[] => readdirSync(d).flatMap((f) => (statSync(join(d, f)).isDirectory() ? walk(join(d, f)) : [join(d, f)]));
  for (const f of walk(dir)) {
    if (/sw\.test\.js$/.test(f)) throw new Error(`${f}: the test build's service worker is in a deployable directory`);
    if (/\.(js|mjs|html|json)$/.test(f) && readFileSync(f, "utf8").includes("//  <offline-test>")) throw new Error(`${f}: carries the service worker's test hook`);
  }
}

// The service worker of sagebrush.space: the notebook works offline, and
// installs as an app.  web/build.ts fills in VERSION, SHELL, LAZY and DIGESTS.
//
// The app's own files (SHELL, kept when this script installs; LAZY, kept the
// first time they are fetched online through it or by "download all": the
// engine, the documentation indexes and the Python library's chunks, which
// not every visit needs) are fetched network-first, so a deploy shows up at
// once, with the kept copy when offline; those whose URLs have a content hash
// (?h=, or a library chunk's name: lib/<group>.<kind>.<hash>.json) are
// cache-first.  Everything else (the Atlas, demos, data a notebook fetches) is
// not cached.
//
// The cache is the origin's storage, which any script of the origin can
// write.  So a kept copy is used only if it is under this build's exact
// request key, exactly the size and with the SHA-256 the build gave it
// (DIGESTS), and is then served as a response made here with the build's
// status and headers, never the kept one's; else it is dropped and fetched
// again, or, offline, not served (design/security.md, SEC-8D6-1, SEC-522-1;
// plan-b8-offline §14 S1).  Every body this script buffers is counted in one
// 64 MiB budget (§12 SIZE-8, §14 S3), and every body it puts into the build's
// cache is read with its own 1 MiB buffer and refused past its size (§13,
// §16).  This script itself cannot be changed that way: the browser fetches it.
const VERSION = "__VERSION__";
const SHELL = __SHELL__;
const LAZY = __LAZY__;
const DIGESTS = __DIGESTS__;
const CACHE = "sagebrush-" + VERSION;
// (web/stall-fetch.js's bound, given by the build: a client's chunk fetch is given up after this long without data)
const STALL_LIMIT_MS = __STALL_LIMIT_MS__;
// A kept copy's read is given up after half that without data, so the copy's request falls through to the network
// well before its client gives up: a cache-hit body that never settled held a Sage run for good (the grader's
// plain-worker investigation; VM1, Nov 3: the reservation taken, the read never answered, nobody waiting)
const READ_STALL_MS = STALL_LIMIT_MS / 2;

self.addEventListener("install", (ev) => {
  ev.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(SHELL);
    await self.skipWaiting();
  })());
});

const scope = new URL(self.registration.scope);
const shellPaths = new Set([...SHELL, ...LAZY].map((p) => new URL(p, scope).pathname));
const wanted = new Map(Object.entries(DIGESTS).map(([p, d]) => [new URL(p, scope).pathname, d]));
const MiB = 1 << 20;
// (timers are N * timeScale; the test build's hook alone may change it, or the estimate it reads)
let timeScale = 1, estimateFn = () => navigator.storage?.estimate?.();
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");

