  setup: Record<string, number>; dead: boolean; fail: (why: string) => void;
};
let pool: Pool | null = null;
// the job in flight: its settle functions (a pool failure rejects it)
let active: { resolve: (r: Result) => void; reject: (e: Error) => void } | null = null;

// (test hooks: helper 1 refuses, throws or exits ("refuse", "throw", "exit"); or, on the first startup only, the
// second worker's constructor ("spawn") or postMessage ("post") throws; window.__ndWorkers counts workers made
// and terminated)
const fault = new URLSearchParams(location.search).get("fault") ?? undefined;
const counts = { made: 0, terminated: 0, startups: 0 };
if (fault) (self as any).__ndWorkers = counts;
function makeWorker(url: URL): Worker {
  const first = counts.startups === 1;
  if (fault === "spawn" && first && counts.made === 1) throw new Error("injected Worker constructor failure");
  const w = new Worker(url, { type: "module" });
  counts.made++;
  if (fault) {
    const terminate = w.terminate.bind(w), post = w.postMessage.bind(w);
    w.terminate = () => { counts.terminated++; terminate(); };
    if (fault === "post" && first && counts.made === 2) w.postMessage = () => { throw new DOMException("injected postMessage failure", "DataCloneError"); };
    else w.postMessage = post;
  }
  return w;
}

function threadCounts(max: number): number[] {

// The threads demo's worker (numerics-core r4.2, M0): one script, two roles, on one shared memory.
// - "helper" (threads 1..T-1): waits on the control word, runs its share of the job, counts in.
// - "conductor" (thread 0): fills the inputs, checks correctness, then times the job at each thread count. It is
//   a worker because a page's main thread may not block (Atomics.wait), and the job's thread 0 must wait for the others.
// Every job returns before anyone reads C (r4.2 §6). Failures never hang (E3): a helper that throws or traps
// records it and still counts in; a helper that dies outright is caught by the conductor's bounded wait (no
// helper finishing for STALL_MS fails the job); the page tears the pool down on any failure (page.ts).

type Exports = {
  __stack_pointer: WebAssembly.Global;
  nd_gemm_part(desc: number, id: number): number;
  nd_pool_init(ctl: number, stacks: number, slot: number, participants: number): number;
  nd_info(what: number): number; // 0 scratch length, 1 floor, 2 and 3 the microkernel name's address and length
};

// control words (Int32): [0] job generation (−1 = stop), [1] helpers done, [2] helper failures
const GEN = 0, DONE = 1, FAIL = 2;
// (no helper finishing for this long fails the job: far above any helper's share of the largest job here)
const STALL_MS = 15000;

function instantiate(module: WebAssembly.Module, memory: WebAssembly.Memory, stackTop: number): Exports {
  const ex = new WebAssembly.Instance(module, { env: { memory } }).exports as unknown as Exports;
  ex.__stack_pointer.value = stackTop;
  return ex;
}

self.onmessage = (ev: MessageEvent) => {
  const m = ev.data;
  if (m.role === "helper") helper(m);
  else if (m.role === "conductor") conductor(m);
};

// (fault: a test hook from the page's ?fault= (helper 1 only): "refuse", "throw", or "exit" after its first job)
function helper(m: { module: WebAssembly.Module; memory: WebAssembly.Memory; id: number; stackTop: number; ctl: number; desc: number; fault?: string }) {
  const ex = instantiate(m.module, m.memory, m.stackTop);
  const c = new Int32Array(m.memory.buffer, m.ctl, 4);
  let seen = Atomics.load(c, GEN);
  postMessage({ ready: m.id });
  const fault = m.id === 1 ? m.fault : undefined;
  for (let jobs = 0; ; jobs++) {
    Atomics.wait(c, GEN, seen);
    seen = Atomics.load(c, GEN);
    if (seen < 0) return;
    if (fault === "exit" && jobs > 0) {
      self.close(); // (a dead worker: it never counts in)
      return;
    }
    try {
      if (fault === "throw") throw new Error("injected failure");
      if (fault === "refuse" || !ex.nd_gemm_part(m.desc, m.id)) Atomics.add(c, FAIL, 1);
    } catch (e) {
      Atomics.add(c, FAIL, 1);
      postMessage({ helperError: `helper ${m.id}: ${String((e as Error)?.message ?? e)}` });
    } finally {
      Atomics.add(c, DONE, 1);
      Atomics.notify(c, DONE);
    }
  }
}

// The pinned zone data for the browser (tzdata/, scripts/tzdata-import.mjs),
// as engine files: each zone file by its content's SHA-256
// (lib/tzdata/<sha256>.tzif: zones whose files are the same share one), and an
// index, zone name -> that SHA-256 (lib/tzdata/index-<sha256>.json; under lib/, a
// published engine's are kept, as the library's chunks are: web/engines.ts). The worker's
// library manifest carries only the index's reference (web/lib-chunks.mts's
// LibManifest.tzdata); the browser's time module (lib/_pytime.py) fetches the
// index and its own zone's file the first time it is imported, each checked
// against its SHA-256 (web/lib-lazy.ts, as the library's chunks are).
import { createHash } from "node:crypto";
import { readFileSync, readdirSync, lstatSync } from "node:fs";
import { join, relative, sep } from "node:path";
import type { ChunkRef } from "./lib-chunks.mts";

const sha256 = (b: Uint8Array | string) => createHash("sha256").update(b).digest("hex");

function walk(dir: string, base = dir, out: string[] = []): string[] {
  for (const f of readdirSync(dir).sort()) {
    const p = join(dir, f), st = lstatSync(p);
    if (st.isSymbolicLink()) throw new Error(`${p}: a symbolic link`);
    if (st.isDirectory()) walk(p, base, out);
    else if (st.isFile()) out.push(relative(base, p).split(sep).join("/"));
  }
  return out;
}

/** The engine files (name -> bytes) and the index's reference, for the
 * repository at root. */
export function tzdataChunks(root: string): { ref: ChunkRef & { version: string }; files: Map<string, Uint8Array> } {
  const source = JSON.parse(readFileSync(join(root, "tzdata", "source.json"), "utf8"));
  const zoneDir = join(root, "tzdata", "zoneinfo");
  const files = new Map<string, Uint8Array>();
  const zones: Record<string, string> = {};
  for (const name of walk(zoneDir)) {
    const bytes = readFileSync(join(zoneDir, name));
    const h = sha256(bytes);
    zones[name] = h;
    files.set(`lib/tzdata/${h}.tzif`, bytes);
  }
  if (Object.keys(zones).length !== source.zones) throw new Error(`tzdata/: ${Object.keys(zones).length} zone files, not the ${source.zones} of tzdata ${source.version} (node scripts/tzdata-import.mjs --check)`);
  const index = new TextEncoder().encode(JSON.stringify({ format: "sagebrush-tzdata", version: source.version, zones }));
  const ih = sha256(index);
  const file = `lib/tzdata/index-${ih}.json`;
  files.set(file, index);
  return { ref: { file, sha256: ih, size: index.length, version: source.version }, files };
}

