const enc = (s) => new TextEncoder().encode(s);
const dec = (b) => new TextDecoder().decode(b);

// A folder grant, as ShellHost's principals make one: admitted if the entry, or a folder above it, is one of the
// granted folders, by fid (design/capabilities.md §6).  `seen` records every check.  The refusal is an object of
// its own, so a test can tell it is what the verb rejected with.
// (an OutOfScope: the one refusal list() leaves an entry out for; anything else is list's error)
class Refused extends W.OutOfScope {}
function grant(...fids) {
  const g = new Set(fids), seen = [];
  const admit = (c) => {
    seen.push({ op: c.op, role: c.role, path: c.path, entry: c.entry?.path ?? null, chain: c.chain.map((e) => e.path) });
    const ok = c.chain.some((e) => g.has(e.fid)) || (c.entry?.kind === "folder" && g.has(c.entry.fid));
    if (!ok) throw new Refused(`EACCES ${c.path}`);
  };
  return { admit, seen, g };
}

export async function run() {
  const out = [];
  const check = (ok, what) => out.push([!!ok, what]);
  // (a case that throws is a failed check, said, not a lost run)
  try {
    await cases(check);
  } catch (e) {
    check(false, `the cases threw: ${e?.constructor?.name}: ${e?.message}`);
  }
  return out;
}

async function cases(check) {
  localStorage.clear();
  const w = await W.Workspace.open({ name: "admit-cases", mainName: "admit-cases-main" });
  const A = await w.mkdir("/A"), B = await w.mkdir("/B");
  await w.create("/A/f.txt", { content: enc("a") });
  await w.create("/B/g.txt", { content: enc("b") });
  const nOps = async () => (await w.ops()).length;
  // (a refusal: rejects with admit's own object, and the workspace's op log is unchanged)
  async function refused(what, f) {
    const before = await nOps();
    let err = null;
    try { await f(); } catch (e) { err = e; }
    const after = await nOps();
    check(err instanceof Refused && after === before, `${what}: refused with admit's error, nothing logged (${err?.constructor?.name}: ${err?.message}; ops ${before} -> ${after})`);
    return err;
  }

  // ---- stat: present and absent, refused alike (an absent path in B isn't told apart from a present one)
  {
    const a = grant(A.fid);
    check((await w.stat("/A/f.txt", { admit: a.admit }))?.path === "/A/f.txt", "stat in the granted folder answers");
    await refused("stat of a file outside the grant", () => w.stat("/B/g.txt", { admit: a.admit }));
    await refused("stat of an absent path outside the grant", () => w.stat("/B/none.txt", { admit: a.admit }));
    const s = a.seen.find((x) => x.path === "/B/none.txt");

// The agent's bar never covers what the person types in or reads (decided Nov 19 2026): an expression for a page test's
// evaluate, true when the bar is in the page's own row for it ([data-sbag-slot]) and its box overlaps no input, button,
// editor or plot of the page; else what it overlaps, as a string. (The test pages: the notebook, code and LaTeX pages,
// the board and the Agents page. The board's canvas is under its whole top bar by design, so it isn't counted; the
// pictures on it are.)
export const BAR_CLEAR = `(() => {
  const b = document.querySelector(".sbag-bar");
  if (!b) return "no bar";
  if (!b.classList.contains("docked") || !b.parentElement?.matches("[data-sbag-slot]")) return "not docked: " + (b.parentElement?.tagName ?? "nowhere");
  const r = b.getBoundingClientRect();
  const sel = "input, textarea, select, button, [contenteditable], .ed, .cell, svg[aria-label^=Plot], img, #editor, .composer, .code-body, .tex-main, [data-sbb=canvas]";
  // (an element's box as it is seen: cut to every scrolling or clipping ancestor's, as a list scrolled under a row)
  const seen = (e) => {
    const q = e.getBoundingClientRect();
    let x0 = q.left, y0 = q.top, x1 = q.right, y1 = q.bottom;
    for (let a = e.parentElement; a; a = a.parentElement) {
      if (getComputedStyle(a).overflow === "visible") continue;
      const c = a.getBoundingClientRect();
      x0 = Math.max(x0, c.left); y0 = Math.max(y0, c.top); x1 = Math.min(x1, c.right); y1 = Math.min(y1, c.bottom);
    }
    return { left: x0, top: y0, right: x1, bottom: y1, width: x1 - x0, height: y1 - y0 };
  };
  // (and only where the person would see it without the bar: the topmost thing at the overlap's middle, so a page under
  //  another (the notebook page under the code page) isn't counted)
  const under = (e, q) => {
    const x = (Math.max(r.left, q.left) + Math.min(r.right, q.right)) / 2, y = (Math.max(r.top, q.top) + Math.min(r.bottom, q.bottom)) / 2;
    b.style.visibility = "hidden";
    const top = document.elementFromPoint(x, y);
    b.style.visibility = "";
    return !!top && (e === top || e.contains(top));
  };
  const hit = [...document.querySelectorAll(sel)].filter((e) => !b.contains(e) && !e.contains(b) && e.offsetParent !== null).find((e) => {
    const q = seen(e);
    return q.width > 0 && q.height > 0 && r.left < q.right && q.left < r.right && r.top < q.bottom && q.top < r.bottom && under(e, q);
  });
  if (!hit) return true;
  const q = seen(hit), box = (x) => [x.left, x.top, x.width, x.height].map(Math.round).join(",");
  return "over " + (hit.id ? "#" + hit.id : hit.tagName.toLowerCase() + (hit.className && typeof hit.className === "string" ? "." + hit.className.split(" ")[0] : "")) + " (" + (hit.textContent ?? "").trim().slice(0, 30) + ") at " + box(q) + "; the bar at " + box(r);
})()`;

// The permission digest's canonical JSON, the page's side: a copy of sagebrush-agent's lib/canon.mjs (canon and
// permissionDigest), so the page and the agent turn the same action into the same bytes. Both are checked against the
// agent's canon fixtures (test-agent-canon.mjs). An Allow counts only with the digest of the very action the person
// was shown: the agent computes it from the action it asked about, the page from the card it shows, and the agent
// compares the two. Over `sagebrush remote` (the agent's --stdio) every Allow carries it.
//
// Accepted values: null, true, false, strings, integers with |n| <= 2^53 - 1 (not -0), arrays, and plain objects
// (prototype Object.prototype or null) whose own properties are all plain data (no getters, no symbols). Anything
// else is refused. Object keys are sorted by UTF-16 code units (JavaScript's default sort) and arrays keep their
// order; there is no whitespace. Strings are written as ES2019 JSON.stringify writes them: \" \\ \b \f \n \r \t,
// other control characters as lower-case \u00xx, lone surrogates as lower-case \udxxx, nothing else escaped. Bounded
// as it goes, as the agent's is: the same budget, checked at the same points.

export const CANON_MAX = 16 * 1024; // the most of a tool's arguments a person reviews, as canonical text
export const CANON_DEPTH = 32;
export const DIGEST_DOMAIN = "sb-agent-permission/1\n";

class Refused extends Error {}

const hex4 = (n: number) => n.toString(16).padStart(4, "0");

/** The UTF-8 length and JSON form of one string, or a refusal once it would pass `room` bytes. */
function encodeString(s: string, room: number): { text: string; bytes: number } {
  if (s.length + 2 > room) throw new Refused("too large");
  let bytes = 2;
  const parts = ['"'];
  let run = 0; // (start of the current run of characters written as they are)
  const flush = (i: number) => { if (i > run) parts.push(s.slice(run, i)); };
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    let esc: string | null = null, n = 0;
    if (c === 0x22) esc = '\\"';
    else if (c === 0x5c) esc = "\\\\";
    else if (c < 0x20) esc = c === 8 ? "\\b" : c === 9 ? "\\t" : c === 10 ? "\\n" : c === 12 ? "\\f" : c === 13 ? "\\r" : "\\u" + hex4(c);
    else if (c >= 0xd800 && c <= 0xdbff) {
      const d = i + 1 < s.length ? s.charCodeAt(i + 1) : 0;
      if (d >= 0xdc00 && d <= 0xdfff) { n = 4; i++; } // (a pair: one 4-byte character)
      else esc = "\\u" + hex4(c);
    } else if (c >= 0xdc00 && c <= 0xdfff) esc = "\\u" + hex4(c);
    else n = c < 0x80 ? 1 : c < 0x800 ? 2 : 3;
    if (esc !== null) {
      flush(i);
      parts.push(esc);
      run = i + 1;
      n = esc.length;
    }
    bytes += n;
    if (bytes > room) throw new Refused("too large");
  }
  flush(s.length);
  parts.push('"');
  return { text: parts.join(""), bytes };
}

const plainProto = (v: object) => { const p = Object.getPrototypeOf(v); return p === Object.prototype || p === null; };

export type Canon = { ok: true; text: string; value: unknown; bytes: number } | { ok: false; reason: string };

/** The canonical text of `value` and an inert copy of it, or why it is refused. */
export function canon(value: unknown, max = CANON_MAX): Canon {

// The paired agent's permission cards, the page's side: each card kept with the fields its digest
// binds (child, conversation, request_id, action) as admitted, never rebuilt from what is shown; answered once, the
// first click claiming it before anything is awaited; an Allow carrying the digest of that very card (agent-canon.ts),
// computed within the page-wide digest bound and sent only if the same pairing and the same agent child are still
// current. A card the page's canon refuses is answered Deny (the agent accepted the same input when it asked, so that
// is the page's fault, and it fails closed).

import { canon, permissionDigest } from "./agent-canon";

type Gate = { acquire(bytes: number, live: () => boolean): Promise<(() => void) | null>; sweep(): void };
/** What the cards need of the pairing: its child, whether it's over a runner, and its notify. */
export type CardPairing = { readonly state: string; readonly link: unknown; readonly hello: { child?: string } | null; notify(method: string, params: unknown): boolean };
type Card = { pairing: CardPairing; turn: string; instance: string; child?: string; conversation: string; request_id: string; tool?: string; input?: unknown; claimed: boolean };

/** A card's identities and tool, each at most this many bytes as canonical text (permissionText's bound). A kept card
 * is then at most 16 KiB of input and 4 KiB of identities as UTF-8, so the cards kept hold at most CARDS_MAX times
 * that, twice over as JS strings, plus each card's 32-character page token (64 bytes as a JS string, 1 KiB for
 * CARDS_MAX cards): an accounted figure, not a browser ceiling. */
export const ID_MAX = 1024;
export const CARDS_MAX = 16; // (the agent asks at most 4 at once; older unanswered ones past this are forgotten)
export const SPENT_MAX = 256; // (ids remembered as asked, per pairing, each a 16-character hash: 32 bytes as a JS string, 8 KiB of payload in all; object and GC overhead not counted)

/** A card's own token, made by the page: 16 random bytes. */
const token = () => { let s = ""; for (const b of globalThis.crypto.getRandomValues(new Uint8Array(16))) s += b.toString(16).padStart(2, "0"); return s; };
/** An id as a fixed-size hash (two 32-bit FNV-1a passes): a collision only refuses a new card, failing closed. */
function idHash(id: string): string {
  let a = 0x811c9dc5, b = 0x01000193 ^ id.length;
  for (let i = 0; i < id.length; i++) { const c = id.charCodeAt(i); a = Math.imul(a ^ c, 0x01000193); b = Math.imul(b ^ c, 0x0100019d); }
  return (a >>> 0).toString(16).padStart(8, "0") + (b >>> 0).toString(16).padStart(8, "0");
}

/** What Codex asks before it acts (sagebrush-agent's codex.* cards), titled as the agent titles them. */
const CODEX_TITLES: Record<string, string> = {
  "codex.command": "Run this command?",
  "codex.stdin": "Send input to a running command?",
  "codex.fileChange": "Make these file changes?",
  "codex.permissions": "Give Codex more access?",
};
// (what a Codex card is about, in full: the command and the folder it runs in; the files changed; why more access)
function codexSummary(tool: string, i: Record<string, unknown>): string {
  const str = (v: unknown) => (typeof v === "string" ? v : "");
  if (tool === "codex.fileChange") return (Array.isArray(i.changes) ? i.changes.map((c) => str((c as { path?: unknown })?.path)).filter(Boolean).join(", ") : "") || "(no file named)";
  if (tool === "codex.permissions") return str(i.reason) || "(no reason given)";
  // (Codex's command may be missing or null: said so, never an empty line under "Run this command?")
  const command = str(i.command), cwd = str(i.cwd);
  if (!command) return "(no command given)";
  return cwd ? `${command} (in ${cwd})` : command;
}

/** A card's words from its action, exactly as the agent words them (sagebrush-agent's askPerson): the tool's name,
 * what the call is for (its address, query or path), and all of its arguments. */
export function cardText(tool: string, input: unknown): { title: string; summary: string; detail: string } {
  const name = tool.startsWith("mcp__sagebrush__") ? tool.slice("mcp__sagebrush__".length) : tool;
  const i = (input && typeof input === "object" ? input : {}) as Record<string, unknown>;
  const codex = CODEX_TITLES[tool];
  if (codex) return { title: codex, summary: codexSummary(tool, i), detail: JSON.stringify(input, null, 2) };
  const target = [i.url, i.query, i.path, i.from && i.to ? `${i.from} → ${i.to}` : undefined].find((v) => typeof v === "string") as string | undefined;
  return { title: `Allow ${name}?`, summary: target ?? "(no address or query given)", detail: JSON.stringify(input, null, 2) };
}
