      ...(o.chunks.latex ? { latex: { load: () => (latexMods ??= Promise.all(o.chunks.latex!.map((f) => import(/* @vite-ignore */ at(f) + (latexTries ? `?try=${latexTries}` : ""))))
        .then(([page, tools, run]) => ({ page, tools, run })).catch((e) => { latexMods = null; latexTries++; throw e; })) } } : {}),
      ...o.more?.(),
