// An agent's branch (chat plan PR 3, packet r4e): git_branch copies main into /Branches/<name>/, a folder of the
// person's workspace that the agent which made it (its grant's id) may change, and no other agent.  What the host
// keeps of it is a record in the workspace's meta store, keyed by its root folder's fid, never by its name:
//
//   agent-branch:<fid>          {name, owner, status, entries, bytes, made, reason?}
//   agent-branch-h:<fid>:<k>    the base hashes, [relPath, sha256][], whole entries, each page at most PAGE_BYTES
//
// The records are the host's alone: never in an agent's entry data, never offered by forAgent.  This module holds
// what the workspace (api.ts, in every page) needs: the limits, the ownership rule an agent's change passes
// (branchRefusal, asked by the workspace holding its lock) and its texts, and the form of what is copied and hashed.
// git_branch's own flow and the rest of its texts are git-branch.ts's, only in the pages that offer it.

import { BRANCHES, nameOf, within, type Kind } from "./paths";
import { docCanonBytes } from "./canon-doc";
export { BRANCHES };
/** A branch's name: the agent's choice, for what the work is about. */
export const BRANCH_NAME = /^[a-z0-9][a-z0-9-]{0,39}$/;
/** git_branch's creation-copy limits (not lifetime quotas: later edits in a branch follow the workspace's own).
 * `branches` counts every record, making, ready and failed; `hashBytes` bounds the base hashes' pages as stored
 * (their JSON in UTF-8, every page: under it), `pageBytes` each page (at most), and `pathBytes` the copied entries'
 * relative paths, each as JSON in UTF-8 (escapes counted), together (at most): daybreak2's ruling on Option A. */
export const BRANCH_LIMITS = { branches: 16, entries: 2000, bytes: 256 * 2 ** 20, pathBytes: 512 * 2 ** 10, hashBytes: 2 ** 20, pageBytes: 32 * 2 ** 10 };
export const BRANCH_KEY = "agent-branch:";
export const BRANCH_HASH_KEY = "agent-branch-h:";
/** A branch's review state (branch-store.ts's history beside it), keyed by the root folder's fid like its record. */
export const BRANCH_REVIEW_KEY = "agent-branch-r:";

/** A branch's runs (run-verbs.ts notes them, the review page reads them), keyed by the root folder's fid like its record:
 * apart from the review state, so a note never touches a commit's or an accept's seq. */
export const BRANCH_RUNS_KEY = "agent-branch-runs:";
/** One file's latest run in a branch: when the run's snapshot was read (`at`, ms), and the git blob id of the file's
 * canonical bytes as that snapshot had them, under the branch's canon. */
export type BranchRun = { at: number; oid: string };
/** By path within the branch ("/a.ipynb"), as pairs (never an object keyed by path: a file named __proto__ is a name
 * like any other); `seq` goes up by one at every write (the wake's). */
export type BranchRuns = { seq: number; runs: [string, BranchRun][] };
/** A branch's runs, at most: entries, and their JSON's UTF-8 bytes. */
export const RUNS_LIMITS = { count: 2000, bytes: 64 * 2 ** 10 };

/** Whether the run `a` is newer than `b`: later `at`, then the larger oid (so two notes of one time agree whichever
 * lands first). */
const newerRun = (a: BranchRun, b: BranchRun) => a.at > b.at || (a.at === b.at && a.oid > b.oid);

/** `cur` with `path`'s run noted as `run`, unless the one kept is as new or newer (null: nothing to write).  Paths
 * `alive` says are gone are dropped; past RUNS_LIMITS the oldest go first (by `at`, then path); a note too large to
 * be kept alone is not written. */
export function mergeRun(cur: BranchRuns | null, path: string, run: BranchRun, alive: (p: string) => boolean, limits = RUNS_LIMITS): BranchRuns | null {
  const one = (e: [string, BranchRun]) => jsonBytes(e);
  if (2 + one([path, run]) > limits.bytes) return null;
  const was = cur?.runs.find(([p]) => p === path)?.[1];
  if (was && !newerRun(run, was)) return null;
  const kept: [string, BranchRun][] = (cur?.runs ?? []).filter(([p]) => p !== path && alive(p));
  kept.push([path, run]);
  // (newest first; the oldest dropped until both bounds hold: a JSON array's bytes are its entries', the commas between,
  //  and its brackets)
  kept.sort((x, y) => (x[1].at !== y[1].at ? y[1].at - x[1].at : x[0] < y[0] ? 1 : x[0] > y[0] ? -1 : 0));
  let bytes = 2 + kept.reduce((n, e) => n + one(e), 0) + kept.length - 1;
  while (kept.length > limits.count || bytes > limits.bytes) { bytes -= one(kept.pop()!) + 1; }
  return { seq: (cur?.seq ?? 0) + 1, runs: kept };
}

// An agent's branch's history: a small git object store of its own, one per workspace, in this browser's
// IndexedDB, only in the pages that offer branches.  No .git folder anywhere in the workspace, no git library, and
// nothing here is ever pushed: it is the record of what an agent submitted, and of what the person accepted.
//
//   - Objects are git's own (blob, tree, commit, with their SHA-1 ids, as `git hash-object` gives them), so a later
//     push to GitHub (design/git-projects.md) maps them as they are.
//   - Its database is "sagebrush-branches:" + the SHA-256 of the workspace's actual database name (named and test
//     databases included), so two workspaces never share a store, and no two names can collide by sanitizing.
//   - A branch's ref is "agent/" + the first 40 hex of the SHA-256 of its root folder's fid: keyed by the fid, never
//     by the branch's name (a name is a display label, and a renamed root is no longer a branch, as git_branch has it).
//   - Objects are written first; a ref moves only by compare-and-swap, in one transaction (setRef's `expect`), so two
//     writers can't both advance one ref, and a half-made commit is unreferenced, never visible.
//   - What is committed is each document's canonical bytes (branch-canon.ts): the same bytes the base hashes are of.
//   - Lifetime bounds (not git_branch's creation-only ones): STORE_LIMITS.

import { sha256Hex as bytesHash } from "./sha256-hex";
import type { Canon } from "./branch-canon";

const MiB = 1024 * 1024;
/** Lifetime bounds of a workspace's branch history, and of what a review carries (astra's point 6). */
export const STORE_LIMITS = Object.freeze({
  /** commits on one branch, the first (its base) included */
  commits: 200,
  /** new blob bytes the store has taken, all branches, all time */
  historyBytes: 64 * MiB,
  /** characters */
  message: 10_000,
  note: 2_000,
  title: 200,
  reason: 2_000,
  /** git_wait calls waiting at once, per grant */
  waitsPerGrant: 4,
  /** git_wait's longest wait in one call, seconds */
  waitSeconds: 50,
});

/** The history bound in force: STORE_LIMITS.historyBytes, but for tests (a near-cap race needs a small one). */
export const HISTORY_CAP = { bytes: STORE_LIMITS.historyBytes };
/** A commit refused because the workspace's history would pass HISTORY_CAP (nothing of it was written). */
export class HistoryFull extends Error {}

/** Relative path (within the branch) -> canonical bytes. */
export type Files = Map<string, Uint8Array>;
/** A file's whole document as submitted (a notebook's or board's JSON, outputs included; a data file's bytes), with
 * its kind and mode: what accepting it writes, so nothing changed after the review is applied. */
export type Full = { bytes: Uint8Array; kind: string; mode?: string };
export type Who = { name: string; email?: string };
/** A commit as log() gives it (the shape isomorphic-git's log has). */
export type LogEntry = { oid: string; commit: { message: string; tree: string; parent: string[]; author: { name: string; email: string; timestamp: number; timezoneOffset: number } } };

const enc = new TextEncoder(), dec = new TextDecoder();
const hexOf = (s: string): Promise<string> => bytesHash(enc.encode(s));
const hex = (b: Uint8Array) => [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
const unhex = (s: string) => Uint8Array.from(s.match(/../g)!.map((x) => parseInt(x, 16)));
const concat = (...xs: Uint8Array[]) => { const out = new Uint8Array(xs.reduce((n, x) => n + x.length, 0)); let i = 0; for (const x of xs) { out.set(x, i); i += x.length; } return out; };

type ObjType = "blob" | "tree" | "commit";
/** A git object's id and its stored form: SHA-1 of "<type> <length>\0" + body. */
export async function objectId(type: ObjType, body: Uint8Array): Promise<string> {
  return hex(new Uint8Array(await crypto.subtle.digest("SHA-1", concat(enc.encode(`${type} ${body.length}\0`), body))));

// A branch's change events (onBranch): this bundle's subscribers directly, every other one (another tab, or another
// chunk of this page with its own copy of this module: the runs' chunk, the review page's) through a BroadcastChannel
// named for the branch store, "sagebrush-branches:" + its name, which every other channel of that name receives.  A
// wake-up only, never the state: the receiver reads it.  One channel per store, kept (a page has one workspace or few).

import { sha256Hex } from "./sha256-hex";

type Wake = { ns: string; fid: string; seq: number };
const local = new Set<(w: Wake) => void>();
const channels = new Map<string, BroadcastChannel>();
function channelFor(ns: string): BroadcastChannel | undefined {
  if (typeof BroadcastChannel === "undefined") return undefined;
  let c = channels.get(ns);
  if (!c) {
    c = new BroadcastChannel("sagebrush-branches:" + ns);
    // (another copy's wake-up: only its keys are read, and only as a wake-up; the receiver reads the state itself)
    c.onmessage = (e: MessageEvent) => {
      const d = e.data;
      if (d && typeof d === "object" && typeof d.fid === "string" && Number.isSafeInteger(d.seq)) for (const f of [...local]) f({ ns, fid: d.fid, seq: d.seq });
    };
    channels.set(ns, c);
  }
  return c;
}

/** Tells this bundle's subscribers and every other copy's that the branch `w.fid` of the store `w.ns` changed. */
export function tellBranch(w: Wake) {
  for (const f of [...local]) f(w);
  channelFor(w.ns)?.postMessage({ fid: w.fid, seq: w.seq });
}

/** `cb` called (with no state: read it) whenever the branch `fid` of the store `ns` may have changed, in this tab or
 * another; returns the unsubscribe. */
export function onBranch(ns: string, fid: string, cb: () => void): () => void {
  channelFor(ns);
  const f = (w: Wake) => { if (w.ns === ns && w.fid === fid) cb(); };
  local.add(f);
  return () => { local.delete(f); };
}

/** The branch store's name for the workspace whose database is `dbName` (branch-store.ts's openBranchStore). */
export async function branchStoreName(dbName: string): Promise<string> {
  return "sagebrush-branches:" + (await sha256Hex(new TextEncoder().encode(dbName)));
}

/** tellBranch, for a page that knows its workspace's database name, not its branch store's (run-verbs.ts). */
export async function wakeBranch(dbName: string, fid: string, seq: number): Promise<void> {
  tellBranch({ ns: await branchStoreName(dbName), fid, seq });
}

