// The canonical bytes of a notebook or a data file, for an agent's branch (branch-canon.ts's versions; see there):
// apart from branch-canon.ts so a page without boards (the notebook page, where runs are) has them without the board's
// canonical text, and without branch-rules.ts (whose branchCopy calls this for its canon-1 bytes).  branch-canon.ts calls
// these too, so every caller has one function.

export type Canon = 1 | 2;

const enc = new TextEncoder();

/** `v` with every object's keys in sorted order (arrays kept in order), for JSON.stringify. */
export function sortKeys(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(sortKeys);
  if (v && typeof v === "object" && !(v instanceof Uint8Array)) {
    const out: Record<string, unknown> = {};
    for (const k of Object.keys(v as object).sort()) out[k] = sortKeys((v as Record<string, unknown>)[k]);
    return out;
  }
  return v;
}

/** The canonical bytes of a notebook or a data file whose content is `content`, under `version`. */
export function docCanonBytes(kind: "notebook" | "file", content: any, version: Canon): Uint8Array {
  if (kind === "file") return content instanceof Uint8Array ? content : enc.encode(String(content ?? ""));
  const d = content ?? {};
  const cells = Array.isArray(d.cells) ? d.cells : [];
  // (canon 1: git_branch's first form, the cells' type and code in that order, no mode)
  if (version === 1) return enc.encode(JSON.stringify({ cells: cells.map((c: any) => ({ type: c?.type ?? "code", code: String(c?.code ?? "") })) }));
  return enc.encode(JSON.stringify(sortKeys({ mode: d.mode ?? null, cells: cells.map((c: any) => ({ type: c?.type ?? "code", code: String(c?.code ?? "") })) })));
}

/** The git blob id of `bytes` (branch-store.ts's objectId("blob", bytes)): SHA-1 of "blob <length>\0" + bytes. */
export async function blobOid(bytes: Uint8Array): Promise<string> {
  const head = enc.encode(`blob ${bytes.length}\0`), all = new Uint8Array(head.length + bytes.length);
  all.set(head); all.set(bytes, head.length);
  return [...new Uint8Array(await crypto.subtle.digest("SHA-1", all))].map((x) => x.toString(16).padStart(2, "0")).join("");
}

// Type-level pins of web/workspace/checkpoint.ts (tsconfig.web.json checks this file; nothing imports it): an accepted
// batch is made only by acceptedBatch, so a local or unsent row, or a plain object shaped like a batch, can't be passed
// where the exact cut, an install or the coverage rule want accepted history (BH-0b-2 map r2, the grader's pin).
import type { Patch } from "patchflow";
import { acceptedBatch, exactCut, checkCheckpoint, type AcceptedBatch, type Descriptor } from "./checkpoint.ts";
import type { DocCodec } from "patchflow";

declare const codec: DocCodec;
declare const local: Patch;
declare const d: Descriptor;
const ok: AcceptedBatch = acceptedBatch(1, [local], 0);
exactCut(codec, [ok], 1, local.time);
// @ts-expect-error a local row is not an accepted batch
exactCut(codec, [local], 1, local.time);
// @ts-expect-error nor is an object shaped like one: only acceptedBatch makes one
exactCut(codec, [{ seq: 1, patches: [local], charge: 0 }], 1, local.time);
// @ts-expect-error an install's tail is accepted batches too
void checkCheckpoint(codec, d, new Uint8Array(), [{ seq: 2, patches: [local], charge: 0 }]);

// A document's checkpoints, the client's side (BH-0 server design r9, 83f3dd5a, §5.2, §5.3, §6.2, §7; the BH-0b-2
// implementation map r2, a5cccbe9, cleared by astra, daybreak2 and the grader).  Pure: no storage, no network; DocSync
// (0b-2b, 0b-2c) is what wires it.  Nothing imports it yet.
//
// - exactCut: the owner's registration rule (§5.2): a graph of exactly the server-accepted prefix through at_seq, its
//   one head the last envelope of batch at_seq.  Only chain-verified accepted batches are taken (the type says so),
//   never a local or unsent row.
// - makeCheckpoint / checkRecord: the blob, a patchflow snapshot record at cut_patch whose `hash` is checked against a
//   fresh hash of its own value (patchflow 0.16 trusts a record with no hash, or one of an unfamiliar format: map r2 C).
// - checkCheckpoint: an install's checks (§8) on the blob and the tail after it, bounded before any graph is built,
//   with what it holds between calls counted and capped (map r2 G as amended for 0b-2a; allocation inside a patchflow
//   call is not bounded here: the TRANSIENT-BUDGET gate).
// - reconcile (§6.2), splitPrefix (§7): the outcome of a registration from the server's answer; a batch cut to fit the
//   rooms a `busy {checkpoint: "split"}` names.
import { PatchGraph, sameHashFormat, type DocCodec, type Document, type Patch } from "patchflow";

/** Patches in a tail at most, and its charged bytes at most (r9 §0, §3; the server's TAIL_PATCHES_CAP, TAIL_ITEM_CAP) */
export const TAIL_PATCHES_CAP = 1000;
export const TAIL_ITEM_CAP = (4 << 20) - (8 << 10);
/** (LIMITS.pullBytes, 4 MiB, less the answer's 8 KiB reserve; a test pins it to protocol.ts's LIMITS.pullBytes, so this
 * module's type-checked import closure stays its own) */
/** A checkpoint blob's bytes at most (r9 §6.4's CANDIDATE_RESERVE: the server reserves no more for one) */
export const CHECKPOINT_BLOB_MAX = 32 << 20;
/** The device's own rows an install takes into its combined graph at most (the journal's per-document debt bounds,
 * journal/rows.js SYNC_DEBT: 10,000 rows, 16 MiB; a test pins them to it) */
export const LOCAL_ROWS_MAX = 10000;
export const LOCAL_BYTES_MAX = 16 << 20;
/** Identical registration requests at most, before the outcome is UNKNOWN (r9 §6.2) */
export const REGISTER_ATTEMPTS = 3;

// ---- accepted history: only what a chain-verified pull page gave

declare const accepted: unique symbol;
/** A batch the server accepted, as a chain-verified pull page gave it: its seq and its patches in envelope order (the
 * last one is the batch's last envelope).  Made only by `acceptedBatch`, from a verified page: a local or unsent row
 * can't be one. */
export interface AcceptedBatch {
  readonly [accepted]: true;
  readonly seq: number;
  readonly patches: readonly Patch[];
  /** the batch's charged bytes (r9 §3), as the server counts them: for the install's bound */
