// nothing else in it opens on the notebook page instead, where what the agent makes opens in place. The code goes within
// this tab only, never in a second URL, so the handover adds no second request, URL or referrer with the code in it; the
// notebook page takes it once, deleting it as it reads, and only while fresh. A module of its own, imported by those two
// pages only, so the other pages' pairing (the LaTeX editor's chunk) carries none of it.
import type { PairLink } from "./pair-link";

export const HANDOFF_KEY = "sb-pair-handoff-v1";
export const HANDOFF_MS = 30_000;
/** Hand `l` over to the notebook page of this tab: true only if it is stored, as read back (else the caller keeps it). */
export function handOver(l: PairLink, now = Date.now()): boolean {
  try {
    const v = JSON.stringify({ code: l.code, port: l.port, at: now });
    sessionStorage.setItem(HANDOFF_KEY, v);
    if (sessionStorage.getItem(HANDOFF_KEY) === v) return true;
    sessionStorage.removeItem(HANDOFF_KEY);
  } catch { /* (no storage: not handed over) */ }
  return false;
}
/** The handed-over link, on the notebook page only (/, its address with no query and no hash), deleted before it is
 * looked at; null if none, stale or malformed. */
export function takeHandoff(path: string, now = Date.now()): PairLink | null {
  if (path !== "/" && path !== "/index.html") return null;
  let v: string | null = null;
  try { v = sessionStorage.getItem(HANDOFF_KEY); if (v !== null) sessionStorage.removeItem(HANDOFF_KEY); } catch { return null; }
  if (v === null) return null;
  try {
    const o = JSON.parse(v);
    if (typeof o?.code !== "string" || !/^[A-Za-z0-9 -]{1,64}$/.test(o.code) || typeof o.port !== "string" || !/^[0-9]{1,5}$/.test(o.port) || typeof o.at !== "number" || !(now - o.at >= 0 && now - o.at < HANDOFF_MS)) return null;
    return { code: o.code, port: o.port };
  } catch { return null; }
}

// A pairing link (?pair=CODE&port=N, as an agent on this computer prints it): read once, when this module is first
// evaluated, and taken out of the address bar at once, so the code doesn't stay on screen, in the history, in a
// bookmark or a copied URL. Pages import this module before anything else that reads or reports the URL.

export type PairLink = { code: string; port: string };

const PARAMS = ["pair", "port"];

function take(): PairLink | null {
  if (typeof location === "undefined") return null;
  const q = new URLSearchParams(location.search);
  if (!q.has("pair")) return null;
  const link = { code: q.get("pair") ?? "", port: q.get("port") ?? "" };
  for (const p of PARAMS) q.delete(p);
  const search = q.toString();
  try {
    history.replaceState(history.state, "", location.pathname + (search ? "?" + search : "") + location.hash);
  } catch { /* (a page that can't rewrite its URL keeps it; the code is still single use, for 5 minutes) */ }
  return link;
}

// (one link per page: a chunk with its own copy of this module (the LaTeX editor's agent chunk, the notebook page's)
// gets the link the page took first, by this key, as the URL no longer has it)
const KEY = Symbol.for("sagebrush.pairLink");
const g = globalThis as any;
let link: PairLink | null = KEY in g ? g[KEY] : (g[KEY] = take());

/** The pairing link this page was opened with, if any (the URL no longer shows it). */
export function pairLink(): PairLink | null {
  return link;
}

/** A link this page was given another way (the board page's handover, pair-handoff.ts): the page's link from now on,
 * for its chunks too, if it had none. */
export function adoptLink(l: PairLink) {
  if (!link) g[KEY] = link = l;
}

// Workspace paths (design/workspace-files.md §2.1): absolute, "/"-separated,
// each name a real one.  A path's kind comes from its name: `.ipynb` a
// notebook, `.board.json` a board, anything else a data file; folders are
// entries of their own.

export type Kind = "notebook" | "board" | "file" | "folder";

/** The bounds of a path (the review's limits): its length, its depth, a name's length. */
export const MAX_PATH = 1024, MAX_DEPTH = 32, MAX_NAME = 255;
/** Where an agent's branches go (git_branch, chat plan PR 3: branch-rules.ts, git-branch.ts). */
export const BRANCHES = "/Branches";
/** The folder deleted entries go to (§2.4). */
export const TRASH = "/Trash";

export class PathError extends Error {}

// (control characters, which no name of a file can hold here)
const CONTROL = /[\u0000-\u001f\u007f]/;

/** `p` as a workspace path, or a PathError saying why it isn't one: no empty
 * names, no "." or "..", no control characters, within the bounds; a
 * trailing "/" is dropped.  "/" itself is the root. */
export function normPath(p: unknown): string {
  if (typeof p !== "string") throw new PathError("a path is a string");
  if (!p.startsWith("/")) throw new PathError(`not an absolute path: ${JSON.stringify(p.slice(0, 80))}`);
  if (p.length > MAX_PATH) throw new PathError(`a path is at most ${MAX_PATH} characters`);
  if (p === "/") return p;
  const names = (p.endsWith("/") ? p.slice(1, -1) : p.slice(1)).split("/");
  if (names.length > MAX_DEPTH) throw new PathError(`a path is at most ${MAX_DEPTH} folders deep`);
  for (const n of names) {
    if (n === "" || n === "." || n === "..") throw new PathError(`not a name in a path: ${JSON.stringify(n)}`);
    if (n.length > MAX_NAME) throw new PathError(`a name is at most ${MAX_NAME} characters`);
    if (CONTROL.test(n)) throw new PathError("a name can't hold control characters");
  }
  return "/" + names.join("/");
}

/** The folder holding `p` ("/" for one at the top). */
export const parentOf = (p: string) => p.slice(0, Math.max(1, p.lastIndexOf("/")));
/** The last name of `p`. */
export const nameOf = (p: string) => p.slice(p.lastIndexOf("/") + 1);
/** `child` in `folder`. */
export const join = (folder: string, child: string) => (folder === "/" ? "" : folder) + "/" + child;
/** Whether `p` is `folder` or inside it. */
export const within = (p: string, folder: string) => folder === "/" || p === folder || p.startsWith(folder + "/");

/** A name's base and extension, `.board.json` as one extension. */
export function splitExt(name: string): [string, string] {
  if (name.toLowerCase().endsWith(".board.json") && name.length > 11) return [name.slice(0, -11), name.slice(-11)];
  const i = name.lastIndexOf(".");
  return i > 0 ? [name.slice(0, i), name.slice(i)] : [name, ""];
}

/** The kind of a document or file by its name (a folder is said by its entry). */
export function kindOf(path: string): Exclude<Kind, "folder"> {
  const n = nameOf(path).toLowerCase();
  if (n.endsWith(".ipynb") && n.length > 6) return "notebook";
  if (n.endsWith(".board.json") && n.length > 11) return "board";
  return "file";
}

