/** The branches, for the chat panel and the review page: every ready branch with its review state. */
export async function listBranches(host: PersonHost): Promise<{ name: string; fid: string; status: ReviewStatus | "open"; title?: string; head?: string; seq?: number; updated: number }[]> {
  const out = [];

// A board's items, base to head, as counts (the review page's board row): each object with a string `id` is an item,
// its signature its own JSON with every item inside it written as its id alone, so each value of the document is
// written into exactly one signature (linear in the document, however its items nest), and the walk keeps its own
// stack (no recursion, however deep).  A signature too deep for JSON.stringify gives no summary: null.

export type BoardCounts = { added: number; removed: number; changed: number; bytes: number };

const isItem = (v: unknown): v is { id: string } => !!v && typeof v === "object" && !Array.isArray(v) && typeof (v as { id?: unknown }).id === "string";

/** Each item's signature, by id; `bytes`: their lengths together (UTF-16 units). Null if one can't be written. */
export function itemSignatures(doc: unknown): { sigs: Map<string, string>; bytes: number } | null {
  const sigs = new Map<string, string>();
  let bytes = 0;
  const stack: unknown[] = [doc];
  while (stack.length) {
    const v = stack.pop();
    if (!v || typeof v !== "object") continue;
    if (isItem(v)) {
      let sig: string;
      // (its own JSON, every item inside it as its id, under any key, the empty one too: only `v` itself is the root;
      //  those are walked as items of their own)
      try { sig = JSON.stringify(v, (_k, x) => (x !== v && isItem(x) ? { "#": x.id } : x)); }
      catch { return null; }
      sigs.set(v.id, sig);
      bytes += sig.length;
    }
    // (only the nearest items are pushed for their own signatures; everything else is inside this one's)
    const kids = Array.isArray(v) ? v : Object.values(v);
    if (isItem(v)) { const inner: unknown[] = [...kids]; while (inner.length) { const x = inner.pop(); if (isItem(x)) stack.push(x); else if (x && typeof x === "object") inner.push(...(Array.isArray(x) ? x : Object.values(x))); } }
    else for (const x of kids) stack.push(x);
  }
  return { sigs, bytes };
}

/** The counts from `a` to `b` (either may be null: no document), or null if a signature can't be written. */
export function boardCounts(a: unknown, b: unknown): BoardCounts | null {
  const x = itemSignatures(a), y = itemSignatures(b);
  if (!x || !y) return null;
  let added = 0, removed = 0, changed = 0;
  for (const [id, s] of y.sigs) { const t = x.sigs.get(id); if (t === undefined) added++; else if (t !== s) changed++; }
  for (const id of x.sigs.keys()) if (!y.sigs.has(id)) removed++;
  return { added, removed, changed, bytes: x.bytes + y.bytes };
}

// A notebook's cells compared, base to head, for the review page: the longest common subsequence of the cells' keys
// (type and code), each cell's key an integer (one Map per cell type, holding the documents' own code strings: no
// copies), the common prefix and suffix first, then one Uint16Array table, checked against its bound before it is
// made.  Cells that differ between two kept ones are paired in order, a deleted with an inserted of the same type:
// one changed cell (its code's line diff is the page's).

export const CELL_LIMITS = Object.freeze({ cells: 2000 });

export type CellKey = { type: string; code: string };
/** unchanged (`=`), changed (`~`, its code differs), deleted (`-`, base's `a`), inserted (`+`, head's `b`) */
export type CellRow = { t: "=" | "~"; a: number; b: number } | { t: "-"; a: number } | { t: "+"; b: number };

/** `rows` with each run of unchanged cells as one fold, its count (the page shows "12 unchanged cells"). */
export function foldRows(rows: CellRow[]): (CellRow | { fold: number; a: number; b: number })[] {
  const out: (CellRow | { fold: number; a: number; b: number })[] = [];
  for (const r of rows) {
    const last = out[out.length - 1];
    if (r.t === "=" && last && "fold" in last) last.fold++;
    else out.push(r.t === "=" ? { fold: 1, a: r.a, b: r.b } : r);
  }
  return out;
}

/** The rows from `base` to `head`, or null past CELL_LIMITS (nothing allocated for the table). */
export function cellDiff(base: CellKey[], head: CellKey[]): CellRow[] | null {
  if (base.length > CELL_LIMITS.cells || head.length > CELL_LIMITS.cells) return null;
  const byType = new Map<string, Map<string, number>>();
  let next = 0;
  const id = (c: CellKey) => {
    let m = byType.get(c.type);
    if (!m) { m = new Map(); byType.set(c.type, m); }
    let v = m.get(c.code);
    if (v === undefined) { v = next++; m.set(c.code, v); }
    return v;
  };
  const A = Int32Array.from(base, id), B = Int32Array.from(head, id);
  byType.clear();
  let pre = 0;
  while (pre < A.length && pre < B.length && A[pre] === B[pre]) pre++;
  let suf = 0;
  while (suf < A.length - pre && suf < B.length - pre && A[A.length - 1 - suf] === B[B.length - 1 - suf]) suf++;
  const n = A.length - pre - suf, m = B.length - pre - suf, w = m + 1;
  // (L[i·w + j]: the LCS of the middle's suffixes from i and j; at most 2000, so 16 bits)
  const L = new Uint16Array((n + 1) * w);
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i * w + j] = A[pre + i] === B[pre + j] ? L[(i + 1) * w + j + 1] + 1 : Math.max(L[(i + 1) * w + j], L[i * w + j + 1]);
  const rows: CellRow[] = [];
  for (let k = 0; k < pre; k++) rows.push({ t: "=", a: k, b: k });
  // (between two kept cells: the deleted and the inserted, in order, paired by type where they meet)
  let dels: number[] = [], ins: number[] = [];
  const flush = () => {
    const k = Math.max(dels.length, ins.length);
    for (let x = 0; x < k; x++) {
      const a = dels[x], b = ins[x];
      if (a !== undefined && b !== undefined && base[a].type === head[b].type) rows.push({ t: "~", a, b });
      else { if (a !== undefined) rows.push({ t: "-", a }); if (b !== undefined) rows.push({ t: "+", b }); }
    }
    dels = []; ins = [];
  };

// How many values a JSON text would make, counted on its bytes before it is parsed (the review page's admission:
// a document of millions of tiny values is refused before JSON.parse makes them).  One pass; outside strings it
// counts each container, each string, and each run of number or literal characters, and subtracts the keys (one
// colon each).  A malformed text gives some count; JSON.parse refuses it after.

export const JSON_LIMITS = Object.freeze({
  /** a submitted document's values */
  full: 400_000,
  /** each side of a notebook diff's (its canonical bytes) */
  side: 40_000,
});

const isTok = (b: number) => (b >= 0x30 && b <= 0x39) || b === 0x2d || b === 0x2b || b === 0x2e || (b >= 0x41 && b <= 0x5a) || (b >= 0x61 && b <= 0x7a);

export function jsonValues(bytes: Uint8Array): number {
  let values = 0, colons = 0, inStr = false, esc = false, inTok = false;
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    if (inStr) {
      if (esc) esc = false;
      else if (b === 0x5c) esc = true;
      else if (b === 0x22) inStr = false;
      continue;
    }
    if (b === 0x22) { inStr = true; values++; inTok = false; }
    else if (b === 0x7b || b === 0x5b) { values++; inTok = false; }
    else if (b === 0x3a) { colons++; inTok = false; }
    else if (isTok(b)) { if (!inTok) { values++; inTok = true; } }
    else inTok = false;
  }
  return values - colons;
}

// The review page's line diff: Myers' O(ND), its own, on lines interned to integers, with every comparison counted
// against a budget.  The editor's lineDiff (web/latex/posmap.ts) is not used and not changed: its trace and string
// comparisons are the editor's bounds, not the review's.
//
// Bounded, before anything is split: each side at most REVIEW_DIFF.sideBytes (UTF-8) and REVIEW_DIFF.sideLines;
// then at most `maxD` edits (the trace is at most (maxD + 1) Int32Arrays of 2·maxD + 3), and at most `budget`
// comparisons of two line ids, counted where they're made: the common prefix and suffix, each frontier step, each
// step of a snake.  Past any of them: { ok: false }, and what the call held is dropped with it.

export const REVIEW_DIFF = Object.freeze({
  /** edits at most */
  maxD: 1000,
  /** comparisons of two line ids, a file at most (a notebook's changed cells share one) */
  budget: 4_000_000,
  /** UTF-8 bytes a side */
  sideBytes: 2 * 2 ** 20,
  /** lines a side */
  sideLines: 50_000,
  /** lines a file's diff shows at most */
