// A data file's versions on the sync server (version-history note r1, PR 1's page side): what the server keeps of it,
// listed under the file preview's own "Earlier versions" (preview.ts), each with Download and Restore.
//   The list: GET /api/sync/v1/versions?fid= (cloud PR #89), read only.  A version's bytes: GET /api/sync/v1/blob/<sha256>
//   (the 303 to a signed URL, followed; debited from the day's read budget as every read), checked against its SHA-256 and
//   size before anything is done with them.  Restore writes them with the workspace's own write, only over the file
//   shown, as it was shown (its fid and revision: the device versions' rule, CORR-F85-2), so the bytes it replaces are
//   kept in turn: a restore can be undone.
import type { Entry, Workspace } from "./api";

export type ServerVersion = { sha256: string; size: number; t: number; by: string; seq: number; path: string };

/** The server's versions of `e` (a synced data file, by its fid), or null where the server can't say (sync off, a
 * page without sync, an error): a list never pretends. */
export async function serverVersions(e: Pick<Entry, "kind" | "fid">, fetchImpl: typeof fetch = fetch): Promise<ServerVersion[] | null> {
  if (e.kind !== "file" || !e.fid || !/^[0-9a-f]{16}$/.test(e.fid)) return null;
  try {
    const r = await fetchImpl(`/api/sync/v1/versions?fid=${e.fid}`, { credentials: "same-origin" });
    if (!r.ok) return null;
    const j = await r.json();
    if (!Array.isArray(j?.versions)) return null;
    return (j.versions as ServerVersion[]).filter((v) => typeof v?.sha256 === "string" && /^[0-9a-f]{64}$/.test(v.sha256) && Number.isSafeInteger(v.size) && v.size >= 0);
  } catch { return null; }
}

const hex = async (b: Uint8Array) => [...new Uint8Array(await crypto.subtle.digest("SHA-256", b as BufferSource))].map((x) => x.toString(16).padStart(2, "0")).join("");

/** A version's bytes from the server, exactly: its size, and its SHA-256, or an Error saying why not. */
export async function serverVersionBytes(v: Pick<ServerVersion, "sha256" | "size">, fetchImpl: typeof fetch = fetch): Promise<Uint8Array> {
  let r: Response;
  try { r = await fetchImpl(`/api/sync/v1/blob/${v.sha256}`, { credentials: "same-origin", redirect: "follow" }); } catch { throw new Error("the server couldn't be reached"); }
  if (r.status === 429) throw new Error("today's download allowance is used up: try again tomorrow");
  if (!r.ok) throw new Error(`the server answered ${r.status}`);
  const b = new Uint8Array(await r.arrayBuffer());
  if (b.length !== v.size || (await hex(b)) !== v.sha256) throw new Error("the bytes that came aren't that version's");
  return b;
}

/** Restore `v` over the file shown (`e`, as it was shown): the server's bytes, checked, written by the workspace. */
export async function restoreServerVersion(w: Workspace, e: Entry, v: ServerVersion, fetchImpl: typeof fetch = fetch): Promise<Entry> {
  const bytes = await serverVersionBytes(v, fetchImpl);
  return (await w.write(e.path, bytes, { base: e.rev ?? 0, fid: e.fid })).entry;
}

// SHA-256 of bytes, lower-case hex: what web/notebook/stores.js's bytesHash computes wherever crypto.subtle exists,
// which the branch store already requires (its object ids are SHA-1, by crypto.subtle). Here, typed, so the branch
// modules need not load stores.js (its own module, checked apart).

export async function sha256Hex(data: Uint8Array): Promise<string> {
  // (the bytes here are never a SharedArrayBuffer's view: as BufferSource, without a copy)
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", data as BufferSource));
  let out = "";
  for (const b of d) out += b.toString(16).padStart(2, "0");
  return out;
}

// The first sync's adoption journal (design/sync-client.md C3; LIMIT-SC1-R1, R3): a device's existing tree captured
// into `adoptJournal` under `<ns>#adopt`, keyed by identity, each record `{id, parent, name, kind, sha256, size,
// trashed}` with its folder's identity (never a path), then sent as `adopt` records through the bounded outbox
// (Outbox.drainJournal, the same drain as a rebuild's reissue journal).  In order, each step resumable from
// `sync:<ns>:adopt`:
//
//   start   one transaction: W0, the latest op, recorded, and the scan watermark set to it (ops after it kept);
//   walk    by identity, through the entries' byIdent index, 500 a transaction with its position: each record the
//           entry's state and the pin on its bytes (C2), owned by the journal until it drains;
//   close   one short transaction holding the workspace's lock: W1, the latest op;
//   replay  the ops in (W0, W1] only, 500 a transaction: each one's identity assigned from its `after` (an
//           assignment: an op the walk already saw is harmless), own intents only (wireOf's rule);
//   done    the last replay page sets the watermark to W1 and makes the journal the active one, the tree as of W1.
//
// The account socket is opened only then (sync-client.ts), so welcome's `index` is applied with the journal in the
// view (layer 2).  The scanner stays idle until the journal has drained.
import type { Entry, Op, Workspace } from "./api";
import { inTx, req } from "./db";
import { entriesOf, type EntriesView } from "./sync-rewrite";
import { TRASH, nameOf, parentOf } from "./paths";
import { wireOf } from "./sync-outbox";
import { pinOfCurrent, pinPresent, type Pin } from "./sync-pins";
import type { JournalRecord } from "./sync-view";

export const ADOPT = {
  /** entries a walk transaction takes at most */
  page: 500,
  /** ops a replay transaction reads at most */
  replayPage: 500,
  /** (tests: awaited before each step: walk, close, replay) */
  before: null as null | ((step: string) => Promise<void>),
};
type State = { step: "walk" | "close" | "replay"; W0: number; W1?: number; at: string | number };
const stateKey = (ns: string) => `sync:${ns}:adopt`;
export const adoptPrefix = (ns: string) => `${ns}#adopt`;
const META = "meta";

/** A journal record of `e`'s present state (its folder's identity, or "" for the root, or for Trash itself). */
async function recordOf(ev: EntriesView, jp: string, e: Entry): Promise<JournalRecord> {
  let parent = "";
  const folder = parentOf(e.path);
  if (!e.trashed && folder !== "/" && folder !== TRASH) parent = (await ev.get(folder))?.fid ?? "";
  return { ns: jp, id: e.ident!, parent, name: nameOf(e.path), kind: e.kind, ...(e.kind === "file" ? { sha256: e.sha256, size: e.size } : {}), trashed: !!e.trashed, ...(e.trashed ? { from: e.trashed.from } : {}) };
}

/** Whether `ns` has begun syncing (its watermark is set) and its adoption, if any, is captured. */
export async function adopted(w: Workspace, ns: string): Promise<boolean> {
  return inTx(w.ws, META, "readonly", async (tx) => {
    const meta = tx.objectStore(META);
    return (await req(meta.get(`sync:${ns}:scanned`))) !== undefined && (await req(meta.get(stateKey(ns)))) === undefined;
  });
}

/** The capture run to its end (each step its own transactions, resumable after a crash). */
export async function capture(w: Workspace, ns: string): Promise<void> {
  // (start: W0 and the watermark, once)
  await inTx(w.ws, [META, "ops"], "readwrite", async (tx) => {
    const meta = tx.objectStore(META);
    if ((await req(meta.get(`sync:${ns}:scanned`))) !== undefined) return;
    const W0 = await new Promise<number>((ok, no) => { const c = tx.objectStore("ops").openKeyCursor(null, "prev"); c.onsuccess = () => ok((c.result?.key as number | undefined) ?? 0); c.onerror = () => no(c.error); });

