const parse = (text: string | null | undefined): Read => {
  if (text === null || text === undefined) return { none: true };
  try {
    const w = JSON.parse(text);
    return isWitness(w) ? { witness: w } : { unreadable: "not a witness" };
  } catch {
    return { unreadable: "not JSON" };
  }
